import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Канон розчулення до Господа нашого Ісуса Христа","e":"Canon of compunction to our Lord Jesus Christ","secs":[{"h":"Глас 2. Пісня 1","ps":["Ірмос: Во глубині́ постла́ іногда́ фараони́тськоє всево́їнство преоруже́нная си́ла, вопло́щшеєся же Сло́во всезло́бний гріх потреби́ло єсть: препросла́вленний Госпо́дь, сла́вно бо просла́вися.","Приспів: Ісу́се Сладча́йший, спаси́ м'я.","Або: Го́споди Ісу́се Христе́, Си́не Бо́жий, поми́луй м'я грі́шнаго.","Ісу́се Сладча́йший Христе́, Ісу́се долготерпіли́ве, душі́ моєя́ я́зви ісціли́, Ісу́се, і услади́ се́рдце моє́, Многоми́лостиве, молю́ся, Ісу́се Спа́се мой, да велича́ю Тя, спаса́ємий.","Приспів: Ісу́се Сладча́йший, спаси́ м'я.","Або: Го́споди Ісу́се Христе́, Си́не Бо́жий, поми́луй м'я грі́шнаго.","Ісу́се Сладча́йший Христе́, Ісу́се, отве́рзи покая́нія мі двер, человіколю́бче Ісу́се, і прийми́ м'я, Тебі́ припа́дающа і те́плі прося́ща, Ісу́се Спа́се мой, согріше́ній проще́нія.","Слава: Ісу́се Сладча́йший Христе́, Ісу́се, ісхити́ м'я із руки́ льсти́ваго велія́ра, Ісу́се, і сотвори́ десна́го предстоя́теля сла́ви Твоєя́, Ісу́се Спа́се мой, ча́сти шу́їя м'я ізбавля́яй.","І нині: Ісу́са ро́ждшая Бо́га, Влади́чице, моли́ о непотре́бних рабі́х, Пречи́стая, я́ко да му́ки моли́твами Твої́ми ізба́вимся, Нескве́рная, оскверне́ннії, сла́ви присносу́щния наслажда́ющеся."]},{"h":"Пісня 3","ps":["Ірмос: На ка́мені м'я ві́ри утверди́в, разшири́л єси́ уста́ моя́ на враги́ моя́. Возвесели́ бо ся дух мой, внегда́ пі́ти: ність свят, я́коже Бог наш, і ність пра́веден па́че Тебі́, Го́споди.","Приспів: Ісу́се Сладча́йший, спаси́ м'я.","Або: Го́споди Ісу́се Христе́, Си́не Бо́жий, поми́луй м'я грі́шнаго.","Усли́ши, человіколю́бче Ісу́се мой, раба́ Твоєго́, вопію́ща во умиле́нії, і ізба́ви м'я, Ісу́се, осужде́нія і му́ки, єди́не долготерпіли́ве, Ісу́се Сладча́йший многоми́лостиве.","Приспів: Ісу́се Сладча́йший, спаси́ м'я.","Або: Го́споди Ісу́се Христе́, Си́не Бо́жий, поми́луй м'я грі́шнаго.","Подими́ раба́ Твоєго́, Ісу́се мой, припа́дающа со слеза́ми, Ісу́се мой, і спаси́, Ісу́се мой, ка́ющагося м'я і геє́нни, Влади́ко, ізба́ви, Ісу́се Сладча́йший многоми́лостиве.","Слава: Вре́м'я, Ісу́се мой, є́же дал мі єси́, во стра́сті іжди́х, Ісу́се мой. Ті́мже, Ісу́се мой, не отве́ржи м'я, но воззови́, молю́ся, Влади́ко Ісу́се Сладча́йший, і спаси́.","І нині: Ді́во, ро́ждшая Ісу́са моєго́, моли́ ізба́вити м'я геє́нни, єди́но предста́тельство оскорбля́ємих, Богоблагода́тная, і сподо́би м'я жи́зні, Всенепоро́чная, нестарі́ющіяся.","Го́споди, поми́луй. (тричі)"]},{"h":"Сідален, глас 1","ps":["Спа́се мой Ісу́се, блу́днаго спаси́й, Спа́се мой Ісу́се, приє́мий блудни́цю, і мене́ ни́ні поми́луй, Ісу́се многоми́лостиве, спаси́, уще́дри, о Ісу́сі благоді́телю, я́коже, Благоутро́бне, Манассі́ю, Ісу́се мой, я́ко Єди́н человіколю́бець.","Сла́ва, і ни́ні: Моли́тви Свої́х раб прийми́, Богоро́дице, і ізба́ви ни от вся́кия біди́, я́ко ро́ждшая Христа́ Спа́са, ізба́вителя душ на́ших."]},{"h":"Пісня 4","ps":["Ірмос: Прише́л єси́ от Ді́ви, не хода́тай, ні А́нгел, но Сам, Го́споди, вопло́щся, і спасл єси́ всего́ м'я челові́ка. Тім зову́ Ті: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Ісу́се Сладча́йший, спаси́ м'я.","Або: Го́споди Ісу́се Христе́, Си́не Бо́жий, поми́луй м'я грі́шнаго.","Ісціли́, Ісу́се мой, душі́ моєя́ я́зви, Ісу́се мой, молю́ся, і руки́ м'я ісхити́, Ісу́се мой благоутро́бне, душетлі́ннаго велія́ра, і спаси́.","Приспів: Ісу́се Сладча́йший, спаси́ м'я.","Або: Го́споди Ісу́се Христе́, Си́не Бо́жий, поми́луй м'я грі́шнаго.","Согріши́х, Ісу́се мой Сладча́йший, благоутро́бне; Ісу́се мой, спаси́ м'я, прибіга́ющаго к покро́ву Твоєму́, Ісу́се долготерпіли́ве, і Ца́рствія Твоєго́ м'я сподо́би.","Слава: Нікто́же согріши́, Ісу́се мой, я́коже согріши́х аз, окая́нний, но припа́даю моля́ся, Ісу́се мой, спаси́ м'я і жи́зні, Ісу́се мой, наслі́діє мі да́руй.","І нині: Всепі́тая, Ісу́са ро́ждшая Го́спода, Того́ моли́ ізба́вити му́ки вся, пою́щия Тя, і Богоро́дицю воі́стинну імену́ющия."]},{"h":"Пісня 5","ps":["Ірмос: Просвіще́ніє во тьмі лежа́щих, спасе́ніє отча́янних, Христе́ Спа́се мой, к Тебі́ у́тренюю, Царю́ ми́ра, просвіти́ м'я сія́нієм Твої́м: іно́го бо ра́зві Тебе́ бо́га не зна́ю.","Приспів: Ісу́се Сладча́йший, спаси́ м'я.","Або: Го́споди Ісу́се Христе́, Си́не Бо́жий, поми́луй м'я грі́шнаго.","Ти просвіще́ніє, Ісу́се мой, ума́ моєго́, Ти спасе́ніє отчая́нния душі́ моєя́, Спа́се, Ти, Ісу́се мой, му́ки ізба́ви і геє́нни м'я, зову́ща: спаси́, Ісу́се мой Христе́, м'я окая́ннаго.","Приспів: Ісу́се Сладча́йший, спаси́ м'я.","Або: Го́споди Ісу́се Христе́, Си́не Бо́жий, поми́луй м'я грі́шнаго.","Всеконе́чно, Ісу́се мой, ко стра́сті безче́стія низве́ржен ни́ні зову́: Ти, Ісу́се мой, по́мощі мі ру́ку низпосла́в, істо́ргни зову́ща: спаси́, Ісу́се мой Христе́, м'я окая́ннаго.","Слава: Оскверне́н ум, Ісу́се мой, обнося́, взива́ю Ті: очи́сти м'я от скве́рни прегріше́ній і ізба́ви м'я во глубини́ зло́би от неві́дінія низпопо́лзшагося, Спа́се Ісу́се мой, і спаси́ м'я, молю́ся.","І нині: Ісу́са ро́ждшая, Отрокови́це Богороди́тельнице, Того́ умоли́ спасти́ вся правосла́вния, мона́хи і мирськи́я, і геє́нни ізба́вити зову́щия: ра́зві Тебе́ предста́тельства тве́рдаго не зна́єм."]},{"h":"Пісня 6","ps":["Ірмос: В бе́здні гріхо́вній валя́яся, неізслі́дную милосе́рдія Твоєго́ призива́ю бе́здну: от тлі, Бо́же, м'я возведи́.","Приспів: Ісу́се Сладча́йший, спаси́ м'я.","Або: Го́споди Ісу́се Христе́, Си́не Бо́жий, поми́луй м'я грі́шнаго.","Ісу́се мой Христе́ многоми́лостиве, іспові́дающася прийми́ м'я, Влади́ко, о Ісу́сі, і спаси́ м'я, і от тлі, Ісу́се, м'я ісхити́.","Приспів: Ісу́се Сладча́йший, спаси́ м'я.","Або: Го́споди Ісу́се Христе́, Си́не Бо́жий, поми́луй м'я грі́шнаго.","Ісу́се мой, нікто́же бисть ін блудни́к, я́коже аз, стра́стний, о Ісу́сі человіколю́бче: но Ти, Ісу́се, м'я спаси́.","Слава: Ісу́се мой, блудни́цю і блу́днаго, і Манассі́ю і митаря́ прейдо́х, о Ісу́сі мой, страстьми́, і разбо́йника, Ісу́се, і ніневи́тяни.","І нині: Ісу́са Христа́ моєго́ ро́ждшая, Пречи́стая Ді́во, єди́на нескве́рная, оскверне́на су́ща м'я моли́тв Твої́х іссо́пом ни́ні очи́сти.","Го́споди, поми́луй. (тричі) Сла́ва, і ни́ні:"]},{"h":"Кондак, глас 6","ps":["Ісу́се Спа́се, очи́сти і спаси́ м'я, я́коже іногда́ блудни́цю, разбо́йника же і блу́днаго, і мене́ ни́ні поми́луй, Всеще́дре і Благосе́рде Го́споди, і му́ки ізба́ви м'я, моли́твами Пречи́стия Твоєя́ і Всепі́тия Ма́тере."]},{"h":"Ікос","ps":["Земна́я і вре́менная возлюби́х, ві́чних благ лиши́хся, Христе́ Ісу́се, Єди́не человіколю́бче, грі́шников не отсека́ємая наде́жда, но ми́лость ка́ющимся пролія́, і мене́ ни́ні ка́ющася не пре́зри, Ісу́се, разумі́ю бо разбо́йника іспові́данієм спасе́на, і митаря́ ми́лостію очи́щена, та́ко і блудни́цю помишля́ю пла́кавшуся, я́ко всім сих положи́л єси́ о́брази покая́нія. Прети́ши бо ми́лостивне, і милосе́рдуєши. Те́плі ка́ющася ви́диши, і проти́ву тече́ши я́ко Оте́ць. А́ще у́бо восхо́щеши, мо́щен бо єси́ і моя́ отпусти́ти гріхи́, і́миже по креще́ннем обі́ті оскверни́хся, но чистоту́ я́ко Бог пода́ждь мі, моли́твами Пречи́стая Твоєя́ і Всепі́тия Ма́тере."]},{"h":"Пісня 7","ps":["Ірмос: О́бразу злато́му на по́лі Деї́рі служи́му, тріє́ Твої́ о́троци небрего́ша безбо́жнаго велі́нія, посреді́ же огня́ вве́ржені, ороша́ємі поя́ху: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Ісу́се Сладча́йший, спаси́ м'я.","Або: Го́споди Ісу́се Христе́, Си́не Бо́жий, поми́луй м'я грі́шнаго.","Христе́ Ісу́се, нікто́же согріши́ на землі́ от ві́ка, о Ісу́сі мой, я́коже согріши́х аз, окая́нний і блу́дний. Ті́мже, Ісу́се мой, вопію́ Ті: пою́ща м'я уще́дри, благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Ісу́се Сладча́йший, спаси́ м'я.","Або: Го́споди Ісу́се Христе́, Си́не Бо́жий, поми́луй м'я грі́шнаго.","Христе́ Ісу́се, ко стра́ху Твоєму́, вопію́, пригвозди́ м'я, о Ісу́сі мой, і окорми́ ни́ні ко приста́нищу благооти́шному, я́ко да, Ісу́се мой ще́дре, пою́ Ті спаса́ємий: благослове́н єси́, Бо́же оте́ць на́ших.","Слава: Христе́ Ісу́се, тьма́ми обіща́х Тебі́, стра́стний, о Ісу́сі мой, покая́ніє, но солга́х окая́нний. Ті́мже, Ісу́се мой, вопію́ Ті: нечу́вственні пребива́ющую ду́шу мою́ просвіти́, Христе́, отце́в Бо́же благослове́н єси́.","І нині: Христа́ Ісу́са ро́ждшая стра́нно і па́че єстества́, Того́ моли́, Всенепоро́чная, я́же чрез єстество́ моя́ прегріше́нія вся прости́ти мі, Отрокови́це, да зову́ спаса́єм: благослове́нна єси́, Бо́га пло́тію ро́ждшая."]},{"h":"Пісня 8","ps":["Ірмос: В пещ о́гненную ко отроко́м євре́йським снизше́дшаго і пла́мень в ро́су прело́жшаго Бо́га, по́йте, діла́, я́ко Го́спода, і превозносі́те во вся ві́ки.","Приспів: Ісу́се Сладча́йший, спаси́ м'я.","Або: Го́споди Ісу́се Христе́, Си́не Бо́жий, поми́луй м'я грі́шнаго.","Тя, Ісу́се мой, молю́: я́коже блудни́цю, Ісу́се мой, ізба́вил єси́ мно́гих согріше́ній, та́ко і мене́, Ісу́се Христе́ мой, ізба́ви, і очи́сти оскверне́нную ду́шу мою́, Ісу́се мой.","Приспів: Ісу́се Сладча́йший, спаси́ м'я.","Або: Го́споди Ісу́се Христе́, Си́не Бо́жий, поми́луй м'я грі́шнаго.","Преклони́вся, Ісу́се, безслове́сними сластьми́, безслове́сен яви́хся і ското́м воі́стину, Ісу́се мой, стра́стно окая́нний уподо́бихся; ті́мже, Ісу́се, безслове́сія м'я ізба́ви.","Слава: Впад, о Ісу́сі, в душетлі́нния разбо́йники, обнажи́хся оде́жди, Ісу́се мой, боготка́нния ни́ні, і лежу́ ра́нами уя́звлен; єле́й, Христе́ мой, возле́й на м'я і вино́.","І нині: Ісу́са моєго́ і Бо́га носи́вшая Христа́ несказа́нно, Богоро́дице Марі́є, Того́ моли́ при́сно от бід спасти́ся рабо́м Твої́м, і півце́м Твої́м, Неіскусому́жная Ді́во."]},{"h":"Пісня 9","ps":["Ірмос: От Бо́га Бо́га Сло́ва, неізрече́нною му́дростію прише́дшаго обнови́ти Ада́ма, я́дію в тлі́ніє па́дшаго лю́ті, от Святи́я Ді́ви неізрече́нно воплоти́вшагося нас ра́ди, ві́рнії єдиному́дренно пі́сньми велича́єм.","Приспів: Ісу́се Сладча́йший, спаси́ м'я.","Або: Го́споди Ісу́се Христе́, Си́не Бо́жий, поми́луй м'я грі́шнаго.","Манассі́ю, Ісу́се мой, митаря́, блудни́цю, блу́днаго, ще́дре Ісу́се, і разбо́йника прейдо́х, Ісу́се мой, в ді́ліх сту́дних і безмі́стних, Ісу́се; но Ти, Ісу́се мой, предвари́в, м'я спаси́.","Приспів: Ісу́се Сладча́йший, спаси́ м'я.","Або: Го́споди Ісу́се Христе́, Си́не Бо́жий, поми́луй м'я грі́шнаго.","От Ада́ма, Ісу́се мой, согреши́вшия вся, пре́жде зако́на і в зако́ні, Ісу́се, і по зако́ні, окая́нний, і благода́ті, Ісу́се мой, побіди́х страстьми́ окая́нно; но Ти, Ісу́се мой, судьба́ми Твої́ми спаси́ м'я.","Слава: Да не отлуче́н бу́ду, Ісу́се мой, неізрече́нния Твоєя́ сла́ви, да не улучу́ ча́сти, Ісу́се, шу́їя, Сладча́йший Ісу́се; но Ти м'я десни́м овця́м Твої́м, Христе́ Ісу́се мой, сочета́в упоко́й, я́ко благоутро́бен.","І нині: Ісу́са, Богоро́дице, Єго́же носи́ла єси́, єди́на неіскусому́жная Ді́во Марі́є, Того́, Чи́стая, уми́лостиви, я́ко Си́на Твоєго́ і Зижди́теля, ізба́вити притека́ющия к Тебі́ іскуше́ній і бід, і огня́ бу́дущаго."]},{"h":"Молитва","ps":["Влади́ко Го́споди Ісу́се Христе́ Бо́же наш, І́же неізрече́ннаго ра́ди Твоєго́ человіколю́бія на коне́ць віко́во в плоть оболки́йся от Присноді́ви Марі́ї, сла́вим о нас Твоє́ спаси́тельноє промишле́ніє раби́ Твої́, Влади́ко; пісносло́вим Тя, я́ко Тебе́ ра́ди Отця́ позна́хом; благослови́м Тя, Єго́же ра́ди і Дух Святи́й в мир приї́де, поклоня́ємся Твоє́й по пло́ті Пречи́стій Ма́тері, такові́й стра́шній та́йні послужи́вшей; восхваля́єм Твоя́ А́нгельськая ликостоя́нія, я́ко воспіва́телі і служи́телі Твоєго́ вели́чествія; ублажа́єм Предте́чу Іоа́нна, Тебі́ крести́вшаго, Го́споди; почита́єм і провозвести́вшия Тя проро́ки, прославля́єм апо́столи Твоя́ святи́я; торжеству́єм же і му́ченики, свяще́нники же Твоя́ сла́вим; поклоня́ємся преподо́бним Твої́м, і вся Твоя́ пра́ведники пе́снствуєм. Такова́го і толи́каго мно́гаго і неізрече́ннаго ли́ка Боже́ственнаго в моли́тву приво́дим Тебі́, всеще́дрому Бо́гу, раби́ Твої́, і сего́ ра́ди про́сим на́шим согріше́нієм проще́ніє, є́же да́руй нам всіх Твої́х Ра́ди святи́х, ізря́дніє же святи́х Твої́х щедро́т, я́ко благослове́н єси́ во ві́ки. Амі́нь."]}],"notes":[]},{"u":"Канон за одного спочилого","e":"Canon for one departed","secs":[{"h":"Канон за померлого (одного)","ps":["Моли́твами святи́х оте́ць на́ших, Го́споди Ісу́се Христе́ Бо́же наш, поми́луй нас. Амі́нь.","Святи́й Бо́же, Святи́й крі́пкий, Святи́й безсме́ртний, поми́луй нас. (Читається тричі, з хресним знаменням і поясним поклоном.)","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","Пресвята́я Тро́йце, поми́луй нас; Го́споди, очи́сти гріхи́ на́ша; Влади́ко, прости́ беззако́нія на́ша; Святи́й, посіти́ і ісціли́ не́мощі на́ша, і́мене Твоєго́ ра́ди.","Го́споди, поми́луй. (тричі)","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","О́тче наш, І́же єси́ на небесі́х, да святи́ться і́м'я Твоє́, да при́йдеть Ца́рствіє Твоє́, да бу́деть во́ля Твоя́, я́ко на небесі́ і на землі́. Хліб наш насу́щний даждь нам днесь; і оста́ви нам до́лги на́ша, я́коже і ми оставля́єм должнико́м на́шим; і не введи́ нас во іскуше́ніє, но ізба́ви нас от лука́ваго.","Го́споди, поми́луй. (12 разів)","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","Прийді́те, поклоні́мся Царе́ві на́шему Бо́гу. (поклін)","Прийді́те, поклоні́мся і припаде́м Христу́, Царе́ві на́шему Бо́гу. (поклін)","Прийді́те, поклоні́мся і припаде́м Самому́ Христу́, Царе́ві і Бо́гу на́шему. (поклін)"]},{"h":"Псалом 90","ps":["Живи́й в по́мощі Ви́шняго, в кро́ві Бо́га небе́снаго водвори́ться. Рече́ть Го́сподеві: засту́пник мой єси́ і прибі́жище моє́, Бог мой, і упова́ю на Него́. Я́ко Той ізба́вить тя от сі́ті ло́вчі, і от словесе́ м'яте́жна. Плещма́ Свої́ма осіни́ть тя, і под крилі́ Єго́ наді́єшися, ору́жієм оби́деть тя і́стина Єго́. Не убої́шися от стра́ха нощна́го, от стрі́ли летя́щия во дні, от ве́щі во тьмі преходя́щия, от сря́ща і бі́са полу́деннаго. Паде́ть от страни́ твоєя́ ти́сяща, і тьма одесну́ю тебе́, к тебі́ же не прибли́житься. Оба́че очи́ма твої́ма смо́триши і воздая́ніє грі́шников у́зриши. Я́ко Ти, Го́споди, упова́ніє моє́; Ви́шняго положи́л єси́ прибі́жище твоє́. Не при́йдеть к тебі́ зло, і ра́на не прибли́житься тілесі́ твоєму́. Я́ко А́нгелом Свої́м запові́сть о тебі́, сохрани́ти тя во всіх путеіх твої́х. На рука́х во́зьмуть тя, да не когда́ преткне́ши о ка́мень но́гу твою́. На а́спида і васили́ска насту́пиши, і попере́ши льва і змі́я. Я́ко на М'я упова́, і ізба́влю ї: покри́ю ї, я́ко позна́ і́м'я Моє́. Воззове́ть ко Мні, і усли́шу єго́, с ним єсьм в ско́рбі, ізму́ єго́ і просла́влю єго́, долгото́ю дній іспо́лню єго́ і явлю́ єму́ спасе́ніє Моє́.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","Аллилу́я, аллилу́я, аллилу́я, сла́ва Тебі́, Бо́же. (тричі)","Го́споди, поми́луй. (тричі)"]},{"h":"Тропар, глас 8","ps":["Глубино́ю му́дрости человіколю́біє вся стро́яй і поле́зная всім подава́яй, Єди́не Соді́телю, упоко́й, Го́споди, ду́ші раб Твої́х, на Тя бо упова́ніє возложи́ша, Творця́ і Зижди́теля і Бо́га на́шего.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","Богородичен: Те́бі і сті́ну, і приста́нище і́мами, і моли́твенницю благоприя́тну к Бо́гу, Єго́же родила́ єси́, Богоро́дице Безневі́стная, ві́рних спасе́ніє."]},{"h":"Псалом 50","ps":["Поми́луй м'я, Бо́же, по вели́цій ми́лості Твоє́й, і по мно́жеству щедро́т Твої́х очи́сти беззако́ніє моє́. Найпа́че оми́й м'я от беззако́нія моєго́, і от гріха́ моєго́ очи́сти м'я. Я́ко беззако́ніє моє́ аз зна́ю, і гріх мой предо мно́ю єсть ви́ну. Те́бі єди́ному согріши́х і лука́воє пред Тобо́ю сотвори́х, я́ко да оправди́шися во словесі́х Твої́х і побіди́ши, внегда́ суди́ти Ті. Се бо, в беззако́ніїх зача́т єсьм, і во грісі́х роди́ м'я ма́ти моя́. Се бо, і́стину возлюби́л єси́, безві́стная і та́йная прему́дрости Твоє́й яви́л мі єси́. Окропи́ши м'я іссо́пом, і очи́щуся, оми́єши м'я, і па́че сні́га убілю́ся. Слу́ху моєму́ да́си ра́дость і весе́ліє, возра́дуються ко́сті смире́нния. Отврати́ лице́ Твоє́ от гріх мої́х, і вся беззако́нія моя́ очи́сти. Се́рдце чи́сто сози́жди во мні, Бо́же, і дух прав обнови́ во утро́бі моє́й. Не отве́ржи мене́ от лиця́ Твоєго́, і Ду́ха Твоєго́ Свята́го не отими́ от мене́. Возда́ждь мі ра́дость спасе́нія Твоєго́ і Ду́хом влади́чним утверди́ м'я. Научу́ беззако́нния путе́м Твої́м, і нечести́вії к Тебі́ обратя́ться. Ізба́ви м'я от крове́й, Бо́же, Бо́же спасе́нія моєго́, возра́дується язи́к мой пра́вді Твоє́й. Го́споди, устні́ мой отве́рзеши, і уста́ моя́ возвістя́ть хвалу́ Твою́. Я́ко а́ще би восхоті́л єси́ же́ртви, дал бих у́бо, всесожже́нія не благоволи́ши. Же́ртва Бо́гу дух сокруше́н, се́рдце сокруше́нно і смире́нно Бог не унічижи́ть. Ублажи́, Го́споди, благоволе́нієм Твої́м Сіо́на, і да сози́ждуться сті́ни Ієрусали́мськія. Тогда́ благоволи́ши же́ртву пра́вди, возноше́ніє і всесожега́ємая, тогда́ возложа́ть на олта́р Твой тельці́."]},{"h":"Глас 8. Пісня 1","ps":["Ірмос: Во́ду проше́д, я́ко су́шу, і єги́петськаго зла ізбіжа́в, ізра́їльтянин вопія́ше Ізба́вителю і Бо́гу на́шему пої́м.","Приспів: Поко́й, Го́споди, ду́шу усо́пшаго раба́ Твоєго́.","Отве́рз уста́ моя́, Спа́се, сло́во мі пода́ждь моли́тися, Милосе́рде, о преста́вленнем рабі́ Твоє́м, і́м'ярік, да поко́їши ду́шу єго́, Влади́ко.","Приспів: Поко́й, Го́споди, ду́шу усо́пшаго раба́ Твоєго́.","Мертв бив пло́тію, Спа́се, і во гро́бі положе́н с ме́ртвими, ду́шу раба́ Твоєго́ поко́й в мі́сті зла́чні, я́ко Милосе́рд.","Слава: Моле́бний глас мой усли́ши, Бо́же Трийпоста́сне, і учини́ ду́шу преста́вленнаго в ні́дріх Авраа́млих, Ізба́вителю.","І нині: Ти, Пречи́стая Богоро́дице, Єго́же без і́скуса му́жеська заче́нши родила́ єси́, моли́ Си́на Твоєго́ пода́ти поко́й рабу́ Твоєму́ преста́вленному, (і́м'ярік)."]},{"h":"Пісня 3","ps":["Ірмос: Небе́снаго кру́га Верхотво́рче, Го́споди, і Це́ркве Зижди́телю, Ти мене́ утверди́ в любві́ Твоє́й, жела́ній кра́ю, ві́рних утвержде́ніє, Єди́не Человіколю́бче.","Приспів: Поко́й, Го́споди, ду́шу усо́пшаго раба́ Твоєго́.","В мі́сті зла́чні, в мі́сті поко́йні, іді́же ли́ци святи́х веселя́ться, ду́шу раба́ Твоєго́ преста́вленнаго поко́й, Христе́, Єди́не Ми́лостиве.","Приспів: Поко́й, Го́споди, ду́шу усо́пшаго раба́ Твоєго́.","Іді́же ли́ци святи́х, та́мо вчини́, Влади́ко, послужи́вшаго Тебі́ всім се́рдцем і воздви́гшаго і́го Твоє́ на ра́мо своє́, я́ко Єди́н Влади́ка живота́ і сме́рті.","Слава: Небе́сний О́тче Вседержи́телю, і Си́не Єдиноро́дний, і Ду́ше Святи́й Ісхо́дний, пре́зри уме́ршаго согріше́нія, і в Це́ркві пе́рвенець всели́ єго́, сла́вити Тя со всі́ми уго́ждшими Тебі́.","І нині: Я́ко Ма́ти Свята́я Пресвята́го Бо́га, Влади́чице вся́чеських, Марі́є Богоро́дице, со всі́ми святи́ми Сего́ моли́ ду́шу поко́іти раба́ Твоєго́ в Небе́сних селе́ніїх.","Го́споди, поми́луй (Три́жди)"]},{"h":"Сідален, глас 5","ps":["Поко́й, Спа́се наш, с пра́ведними раба́ Твоєго́, і сего́ всели́ во двори́ Твоя́, я́коже єсть пи́сано, презира́я, я́ко благ, прегріше́нія єго́ во́льная і нево́льная, і вся я́же во ві́дінії і не во ві́дінії, Человіколю́бче.","Сла́ва, і ни́ні: Богоро́дичен: От Ді́ви возсія́вий ми́ру, Христе́ Бо́же, си́ни сві́та То́ю показа́вий, поми́луй нас."]},{"h":"Пісня 4","ps":["Ірмос: Усли́шах, Го́споди, смотре́нія Твоєго́ та́їнство, разумі́х діла́ Твоя́ і просла́вих Твоє́ Божество́.","Приспів: Поко́й, Го́споди, ду́шу усо́пшаго раба́ Твоєго́.","Соше́дий в преіспо́дняя, Христе́, совоздви́гл єси́ уме́ршія вся, і преста́вльшагося от нас поко́й, Спа́се, я́ко щедр.","Приспів: Поко́й, Го́споди, ду́шу усо́пшаго раба́ Твоєго́.","Нікто́же без гріха́ єсть, то́кмо Ти Єди́н, Влади́ко: сего́ ра́ди преста́вленному і гріхи́ оста́ви, і в рай того́ всели́.","Слава: Усли́ши, Тро́йце Свята́я, гла́си моле́бния, приноси́мия Тебі́ в це́ркві о усо́пшем, і Богонача́льним Твої́м сві́том озари́ ду́шу, омраче́нную су́єтними приверже́нії.","І нині: Родила́ єси́, Пречи́стая, без му́жеська сі́мене, Бо́га соверше́нна і Челові́ка соверше́нна, взе́млющаго гріхи́ на́ша, Ді́во. Того́ моли́, Госпоже́, преста́вльшемуся рабу́ Твоєму́ пода́ти поко́й."]},{"h":"Пісня 5","ps":["Ірмос: Просвіти́ нас повелі́нії Твої́ми, Го́споди, і ми́шцею Твоє́ю висо́кою Твой мир пода́ждь нам, Человіколю́бче.","Приспів: Поко́й, Го́споди, ду́шу усо́пшаго раба́ Твоєго́.","Іми́й живота́ і сме́рті власть, преста́вленнаго от нас поко́й, Христе́ Бо́же, Ти бо єси́ всіх, Спа́се, поко́й і живо́т.","Приспів: Поко́й, Го́споди, ду́шу усо́пшаго раба́ Твоєго́.","На Тя, Спа́се, наде́жду возло́ж, уме́рий оти́де от нас; Ти же, Го́споди, уще́дри єго́, я́ко Бог Многоми́лостив.","Слава: Просвіти́ нас, Трисвя́те, воспіва́ємий Влади́ко, моля́щихся Тебі́, мир небе́сний прия́ти, і в ми́рних се́ліх ду́шу вчини́, отше́дшую от вре́менних в наде́жді безконе́чния жи́зні.","І нині: Шу́їяго стоя́нія, Пречи́стая, ізба́вити преста́вленнаго умоли́ Си́на Твоєго́, Ді́во Госпоже́, я́ко Спа́са і Бо́га на́шего Ма́ти су́щая."]},{"h":"Пісня 6","ps":["Ірмос: Моли́тву пролію́ ко Го́споду, і Тому́ возвіщу́ печа́лі моя́, я́ко зол душа́ моя́ іспо́лнися і живо́т мой а́ду прибли́жися, і молю́ся, я́ко Іо́на: от тлі, Бо́же, возведи́ м'я.","Приспів: Поко́й, Го́споди, ду́шу усо́пшаго раба́ Твоєго́.","А́да іспрове́рг, Влади́ко, воскреси́л єси́ уме́ршія от ві́ка: і ни́ні преста́вленнаго от нас, в ні́дро Авраа́мле Ти, Бо́же, всели́, прегріше́нія вся отпусти́в, я́ко Милосе́рд.","Приспів: Поко́й, Го́споди, ду́шу усо́пшаго раба́ Твоєго́.","За́повідь, ю́же мі дал єси́, Бо́же, преступи́х і сме́ртен бих, но Ти, Бо́же, соше́дий во гроб і ду́ші я́же от ві́ка воскреси́вий, не возста́ви мене́, Влади́ко, на муче́ніє, но на поко́й, преста́вленний вопіє́ть Тебі́ с на́ми, Многоми́лостиве.","Слава: Мо́лим Тя, Безнача́льне О́тче і Си́не і Ду́ше Святи́й, зло́бою душезло́бнаго ми́ра озло́бленную і к Тебі́, Зижди́телю, преше́дшую ду́шу во а́дово дно не отри́ни, Бо́же Спа́се мой.","І нині: С небесе́ Христо́с Бог наш, я́ко дождь на руно́, Пречи́стая, сни́де на Тя, напая́я весь мир і ізсуша́я вся безбо́жния пото́ки, наводня́яй всю зе́млю ра́зумом Свої́м, Присноді́во; Того́ моли́ да́ти поко́й преста́вленному рабу́ Твоєму́."]},{"h":"Кондак, глас 8","ps":["Со святи́ми упоко́й, Христе́, ду́шу раба́ Твоєго́, іді́же ність болі́знь, ні печа́ль, ні воздиха́ніє, но жизнь безконе́чная."]},{"h":"Ікос","ps":["Сам Єди́н єси́ Безсме́ртний, сотвори́вий і созда́вий челові́ка: земні́ї у́бо от землі́ созда́хомся і в зе́млю ту́южде по́йдем, я́коже повелі́л єси́, созда́вий м'я і реки́й мі: я́ко земля́ єси́ і в зе́млю оти́деши, а́може всі челові́ци по́йдем, надгро́бноє рида́ніє творя́ще піснь: аллилу́я, аллилу́я, аллилу́я."]},{"h":"Пісня 7","ps":["Ірмос: От Іуде́ї доше́дше о́троци, во Вавило́ні іногда́, ві́рою Тро́йчеською пла́мень пе́щний попра́ша, пою́ще: отце́в Бо́же, благослове́н єси́.","Приспів: Поко́й, Го́споди, ду́шу усо́пшаго раба́ Твоєго́.","Влади́ко Христе́ Бо́же, єгда́ хо́щеши суди́ти ми́ру, пощади́ ду́шу раба́ Твоєго́, єго́же от нас прия́л єси́, вопію́щаго: оте́ць на́ших Бо́же, благослове́н єси́.","Приспів: Поко́й, Го́споди, ду́шу усо́пшаго раба́ Твоєго́.","В пи́щі ра́йстій, іді́же пра́ведних ду́ші веселя́ться, послужи́вших Тебі́, причти́ с ни́ми, Христе́, ду́шу раба́ Твоєго́, воспі́вшаго: оте́ць на́ших Бо́же, благослове́н єси́.","Слава: Іуде́йськия три о́троки спаси́й во огні́, в Тріє́х Ли́ціх воспі́тий, ізба́ви огня́ ві́чнаго усо́пшаго, воспі́вшаго Ті ві́рно: оте́ць на́ших Бо́же, благослове́н єси́.","І нині: Влади́ку Христа́ ро́ждшая всіх Бо́га, вла́сті те́мния возду́шнаго кня́зя ізба́ви, Ді́во, ду́шу преста́вльшагося во ві́рі і воспі́вшаго: оте́ць на́ших Бо́же, благослове́н єси́."]},{"h":"Пісня 8","ps":["Ірмос: Седьмери́цею пещ халде́йський мучи́тель богочесті́вим неі́стовно разжже́, си́лою же лу́чшею спасе́ни сія́ ви́дів, Творцю́ і Ізба́вителю вопія́ше: о́троци благослові́те, свяще́нници воспо́йте, лю́діє превозносі́те во вся ві́ки.","Приспів: Поко́й, Го́споди, ду́шу усо́пшаго раба́ Твоєго́.","Сконча́в тече́ніє і к Тебі́ прибіго́х, Го́споди, преста́вленний вопіє́ть ни́ні, прегріше́нія оста́ви, Христе́ Бо́же, і не осуди́ мене́, єгда́ хо́щеши суди́ти всім, ві́рно бо Тебе́ взива́х: вся діла́ Госпо́дня, Го́спода по́йте і превозносі́те Єго́ во ві́ки.","Приспів: Поко́й, Го́споди, ду́шу усо́пшаго раба́ Твоєго́.","Поне́сшаго, Влади́ко, і́го Твоє́ на ра́мі своє́м, і бре́м'я Твоє́ ле́гкоє, а́ще і не всегда́, оба́че в мі́сті преподо́бних Твої́х всели́ ду́шу єго́, воспі́вшаго Тебі́, Христе́ Спа́се: о́троци благослові́те, свяще́нници воспо́йте, лю́діє превозносі́те Єго́ во ві́ки.","Благослові́м Отця́ і Си́на і Свята́го Ду́ха, Го́спода.","Безнача́льная Тро́йце Свята́я, Бо́же О́тче і Си́не і Ду́ше Святи́й, в ли́ці святи́х причти́ ду́шу преста́вленнаго раба́ Твоєго́ і огня́ ві́чнаго ізба́ви, да Тя хва́лить, воспіва́я во ві́ки: о́троци благослові́те, свяще́нници воспо́йте, лю́діє превозносі́те Єго́ во ві́ки.","І нині: Тя, Ді́во, проро́честії ли́ци прореко́ша, прозря́ще бо Тя прозорли́вима очи́ма: ов у́бо жезл нарече́ Тя, ін же двер восто́чную, ов же го́ру челові́ки несіко́мую. Ми же іспові́дуєм Тя воі́стину Богоро́дицю, Бо́га вся́чеських ро́ждшую, Єго́же моли́ упоко́їти преста́вленнаго во ві́ки вся."]},{"h":"Пісня 9","ps":["Ірмос: Ужасе́ся о сем не́бо, і землі́ удиви́шася конці́, я́ко Бог яви́ся челові́ком пло́тськи, і чре́во Твоє́ бисть простра́ннійшеє небе́с. Тім Тя, Богоро́дицю, А́нгелов і челові́к чинонача́лія велича́ють.","Приспів: Поко́й, Го́споди, ду́шу усо́пшаго раба́ Твоєго́.","Ісу́се Бо́же мой, Спа́се, Ада́мле Ти взял єси́ преступле́ніє і сме́рті вкуси́л єси́, да челові́ки от нея́ свободи́ши, Милосе́рде. Ті́мже мо́лим Тя, Ми́лостиве: преста́вленнаго поко́й, я́ко Благ, во дво́ріх святи́х Твої́х, я́ко Єди́н Всеблаги́й і Милосе́рдий.","Приспів: Поко́й, Го́споди, ду́шу усо́пшаго раба́ Твоєго́.","Ність нікто́же, Милосе́рде, і́же не согріши́ в челові́ціх, то́кмо Ти Єди́н, Ісу́се Христе́, взе́мляй гріхи́ всего́ ми́ра. Ті́мже, очи́стив раба́ Твоєго́ от прегріше́ній, вчини́ во святи́х Твої́х дво́ріх: Ти бо живо́т єси́ і поко́й, і світ, і весе́ліє всіх, Тебі́ благоугоди́вших.","Слава: Удиви́ся все єстество́ челові́чеськоє, ка́ко Безнача́льнаго Отця́ Син сий Єдиноро́дний, плоть от Ді́ви ді́йством Свята́го Ду́ха прия́л єси́, і пострада́л єси́ я́ко челові́к, да уме́ршія оживи́ши. Тім і преста́вленнаго ни́ні от нас, прилі́жно мо́лим Тя, во страні́ живи́х, я́ко Благ, всели́.","І нині: Неві́сту Тя нариця́єм, Пречи́стая, Отця́ неви́димаго, і Ма́тер Си́на, із Тебе́ Ду́хом Святи́м воплоще́ннаго, і моле́бницю Тя о усо́пшем рабі́ Твоє́м предлага́єм: Тебі́ бо помо́щницю і́мами, земні́ї, і любо́вію пою́ще Тя велича́єм.","Досто́йно єсть я́ко воі́стину блажи́ти Тя, Богоро́дицю, присноблаже́нную і пренепоро́чную і Ма́тер Бо́га на́шего. Честні́йшую Херуви́м і сла́внійшую без сравне́нія Серафи́м, без істлі́нія Бо́га Сло́ва ро́ждшую, су́щую Богоро́дицю, Тя велича́єм.","Святи́й Бо́же, Святи́й крі́пкий, Святи́й безсме́ртний, поми́луй нас. (тричі)","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","Пресвята́я Тро́йце, поми́луй нас; Го́споди, очи́сти гріхи́ на́ша; Влади́ко, прости́ беззако́нія на́ша; Святи́й, посіти́ і ісціли́ не́мощі на́ша, і́мене Твоєго́ ра́ди.","Го́споди, поми́луй. (тричі)","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","О́тче наш, І́же єси́ на небесі́х, да святи́ться і́м'я Твоє́, да при́йдеть Ца́рствіє Твоє́, да бу́деть во́ля Твоя́, я́ко на небесі́ і на землі́. Хліб наш насу́щний даждь нам днесь; і оста́ви нам до́лги на́ша, я́коже і ми оставля́єм должнико́м на́шим; і не введи́ нас во іскуше́ніє, но ізба́ви нас от лука́ваго."]},{"h":"Тропарі, глас 4","ps":["Со ду́хи пра́ведних сконча́вшихся ду́ші раб Твої́х, Спа́се, упоко́й, сохраня́я їх во блаже́нній жи́зні, я́же у Тебе́, Человіколю́бче.","В поко́їщі Твоє́м, Го́споди, іді́же всі святі́ї Твої́ упокоєва́ються, упоко́й ду́ші раб Твої́х, я́ко Єди́н єси́ Человіколю́бець.","Слава: Ти єси́ Бог, соше́дий во ад і у́зи окова́нних разріши́вий, Сам і ду́ші раб Твої́х упоко́й.","І нині: Єди́на чи́стая і непоро́чная Ді́во, Бо́га без сі́мене ро́ждшая, моли́ спасти́ся душа́м їх.","Го́споди, поми́луй. (40 разів)"]},{"h":"Молитва","ps":["Пом'яни́, Го́споди Бо́же наш, во ві́рі і наде́жді живота́ ві́чнаго преста́вльшагося раба́ Твоєго́ (або: преставльшуюся рабу Твою) (ім’я), і я́ко Благ і Человіколю́бець, отпуща́яй гріхи́ і потребля́яй непра́вди, осла́би, оста́ви і прости́ вся во́льная єго́ (єя) согріше́нія і нево́льная, ізба́ви єго́ (ю) ві́чния му́ки і огня́ геє́нськаго, і да́руй єму́ (ей) прича́стіє і наслажде́ніє ві́чних Твої́х благ, угото́ванних лю́б'ящим Тя: а́ще бо і согріши́, но не отступи́ от Тебе́, і несумні́нно во Отця́ і Си́на і Свята́го Ду́ха, Бо́га Тя, в Тро́йці сла́вимаго, ві́рова: і Єди́ницю в Тро́йці і Тро́йцю в Єди́нстві правосла́вно да́же до послі́дняго своєго́ іздиха́нія іспові́да. Ті́мже ми́лостив тому́ (той) бу́ди, і ві́ру, я́же в Тя, вмі́сто діл вміни́, і со святи́ми Твої́ми, я́ко Щедр, упоко́й: ність бо челові́ка, і́же поживе́ть і не согріши́ть. Но Ти єди́н єси́ кромі́ вся́каго гріха́ і пра́вда Твоя́ пра́вда во ві́ки, і Ти єди́н Бог ми́лости і щедро́т і человіколю́бія, і Тебі́ сла́ву возсила́єм, Отцю́ і Си́ну і Свято́му Ду́ху, ни́ні і при́сно і во ві́ки віко́в, амі́нь."]},{"h":"Або","ps":["Пом'яни́, Го́споди Бо́же наш, во ві́рі і наде́жді живота́ ві́чнаго усо́пших раб Твої́х (імена), і я́ко благ і Человіколю́бець, отпуща́яй гріхи́, і потребля́яй непра́вди, осла́би, оста́ви, і прости́ вся во́льная їх согріше́нія і нево́льная, возставля́я їх во свято́є второ́є прише́ствіє Твоє́ в прича́стіє ві́чних Твої́х благ, ї́хже ра́ди в Тя Єди́наго ві́роваша, і́стиннаго Бо́га і Человіколю́бця; я́ко Ти єси́ воскресе́ніє і живо́т, і поко́й рабо́м Твої́м (імена), Христе́ Бо́же наш, і Те́бі сла́ву возсила́єм, со безнача́льним Твої́м Отце́м, і с Пресвяти́м Ду́хом, ни́ні і при́сно і во ві́ки віко́в, амі́нь.","Честні́йшую Херуви́м і сла́внійшую без сравне́нія Серафи́м, без істлі́нія Бо́га Сло́ва ро́ждшую, су́щую Богоро́дицю, Тя велича́єм.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","Го́споди, поми́луй. (тричі) Го́споди, благослови́.","Го́споди Ісу́се Христе́, Си́не Бо́жий, моли́твами Пречи́стия Твоє́й Ма́тере, преподо́бних і богоно́сних оте́ць на́ших і всіх святи́х поми́луй і упоко́й ду́шу раба́ Твоєго́ (ім’я), в безконе́чния ві́ки, я́ко благ і человіколю́бець, амі́нь.","Рабу́ Бо́жию, ім’я, усо́пшему ві́чная па́м'ять, ві́чная па́м'ять, ві́чная па́м'ять.","І читаємо тричі тропар з поклонами:","Поко́й, Го́споди, ду́шу усопшего раба́ Твоєго́, ім’я (поклін), і єли́ко в житії́ сем я́ко челові́к согріши́, Ти же, я́ко человіколю́бець Бог, прости́ єго́ і поми́луй (поклін), ві́чния муки́ ізба́ви (поклін), Небе́сному Ца́рствію прича́стника учини́ (поклін) і душа́м на́шим поле́зная сотвори́ (поклін)."]}],"notes":[]},{"u":"Канон за недужого","e":"Canon for the sick","secs":[{"h":"Глас 3. Пісня 1","ps":["Ірмос: Пресіка́ємоє мо́ре жезло́м дре́вле, Ізра́їль про́йде я́ко по пусти́ні, і крестообра́зно я́ві предуготовля́єть стезі́. Сего́ ра́ди пої́м во хвале́нії чу́дному Бо́гу на́шему, я́ко просла́вися.","Приспів: Ми́лостиве Го́споди, усли́ши моли́тву раб Твої́х, моля́щихся Тебі́.","В день печа́лі, наше́дшия на ни, к Тебі́, Христе́ Спа́се, припа́дающе, Твоєя́ ми́лости про́сим. Облегчи́ болі́знь раба́ Твоєго́, ізреки нам я́ко і со́тнику: іди́, се здрав єсть о́трок твой.","Приспів: Ми́лостиве Го́споди, усли́ши моли́тву раб Твої́х, моля́щихся Тебі́.","Мольби́ і моле́нія, с воздиха́нієм к Тебі́ вопіє́м, Си́не Бо́жий, поми́луй нас. Воздви́гни со одра́ лежа́щаго, я́ко разсла́бленнаго сло́вом: возьми́ одр твой, глаго́ля, отпуща́ються ті гріси́ твої́.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Твоєго́, Христе́, о́браза подо́бію поклоняющеся, ві́рою цілу́єм, і боля́щему здра́вія про́сим, подража́юще кровоточи́вій, я́же подольця риз Твої́х косну́ся, і ісціле́ніє неду́га прия́т.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Пречи́стая Госпоже́ Богоро́дице, всім ізві́стная Помо́щниця, не пре́зри нас к Тебі́ припа́дающих, моли́ я́ко бла́га Твоєго́ Си́на і Бо́га на́шего, да́ти здра́віє боля́щему, да Тя с на́ми прославля́єть."]},{"h":"Пісня 3","ps":["Ірмос: І́же от не су́щих вся приведи́й, сло́вом созида́ємая, соверша́ємая ду́хом, Вседержи́телю Ви́шній, в любві́ Твоє́й утверди́ мене́.","Приспів: Ми́лостиве Го́споди, усли́ши моли́тву раб Твої́х, моля́щихся Тебі́.","І́же от тя́жких болі́зней на землі́ пове́ржен, к Тебі́, Христе́, с на́ми вопіє́ть, пода́ждь здра́віє тілесі́ єго́, я́ко же Ієзекі́ї пла́кавшуся к Тебі́.","Приспів: Ми́лостиве Го́споди, усли́ши моли́тву раб Твої́х, моля́щихся Тебі́.","При́зри, Го́споди, на на́ше смире́ніє, і не пом'яни́ беззако́ній на́ших, но ві́ри ра́ди боля́щаго, я́ко прокаже́ннаго сло́вом ісціли́ єму́ болі́знь, да Твоє́, Христе́ Бо́же, сла́виться і́м'я.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Це́рков, ю́же єси́ освяти́л, на ту, Христе́, не даждь поноше́нія, но воздви́гни неви́димо в неду́зі на одрі́ лежа́щаго, в не́йже мо́лим Ті ся: да не реку́ть неві́рнії, гді єсть Бог їх.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","К Твоєму́ пречи́стому, Богоро́дице, о́бразу ру́ці возді́юще вопіє́м, усли́ши раб Твої́х моли́тву і спаси́ в болі́зні лежа́щаго, да от болі́зні воста́в, возда́сть обі́ти, я́же в печа́лі глаго́лаша уста́ єго́."]},{"h":"Сідален, глас 8","ps":["На одрі́ гріхо́внім лежа́ща м'я, і страстьми́ уя́звена, і я́коже воздви́гл єси́ Петро́ву те́щу і спа́се разсла́бленнаго носи́ма со одро́м, та́ко і ни́ні посіти́, Ми́лостиве, боля́щаго, понеси́й неду́ги ро́да на́шего. Тебе́ Єди́наго ві́ми, терпіли́ва і милосе́рда, ми́лостива Врача́ душа́м і тілесе́м, Христа́ Бо́га на́шего, наводяща неду́ги і па́ки ісціля́юща, подава́юща проще́ніє кающимся о согріше́ніїх, Єди́наго Милосе́рдаго і Ми́лостиваго.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Аз грі́шний пла́чуся на одрі́ своє́м лежа́, проще́ніє мі пода́ждь, Христе́ Бо́же, і от болі́зні сея́ воздви́гни м'я, і я́же єсьм от ю́ности гріхи́ сотвори́л, ізби́ти мі сих моли́твами Богоро́диці да́руй.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Умилосе́рдися і спаси́ м'я, воздви́гни м'я от одра́ болі́зненнаго, мощ бо моя́ во мні ізнемо́же і весь неча́янієм одержи́м єсьм, Ма́ти Бо́жия Пречи́стая, ісціли́ неду́гующа лю́ті, Ти бо єси́ Помо́щниця Христия́ном."]},{"h":"Пісня 4","ps":["Ірмос: Положи́л єси́ к нам тве́рдую любо́в, Го́споди: Єдиноро́днаго бо Твоєго́ Си́на за ни на смерть дал єси́, ті́мже Ті зове́м благодаря́ще: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Ми́лостиве Го́споди, усли́ши моли́тву раб Твої́х, моля́щихся Тебі́.","Уже́ отча́янна лю́тим неду́гом і к сме́рті прибли́жившася, возврати́, Христе́, на живо́т і даждь плачущимся уті́ху, да всі прославля́єм Твоя́ свята́я чудеса́.","Приспів: Ми́лостиве Го́споди, усли́ши моли́тву раб Твої́х, моля́щихся Тебі́.","К Тебі́, Тво́рче, ка́ємся в свої́х грісі́х, я́ко не хо́щеши сме́рті грі́шничі, оживи́, уздра́ви боля́щаго, да воста́в послу́жить Ті, іспові́дуя с на́ми Твою́ бла́гость.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Сле́зи Манассі́їни, Ніневи́тян покая́ніє, Дави́дово іспові́даніє приї́м, вско́рі спасл єси́, і на́ші моли́тви ни́ні прийми́, даждь здра́віє боля́щему, о нем же Тя мо́лим.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Пода́ждь нам Твою́ ми́лость, Госпоже́, всегда́ на Тя надеющимся, іспроси́ здра́віє боля́щему, врачебнії Твої́ ру́ці с Предте́чею, Богоро́диці, ко Го́споду Бо́гу простира́ющи."]},{"h":"Пісня 5","ps":["Ірмос: На землі́ Неви́димий яви́лся єси́, і челові́ком во́лею сожи́л єси́ Непостижи́мий, і к Тебі́ у́тренююще, воспіва́єм Тя, Человіколю́бче.","Приспів: Ми́лостиве Го́споди, усли́ши моли́тву раб Твої́х, моля́щихся Тебі́.","Дщер Іаї́рову уже́ уме́ршу, я́ко Бог оживи́л єси́, і ни́ні возведи́, Христе́ Бо́же, от врат сме́ртних боля́щаго, Ти бо єси́ Путь і Живо́т всім.","Приспів: Ми́лостиве Го́споди, усли́ши моли́тву раб Твої́х, моля́щихся Тебі́.","Си́на вдови́ча оживи́в Спа́се, і тоя́ сле́зи преложи́в на ра́дость, спаси́ от неду́га тлі́ющаго раба́ Твоєго́, да і на́ша скорб і болі́знь на ра́дость при́йдеть.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","О́гненну болі́знь тещи́ Петро́ві прикоснове́нієм Твої́м ісціли́в, і ни́ні возста́ви боля́щаго раба́ Твоєго́, да воста́в я́коже і она́, послу́жить Ті.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Ско́рбнії, смире́ннії, грі́шнії, не іму́щії дерзнове́нія к Тебі́, Пречи́стая Богома́ти, вопіє́м, умоли́ Си́на Твоєго́ Христа́ да́ти боля́щему здра́віє тілесі́."]},{"h":"Пісня 6","ps":["Ірмос: Бе́здна послі́дняя гріхо́в оби́де м'я, і ісчеза́єть дух мой: но простри́й, Влади́ко, висо́кую Твою́ ми́шцю, я́ко Петра́ м'я, Упра́вителю, спаси́.","Приспів: Ми́лостиве Го́споди, усли́ши моли́тву раб Твої́х, моля́щихся Тебі́.","Бе́здну милосе́рдія і ми́лости імі́я, Христе́ Бо́же, усли́ши моле́нія раб Твої́х. Ти бо єси́ Петро́м Тави́фу воскреси́л, Ти і ни́ні в болі́зні лежа́щаго воздви́гни, послу́шав церко́вних моли́твенник.","Приспів: Ми́лостиве Го́споди, усли́ши моли́тву раб Твої́х, моля́щихся Тебі́.","Врачу́ душа́м і тілесе́м на́шим, понеси́й неду́ги всего́ ми́ра, Христе́, Єнея Петро́м ісціли́вий і Євти́ха Па́влом воскреси́вий, Ти і ни́ні боля́щаго ісціли́ святи́х апо́стол моли́твами.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Преложи́, Христе́, на ра́дость рида́ніє о недужнем скорб'ящем, да Твою́ получи́вше ми́лость, вни́дуть в дом Твой со обетними дарми́, сла́в'яще Тя в Тро́йці Єди́наго Бо́га.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Прийді́те, о дру́зі, поклоні́мся моля́щеся о боля́щем Бо́жієй Ма́тері. Та бо імі́єть власть неду́жния ісціля́ти, со безме́здникома вку́пі, духо́вним неви́димо помазу́юще ма́слом."]},{"h":"Кондак, глас 3","ps":["Ду́шу мою́, Го́споди, во грісі́х вся́чеських, безмі́стними дія́ньми разсла́блену воздви́гни боже́ственним Твої́м человіколю́бієм, я́ко же і разсла́бленнаго воздви́гл єси́ дре́вле, да зову́ Ті спасаєм: ще́дре Христе́, даждь мі ісціле́ніє."]},{"h":"Ікос","ps":["І́же руки́ Своє́й го́рстію содержа́й конці́, Ісу́се Бо́же, І́же Отцю́ собезнача́льний і Ду́ху Свято́му совладичествуя, я́ко пло́тію яви́лся єси́ неду́ги ісціля́я і стра́сті очи́стил єси́, сліпи́я просвіти́л єси́, і разсла́бленнаго сло́вом Боже́ственним совоставил єси́, сего́ пра́во ходя́ща сотвори́в і одр повелі́л єси́ на ра́мо взя́ти. Ті́мже всі с ним воспіва́єм і поє́м: ще́дре Христе́, даждь мі ісціле́ніє."]},{"h":"Пісня 7","ps":["Ірмос: Пре́жде о́бразу злато́му, перси́дському чти́лищу о́троци не поклони́шася, тріє́ пою́ще посреді́ пе́щі: отце́в Бо́же, благослове́н єси́.","Приспів: Ми́лостиве Го́споди, усли́ши моли́тву раб Твої́х, моля́щихся Тебі́.","О, Кресті́ Пресвяти́й Христо́в, честно́є Дре́во Живо́тноє. Тобо́ю смерть поги́бе і ме́ртвії воскресо́ша, і ни́ні боля́щаго ісціли́ і оживи́, я́коже при Єле́ні уме́ршую діви́цю.","Приспів: Ми́лостиве Го́споди, усли́ши моли́тву раб Твої́х, моля́щихся Тебі́.","До́лгую і лю́тую болі́знь І́овлю на гно́їщі і в червіх, того́ моля́щася, сло́вом ісціли́л єси́, Го́споди. І ни́ні же в це́ркві о боля́щем мо́лим Тя: я́ко благ, ісціли́ неви́димо моли́твами святи́х Твої́х.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Всі ві́ми, я́ко умре́ти нам єсть, Тебі́ Бо́гу та́ко ізво́лившу, но на ма́ло вре́м'я, Ми́лостиве, здра́вія про́сим боля́щему, преміни́ от сме́рти на живо́т, даждь скорб'я́щим уті́ху.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Посо́бствуй і помога́й на́шему сиротству, Богоро́дице, Ти бо ві́си вре́м'я і час, когда́ умоли́ти Си́на Твоєго́ і Бо́га на́шего, да́ти боля́щему здра́віє і проще́ніє от всіх гріх."]},{"h":"Пісня 8","ps":["Ірмос: Служи́ти Живо́му Бо́гу, во Вавило́ні о́троци претерпі́вше, о мусикі́йських орга́ніх неради́ша, і посреді́ пла́мене стоя́ще, боголі́пную піснь воспіва́ху, глаго́люще: благослові́те вся діла́ Госпо́дня Го́спода.","Приспів: Ми́лостиве Го́споди, усли́ши моли́тву раб Твої́х, моля́щихся Тебі́.","Ми́лость покажи́, Влади́ко, в болі́зні раба́ Твоєго́, і ско́ро ісціли́, ми́лостиве Христе́ Бо́же, і а́ще сме́рті не преда́ждь судней, да Ті покая́ніє возда́сть. Сам бо рекл єси́: не хощу́ сме́рти грі́шничі.","Приспів: Ми́лостиве Го́споди, усли́ши моли́тву раб Твої́х, моля́щихся Тебі́.","Го́споди ми́лостиве, Твоя́ пресла́вная чудеса́ да і до нас ни́ні дости́гнуть: бі́си прожени́, неду́ги погуби́, ра́ни ісціли́, болі́зні уврачу́й, і потво́ри і чародія́нія і вся́кия я́зі ізба́ви ни.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Запрети́вий, Христе́, морськи́м ві́тром, і страх учени́к на ра́дость преложиви́й, і ни́ні запрети́ тя́жким болі́знем, труждающим раба́ Твоєго́, да всі возвеселі́мся хва́ляща Тя во ві́ки.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Ізба́ви, Богоро́дице, от обише́дших ни печа́лей, разли́чних неду́г, отра́ви же і чароді́йства, і бісо́вськаго мечта́нія, і от наві́та злих челові́к і от напра́сния сме́рті, мо́лим Ті ся."]},{"h":"Пісня 9","ps":["Ірмос: На Сина́йстій го́ре ви́ді Тя в купині́ Мойсе́й, неопа́льно огнь Божества́ заче́ншую во чре́ві: Данії́л же Тя ви́ді го́ру несіко́мую, жезл прозя́бший, Ісайя взива́ше, от ко́рене Дави́дова.","Приспів: Ми́лостиве Го́споди, усли́ши моли́тву раб Твої́х, моля́щихся Тебі́.","Істо́чниче жи́зні, пода́телю, Христе́, ми́лості, не отврати́ лиця́ Твоєго́ от нас. Облегчи́ болі́знь утружде́нному болі́знію, і воздви́гни я́ко Фадде́ом А́вгаря, да при́сно Тебе́ сла́вить со Отце́м і Святи́м Ду́хом.","Приспів: Ми́лостиве Го́споди, усли́ши моли́тву раб Твої́х, моля́щихся Тебі́.","Єва́нгельському ві́рующе гла́су, Твоєго́ і́щем обі́та, Христе́: просі́те бо, рече́, і да́сться вам. Тім і ни́ні предстоя́ще мо́лим Тя, возста́ви со одра́ здра́ва лю́тим пове́ржена неду́гом, да Тя с на́ми вку́пі велича́єть.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Мучимий неду́гом, внутр неви́димими ра́нами, Тебі́, Христе́, с на́ми вопіє́ть, не нам, Го́споди, не нас ра́ди, всі бо ми іспо́лнени гріхо́в, но Ма́терніми Твої́ми і Предтечевими моли́твами даждь ісціле́ніє боля́щему, да Тя всі возвели́чим.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Бо́жия Ма́ти Пречи́стая, со всі́ми святи́ми призива́єм Тя, со а́нгели і арха́нгели, с проро́ки і патріа́рхи, со апо́столи, с преподо́бними і пра́ведними моли́ся Христу́ Бо́гу на́шему да́ти здра́віє боля́щему, да Тя всі велича́єм."]},{"h":"Молитва","ps":["Бо́же си́льний, ми́лостію стро́яй вся на спасе́ніє ро́ду челові́чеському, посіти́ раба́ Твоєго́ сего́ (ім’я), нарицяюща і́м'я Христа́ Твоєго́, ісціли́ єго́ от всякого неду́га плотська́го: і отпусти́ гріх і гріхо́вния собла́зни, і вся́ку напа́сть, і вся́ко наше́ствіє неприязнено дале́че сотвори́ от раба́ Твоєго́. І воздви́гни от одра́ гріхо́внаго, і устро́й єго́ во святу́ю Твою́ Це́рков здра́ва душе́ю і ті́лом, і ді́ли до́брими сла́в'ящаго со всі́ми людьми́ і́м'я Христа́ Твоєго́, я́ко Тебі́ сла́ву возсила́єм, со Безнача́льним Ті Сино́м і со Святи́м Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Канон покаянний до Пресвятої Богородиці","e":"Canon of repentance to the Most Holy Theotokos","secs":[{"h":"Октоїх. Глас 6. У вівторок, на повечір’ї.","ps":[]},{"h":"Глас 6. Пісня 1","ps":["Ірмос: Я́ко по су́ху пішеше́ствовав Ізра́їль, по бе́здні стопа́ми, гони́теля фарао́на ви́дя потопля́єма, Бо́гу побі́дную піснь пої́м, вопія́ше.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Вся́ко моєго́ рида́ю житія́ скве́рнаго, і мно́жества безмі́рних мої́х зол: что же іспові́м ті Чи́стая, недоумі́ю і ужаса́юся: но по́мощі мі Влади́чице.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Отку́ду начну́ глаго́лати лука́вая і лю́тая моя́ паде́нія, стра́стний аз; уви́ мні, что бу́ду про́чеє; но Влади́чице, пре́жде конця́ уще́дри м'я.","Слава: Сме́ртний у́бо час, і суди́ще стра́шноє всегда́ помишля́ю, Пречи́стая, оби́чаєм же всезли́м прельща́юся лю́ті: но помозщи мі.","І нині: Благи́х тли́тель, смотря́я м'я ни́ні на́га Боже́ственних доброді́телей, і дале́че отсту́пльша і отчужде́на от Бо́га, поглоти́ти м'я устремля́ється: Влади́чице, предвари́."]},{"h":"Пісня 3","ps":["Ірмос: Ність свят, я́коже Ти, Го́споди Бо́же мой, вознеси́й рог ві́рних Твої́х, Бла́же, і утверди́вий нас на ка́мені іспові́данія Твоєго́.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Ду́шу окаля́х скве́рно от безмі́рних зол мої́х стра́стний аз, Богоро́дице Влади́чице: і ка́мо про́чеє пойду́, отча́янієм весь одержи́м.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","І є́же по о́бразу, себі́ окаля́х, Чи́стая, і по подо́бію: ді́лом, і сло́вом, і по́мислом соді́ях безмі́стная.","Слава: Ність ін в челові́ціх, і́же неподо́бная соді́яв, ні роди́ся в ми́рі, я́коже аз, Блага́я, помраче́н умо́м: і́бо креще́ніє Боже́ственноє оскверни́х.","І нині: На коне́ць достиго́х злих, пресвята́я Ді́во, ти по́мощі мі вско́рі: не́бо і земля́ вопію́ть го́рці, от безмі́стних дія́ній неподо́бних."]},{"h":"Пісня 4","ps":["Ірмос: Христо́с моя́ си́ла, Бог і Госпо́дь, честна́я Це́рков боголі́пно поє́ть, взива́ющи от сми́сла чи́ста, о Го́споді пра́зднующи.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","А́нгельстії чи́нове, і во́їнства небе́сних сил, твоєго́ Си́на ужаса́ються держа́ви, Чи́стая: ни́ні же аз отча́явся, безстра́шієм одержи́м єсьм.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Удиви́ся вся земля́ і ужасе́ся зря́щи, лю́тая і зла́я творя́щу мі, і безмі́стная: і твоєго́ Си́на мно́гому милосе́рдію чуди́ться.","Слава: Це́рков оскверни́в злі тіле́сную, і Це́рков Госпо́дню, в ню́же челові́ци трепе́щуще вхо́дять, аз же блу́дний без студа́ вхожду́: уви́ мні.","І нині: Не яви́, Влади́чице, не яви́ стра́нна м'я устра́ншася кро́ва Си́на твоєго́, вся́ко недосто́йнаго: но оми́й мене́ от скве́рни прегріше́ній мої́х."]},{"h":"Пісня 5","ps":["Ірмос: Бо́жиїм сві́том Твої́м, Бла́же, у́тренюющих Ті душі́ любо́вію озари́, молю́ся, Тя ві́діти, Сло́ве Бо́жий, і́стиннаго Бо́га, от мра́ка гріхо́внаго взива́юща.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Боже́ственним сія́нієм твої́м Блага́я, ісціли́ душе́вния моя́ стра́сті, я́же мі тли́тель всея́: і ізба́ви м'я сего́ пліне́нія го́ркаго.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Ада́м преступи́ у́бо за́повідь єди́ну Ді́во, і во ізгна́ніє впаде́: ка́ко же рида́ю прегріше́ній мої́х бе́здну аз престу́пний.","Слава: Уби́йця у́бо я́влься дре́ві, і братоуби́йця Ка́їн, Бо́гом про́клят бисть: что же сотворю́ аз вседе́рзий, ду́шу у́бо уби́в ни́ні, і не стижду́ся.","І нині: Іса́ву поревнова́х лю́тому, чревооб'яденієм, і си́тостію: весь, ду́шу оскверни́х пія́нством, і ласкосе́рдством житіє́ моє́: і кто мене́ не пла́четь стра́стнаго, уви́ мні."]},{"h":"Пісня 6","ps":["Ірмос: Жите́йськоє мо́ре, воздвиза́ємоє зря напа́стей бу́рею, к ти́хому приста́нищу Твоєму́ прите́к, вопію́ Ті: возведи́ от тлі живо́т мой, Многоми́лостиве.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Житіє́ моє́ блу́дно, душа́ моя́ скверна́ва, і живо́т весь окая́нен, ті́ло же моє́ все во злих лю́ті окаля́х: ті́мже потщи́ся Ді́во, по́мощі мі.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Коне́ць предста́, і не теплю, Блага́я, со́вість облича́єть м'я: предстоя́ть бо мі дія́нія лука́вая, і житіє́ блу́дноє, і суди́ща ужаса́юся Си́на твоєго́, Чи́стая.","Слава: Пло́ті моєя́ разжже́ніє, ріка́ о́гненна стра́шна і неугаси́ма ждеть воі́стину, і черв неусипа́яй: но угаси́ мі сія́ моли́твами твої́ми, Пречи́стая.","І нині: Ни́ні тре́петом одержи́м єсьм, Блага́я, і ужаса́юся лука́ваго ловле́нія: пре́жде бо конця́ хо́щеть м'я тли́тель уби́ти, держа́ м'я я́ко пліне́на всего́, і на́га доброді́телей.","Го́споди поми́луй, Тричі.","Слава, і нині:"]},{"h":"Сідален, глас 6","ps":["Упова́ніє і стіна́, і приста́нище лю́дем твої́м, Ді́во: із нея́же роди́ся безстра́стно Спас вся́чеських: я́коже пла́чася твоєго́ Си́на при кресті́, того́ і ни́ні моли́ ізба́вити от тлі вся, пою́щия тя."]},{"h":"Пісня 7","ps":["Ірмос: Росода́тельну у́бо пещ соді́ла А́нгел преподо́бним отроко́м, халде́ї же опаля́ющеє велі́ніє Бо́жиє, мучи́теля увещі вопи́ти: благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Седьм седьмери́цею пла́мень разжже́ мі страстьми́ лука́вий, і любодія́ньми се́рдце моє́ всегда́ умерщвля́єть: ті́мже то́ками мої́х слез угаси́ єго́, Ма́ти Бо́жия, і спаси́.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Окаля́єма ти́ною прегріше́ній мої́х, не отри́ни мене́, Влади́чице блага́я: і́бо зря м'я во отча́янії су́ща, сміє́ться прелука́вий враг: но сама́, твоє́ю держа́вною руко́ю возста́ви.","Слава: Стра́шноє у́бо суди́ще, стра́стная душе́ моя́ і нечу́вственная, і муче́ніє же неконча́ємоє і гро́зноє: но оба́че ни́ні припади́ к Ма́тері Судії́ твоєго́ і Бо́га, і не отча́йся сама́.","І нині: Омрачи́хся стра́стний, мно́жеством безмі́рних зол, і оскверни́х ду́шу і ті́ло же і ум: ті́мже Пречи́стая, сві́том твої́х сія́ній, к безстра́стію сла́дости ско́ро введи́ м'я."]},{"h":"Пісня 8","ps":["Ірмос: Із пла́мене преподо́бним ро́су істочи́л єси́ і пра́веднаго же́ртву водо́ю попали́л єси́: вся бо твори́ши, Христе́, то́кмо є́же хоті́ти. Тя превозно́сим во вся ві́ки.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Я́же от Тро́йці єди́наго Бо́га ро́ждшая, і на ру́ку носи́вшая, Ді́во Ма́ти: угаси́ страсте́й огнепа́льную пещ, і сле́зними то́ки оми́й ду́шу мою́.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Прихо́да сме́ртнаго ужаса́юся, Пречи́стая, і суда́ о́наго весь ни́ні убоя́хся: ді́я же зла́я, ніка́коже стижду́ся: уще́дри м'я пре́жде конця́, моли́твами твої́ми Ді́во.","Слава: Стена́нія немо́лчная, Влади́чице, да́руй мі, і слез ту́чи даждь, да оми́ю моя́ прегріше́нія мно́гая, і неісці́льния я́зви: я́ко да улучу́ жизнь ві́чную.","І нині: Зол мої́х мно́жество тебі́ іспові́дах Влади́чице: я́ко ні єди́н в ми́рі ін прогні́ва та́ко Бо́га, Си́на і Го́спода твоєго́: сего́ мі на ми́лость вско́рі преміни́, Ді́во."]},{"h":"Пісня 9","ps":["Ірмос: Бо́га челові́ком невозмо́жно ви́діти, на Него́же не смі́ють чи́ни А́нгельстії взира́ти; Тобо́ю же, Всечи́стая, яви́ся челові́ком Сло́во Воплоще́нно, Єго́же велича́юще, с небе́сними во́ї Тя ублажа́єм.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Я́же от Тро́йці єди́наго Бо́га ро́ждшая, і на ру́ку носи́вшая, Ді́во Ма́ти: угаси́ страсте́й огнепа́льную пещ, і сле́зними то́ки оми́й ду́шу мою́.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Се прихожду́ ті Пречи́стая, со стра́хом мно́гим і любо́вію, крі́пость ві́дий мно́гую моли́тви твоєя́, раб твой, мно́го бо мо́жеть воі́стину, Влади́чице, мольба́ ма́терня к Си́ну: милосе́рдієм бо преклоня́ється.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Я́же от Тро́йці єди́наго Бо́га ро́ждшая, і на ру́ку носи́вшая, Ді́во Ма́ти: угаси́ страсте́й огнепа́льную пещ, і сле́зними то́ки оми́й ду́шу мою́.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Ли́ки прими́ Арха́нгел же, і мно́жество ви́шніх во́їнств Зижди́теля моєго́, Апо́стол же і Проро́к собо́ри, і Му́ченики, і Преподо́бния, і Священному́ченики: і моли́тву сотвори́, Чи́стая, за нас к Бо́гу.","Слава: І ни́ні і тогда́ твою́ по́мощ да обря́щу Чи́стая, в час в о́ньже ізи́деть дух мой: вско́рі ізима́ющи ізба́ви м'я бісо́вськаго мучи́тельства, Пренепоро́чная, і не оста́ви мене́ Блага́я, пре́дану би́ти їм.","І нині: Судії́ ще́драго ча́ю, і человіколюби́ваго твоєго́ Си́на: Чи́стая, не пре́зри мене́, но того́ мі сотвори́ благопремі́нна, поста́вити мене́ одесну́ю тогда́, Всенепоро́чная, пречи́стому суди́щу єго́: на тя бо упова́х."]},{"h":"Молитва до Пресвятої Владичиці Богородиці","ps":["Пресвята́я Влади́чице моя́ Богоро́дице, святи́ми твої́ми і всеси́льними мольба́ми, отжени́ от мене́ смире́ннаго, і окая́ннаго раба́ твоєго́ уни́ніє, забве́ніє, неразу́міє, нераді́ніє, і вся скве́рная, лука́вая і ху́льная помишле́нія, от окая́ннаго моєго́ се́рдця, і от помраче́ннаго ума́ моєго́. І погаси́ пла́мень страсте́й мої́х, я́ко нищ єсьм і окая́нен: і ізба́ви м'я от мно́гих і лю́тих воспомина́ній, і предприя́тій, і от всіх дійств злих свободи́ м'я. Я́ко благослове́нна єси́ от всіх родо́в, і сла́виться пречи́стоє і́м'я твоє́, во ві́ки віко́в, амі́нь."]}],"notes":[]},{"u":"Канон Небесним Силам Безплотним","e":"Canon to the Heavenly Bodiless Powers","secs":[{"h":"Тропар, глас 4","ps":["Небе́сних во́їнств Архістрати́зі, мо́лим вас при́сно ми недосто́йнії, да ва́шими моли́твами огради́те нас кро́вом крил невеще́ственния ва́шея сла́ви, сохраня́юще нас припа́дающих прилі́жно і вопію́щих: от бід ізба́віте нас, я́ко чинонача́льници ви́шніх сил."]},{"h":"Канон Безплотних, твір Іоанна монаха, глас 8. Пісня 1","ps":["Ірмос: Піснь возсле́м, лю́діє, чу́дному Бо́гу на́шему, свободи́вшему Ізра́їля от рабо́ти, піснь побі́дную пою́ще і вопію́ще: пої́м Тебі́, Єди́ному Влади́ці.","Приспів: Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","Всі воспої́м, лю́діє, вся направля́ющую невеще́ственния ли́ки ви́шняго чинонача́лія, Тро́йцю Несозда́нную, пою́ще: свят, свят, свят єси́, Бо́же Вседержи́телю.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","Положи́л єси́ тва́рем нача́ток существо́ безпло́тноє, Тво́рче А́нгелов, Пречи́стий Твой Престо́л окружа́юща, зва́ти Ті: свят, свят, свят єси́, Бо́же Вседержи́телю.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","Ра́дуйся, Гавриї́ле, Бо́жия воплоще́нія возвісти́телю, Михаї́ле же, чино́в невеще́ственних предста́телю, непреста́нно зову́ще: свят, свят, свят єси́, Бо́же Вседержи́телю.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Трепе́щу та́їнства, Христе́, Твоєго́ схожде́нія, я́ко і́же єстество́м Бог, прия́л єси́ от Ді́ви роди́тися я́ко челові́к, да спасе́ши мир от рабо́ти сопроти́внаго."]},{"h":"Пісня 3","ps":["Ірмос: Страх Твой, Го́споди, всади́ в сердця́ раб Твої́х, і бу́ди нам утвержде́ніє, Тя во і́стині призива́ющим.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","Крі́постію уста́вил єси́, безсме́ртне, си́льния, соверша́ющия Пресвято́є Твоє́ хоті́ніє, Тебі́ во ви́шніх всегда́ предстоя́щия.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","Хода́таї Твоєго́ вочелові́ченія і честна́го воста́нія, а́нгельськия чинонача́льники, Христе́, за ни прийми́ моля́щіяся.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","А́нгели приста́вил єси́ храни́тели челові́ком, я́ко благоутро́бен, служи́телі же показа́л єси́, Христе́, спасе́нія Твої́м уго́дником.","Пресвята́я Богоро́дице, спаси́ нас.","Неізре́чено ро́ждши, Богоневі́сто, Спа́са і Го́спода, ізба́ви нас от тлі, Тя воі́стину призива́ющих."]},{"h":"Сідален, глас 8","ps":["Небе́сних нача́льниче і первостоя́телю високопресто́льних і стра́шних Боже́ственния сла́ви, Михаї́ле Архістрати́же, А́нгелом чинонача́льниче, со всі́ми безпло́тними, Єму́же слу́жиши Влади́ці, о всем ми́рі непреста́нно моли́ся і іспроси́ оставле́ніє гріхо́в, і ми́лость і благода́ть обрісти́ в день су́дний.","Сла́ва: В пучи́ну лю́ті впад уни́нія, от мно́жества лука́вих і беззако́нних мі діл, прийдо́х в недоумі́ніє, і отчая́нієм ни́ні одержу́ся: Влади́чице Богоро́дице, Ти м'я спаси́, Ти мі помози́: грі́шних бо Ти єси́ очище́ніє і чистота́ спаси́тельная.","І ни́ні: От чи́стих крове́й Твої́х вопло́щшася, і па́че ума́ із Тебе́, Чи́стая, ро́ждшагося, на дре́ві ви́сяща посреді́ злоді́ю зря́щи, утро́бою болі́зновала єси́ і ма́терськи пла́чущи вопія́ла єси́: уви́ мні, Ча́до Моє́, что єсть Боже́ственноє і неізрече́нноє смотре́ніє Твоє́, і́мже оживотвори́л єси́ созда́ніє Твоє́; пою́ Твоє́ милосе́рдіє."]},{"h":"Пісня 4","ps":["Ірмос: Всіл єси́ на ко́ни апо́столи Твоя́, Го́споди, і прия́л єси́ рука́ма Твої́ма узди́ їх, і спасе́ніє бисть їжде́ніє Твоє́ ві́рно пою́щим: сла́ва си́лі Твоє́й, Го́споди.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","Всіл єси́ на А́нгели, я́коже на ко́ни, Человіколю́бче, і прия́л руко́ю Твоє́ю вожда́ їх, і спасе́ніє бисть їжде́ніє Твоє́ ві́рно Ті вопію́щим: сла́ва си́лі Твоє́й, Го́споди.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","Покрива́єть А́нгели доброді́тель Твоя́, Безсме́ртне, і земни́я ісполня́єть конці́ Твоєго́ сла́внаго, Безнача́льне, Боже́ственнаго хвале́нія: с ни́миже Тебі́ вопіє́м: сла́ва си́лі Твоє́й, Го́споди.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","Ізше́л єси́, Ще́дре, на спасе́ніє лю́дем Твої́м, Христе́: созива́євши же дру́ги, си́ли Твоя́, і весе́ліє бисть во спасе́нії Твоє́м безве́щним, вопію́щим: сла́ва си́лі Твоє́й, Го́споди.","Пресвята́я Богоро́дице, спаси́ нас.","Ді́ва і Ма́ти па́че єстества́ яви́лася єси́, Пречи́стая, я́ко Бо́га, Того́же і Челові́ка Христа́ родила́ єси́, от А́нгел хва́лимаго: люде́й Твої́х печа́ль переложи́ на ра́дость моли́твами Твої́ми."]},{"h":"Пісня 5","ps":["Ірмос: От но́щі неві́дінія Богові́дінієм просвіти́вий конці́, просвіти́ м'я у́тром человіколю́бія Твоєго́, Го́споди.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","Невозвра́тним жела́нієм всегда́ к висоті́, Христе́, носи́ми, кра́йнєє всіх жела́ніє, а́нгельськія си́ли непреста́нно сла́в'ять.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","Ти разу́мния по существу́, нетлі́нния благода́тію Твоє́ю, Христе́, поста́вил єси́ півці́ Твоєму́ вели́чествію, А́нгели Твоя́ по о́бразу соді́лав, Непостижи́ме.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","Ти непрекло́нни на го́ршая, к Тебі́ прибли́женієм, Христе́, сохрани́л єси́ Твоя́ слу́ги: істо́чник бо бла́гости Ти єси́, благотворя́ досто́йно Ті служа́щим.","Пресвята́я Богоро́дице, спаси́ нас.","Умерщвле́нную мою́ ду́шу страстьми́ ме́рзькими, Всенепоро́чная, оживи́, животу́ Храни́теля ро́ждши, і к стезі́ ві́чній і блаже́нному житію́ устреми́."]},{"h":"Пісня 6","ps":["Ірмос: Іо́ну в ки́ті, Го́споди, єди́наго всели́л єси́, мене́ же свя́заннаго мре́жами вра́жіїми, я́ко от тлі о́наго, спаси́.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","Боголі́пно от несущества́, Го́споди, сло́вом приве́л єси́ существа́ Небе́сних, Безсме́ртне, во́їнств, світови́дни сих соді́ловая.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","Служи́теліє честні́ї Бо́жия хвале́нія би́сте, безпло́тнії, гра́ждане Небе́снії, і Боже́ственная воі́стину ски́нія, Творцю́ досто́йно служа́ще.","Пресвята́я Богоро́дице, спаси́ нас.","Всепі́тая, Сві́та поро́ждши, всім світ даю́щаго, тьму мої́х прегріше́ній, Чи́стая, отжени́ Ма́терніми Твої́ми к Нему́ моли́твами."]},{"h":"Кондак, глас 2","ps":["Архістрати́зі Бо́жії, служи́теліє Боже́ственния сла́ви, А́нгелов нача́льници і челові́ков наста́вници, поле́зноє нам просі́те і ве́лію ми́лость, я́ко безпло́тних Архістрати́зі."]},{"h":"Ікос","ps":["Рекл єси́, Человіколю́бче, в писа́ніїх Твої́х, мно́жеству ра́доватися А́нгел о челові́ці єди́нім ка́ющемся, Безсме́ртне: тім і ми в беззако́нніїх су́ще, безгрі́шне Єди́не Сердцеві́дче, Тя моли́ти всегда́ дерза́єм я́ко благоутро́бнаго, уще́дрити нас і посла́ти недосто́йним умиле́ніє, Влади́ко, і пода́ти нам проще́ніє гріхо́в: о всіх бо нас мо́ляться Тебі́, я́ко безпло́тних Архістрати́зі."]},{"h":"Пісня 7","ps":["Ірмос: о́троци євре́йстії в пещі́ попра́ша пла́мень дерзнове́нно і на ро́су огнь преложи́ша, вопію́ще: благослове́н єси́, Го́споди Бо́же, во ві́ки.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","Сві́ти яви́л єси́, Ще́дре, А́нгел Твої́х невеще́ственноє существо́, неізрече́ннаго сві́та ісполня́єми, непреста́нно зову́щия: благослове́н єси́, Го́споди Бо́же, во ві́ки.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","Єму́же предстоя́ть непреста́нно служа́ща тьми а́нгельськия, лиця́ же зрі́ти не терп'я́т Божества́: благослове́н єси́, зову́ща, Бо́же, во ві́ки.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","Сло́вом Твої́м іпоста́сним, Го́споди, а́нгельськоє єстество́ соді́лал єси́, освяти́в же Боже́ственним Ду́хом, Тро́йцю богосло́вити научи́л єси́, Бо́же, во ві́ки.","Пресвята́я Тро́йце, Бо́же наш, сла́ва Тебі́.","Три у́бо зря́ще су́щия Іпоста́си, неопи́санноє сла́вим Существо́, Отця́ і Сло́ва со Ду́хом, вопію́ще: благослове́н єси́, Го́споди Бо́же оте́ць на́ших."]},{"h":"Пісня 8","ps":["Ірмос: На горі́ святі́й просла́вльшася і в купині́ огне́м Присноді́ви Моїсе́йові та́йну я́вльшего, Го́спода по́йте і превозносі́те во вся ві́ки.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","А́нгельському поревну́єм житію́ і ра́зум впери́м к висоті́, і с ни́ми невеще́ственно воспоє́м Го́спода і превозно́сим во ві́ки.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","Лико́вственници ли́ка Небе́снаго, і́же Престо́л обстоя́ще сла́ви, о Бо́зі всегда́ обраща́ємі, А́нгели пою́ть і славосло́в'ять во вся ві́ки.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","Невеще́ственна огня́ творя́щей пла́ми, на висоті́ непреста́нно служа́щих, і А́нгели ду́хи явля́ющей, Тро́йці покланя́ємся і славосло́вим во вся ві́ки.","Пресвята́я Богоро́дице, спаси́ нас.","І́же во утро́бу все́льшася Ді́ви, і от Сея́ стра́нно і ви́ше сло́ва, дре́вняго Ада́ма назда́вша, Го́спода поє́м і славосло́вим во ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Уста́ви прешла́ єси́ єстества́, Соді́теля заче́нши і Го́спода, і двер спасе́нія ми́рові била́ єси́. Тім Тя, Богоро́дице, непреста́нно велича́єм.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","Тя, неізрече́нно совокупи́вшаго Небе́сним, Христе́, земна́я, і єди́ну Це́рков соверши́вша А́нгелом і челові́ком, непреста́нно велича́єм.","Святі́ї Арха́нгели і А́нгели, молі́те Бо́га о нас.","А́нгели і Арха́нгели, Престо́ли, Вла́сті же і Госпо́дствія, Нача́ла і Си́ли, і Херуви́ми і Серафи́ми, с Богоро́дицею о ми́рі молі́теся.","Пресвята́я Тро́йце, Бо́же наш, сла́ва Тебі́.","Тя, Тро́йце, сла́вим, от небиті́я вся сотвори́вшую, і чи́ни а́нгельськия украси́вшую, і Боже́ственними заря́ми просвіти́вшую конці́.","Пресвята́я Богоро́дице, спаси́ нас.","Ра́дуйся, свята́я Богоневі́сто, ра́дуйся, Світ ми́рові ро́ждши ві́рним, ра́дуйся, стіно́ і покро́ве всіх нас. Бо́га, я́ко благода́теля, за ни непреста́нно моли́."]},{"h":"Світилен. Подібен: Духом во святилищі","ps":["О́гненних, Архістрати́же, слуг предста́тельство от Отця́ прия́л єси́ Михаї́ле, сві́тов, / тім і сія́ніє Того́ сла́ви сія́ющеє і́маши, / окру́г пречи́стаго Престо́ла ти предстоя́, / я́ко пе́рвий Невеще́ственних чино́в.","Слава, подібен: Со ученики́: Невеще́ственних Сил, Арха́нгел і А́нгел, / Госпо́дьств, і Престо́л, і Нача́л предста́тель пред Бо́гом постоя́нний, / Архістрати́же Боже́ственне, Михаї́ле пресла́вне, / нестерпи́мому бо Престо́лу предстоя́й, / покри́й, соблюди́, сохрани́ і спаси́ вся, ві́рою тя почита́ющия, / мирська́го предста́теля.","І нині, Богородичен: Честні́йшая єси́ Херуви́м сла́вних і Серафи́м, Всепі́тая, / стра́шних без сравне́нія сла́внійшая / і всіх святи́х А́нгел святі́йшая, Пречи́стая: / Зижди́теля бо всіх пло́тськи неізрече́нно родила́ єси́, Богоро́дице. / Єго́же моли́ рабо́м Твої́м разріше́ніє дарова́ти прегріше́ній."]},{"h":"Молитва всім чинам Ангельським","ps":["Усі святі Небесні безплотні Сили, удостойте мене сили, щоб знищувати все зло й пристрасті під ногами моїми. Святі безплотні Серафими, удостойте мене мати полум’яне серце до Бога. Святі безплотні Херувими, удостойте мене мати премудрість для слави Божої. Святі безплотні Престоли, удостойте мене розрізняти істину від неправди. Святі безплотні Господства, удостойте мене панувати над пристрастями, щоб дух підкорив плоть. Святі безплотні Сили, удостойте мене мати мужність у виконанні волі Божої. Святі безплотні Власті, удостойте мене мати силу перемоги над злом. Святі безплотні Начала, удостойте мене служити Господу Богові в непорочності серця й діл рук моїх. Святі безплотні Архангели, удостойте мене виконувати волю Господа нашого Ісуса Христа. Святі безплотні Ангели, удостойте мене керуватися заповідями Божими в усі дні життя мого."]},{"h":"Молитва всім святим і безплотним Небесним Силам","ps":["Бо́же Святи́й і во святи́х почива́яй, трисвяти́м гла́сом на Небесі́ от А́нгел воспіва́ємий, на землі́ от челові́к во святи́х Свої́х хвали́мий; да́вий Святи́м Твої́м Ду́хом коєму́ждо благода́ть по мі́рі дарова́нія Христо́ва, і то́ю поста́вивий Це́ркві Твоє́й святі́й о́ви Апо́столи, о́ви проро́ки, о́ви же благові́стники, о́ви па́стирі і учи́тели, ї́хже сло́вом про́повіді, Тебі́ Самому́ ді́йствующему вся во всіх, мно́зі соверши́шася святі́ї в ко́ємждо ро́ді і ро́ді, разли́чними доброді́тельми благоугоди́вшії Тебі́, і к Тебі́, нам о́браз до́брих по́двигов свої́х оста́вивше, в ра́дості преше́дшії, гото́ві, в не́мже са́мі іскуше́ни би́ша, і нам напа́ствуємим помога́ти. Сих святи́х всіх воспомина́я і їх богоуго́дноє похваля́я житіє́, Тебі́ Самаго́ в них ді́йствовавшаго восхваля́ю і о́ніх благотворе́нія Твоя́ дарова́нія би́ти ві́руя, прилі́жно молю́ Тя, Свя́те святи́х, даждь мі, грі́шному, послі́довати їх уче́нію, житію́, любве́, ві́рі, долготерпі́нію, і їх моли́твенною по́мощію, па́че же Твоє́ю вседі́йствующею благода́тію, небе́сния с ни́ми сподо́битися сла́ви, хва́ляще Пресвято́є і́м'я Твоє́, Отця́ і Си́на і Свята́го Ду́ха во ві́ки. Амі́нь."]}],"notes":[]},{"u":"Молитовне послідування з каноном покаянним про гріх вбивства дітей в утробі (аборт)","e":"Prayer service with a canon of repentance for the sin of killing children in the womb (abortion)","secs":[{"ps":["Го́споди Ісу́се Христе́, Си́не Бо́жий, моли́тв ра́ди Пречи́стия Твоєя́ Ма́тере і всіх святи́х, поми́луй нас. Амі́нь.","Сла́ва Тебі́, Бо́же наш, сла́ва Тебі́.","Царю́ Небе́сний, Уті́шителю, Ду́ше і́стини, І́же везді́ сий і вся ісполня́яй, Сокро́вище благи́х і жи́зні Пода́телю, прийди́ і всели́ся в ни, і очи́сти ни от вся́кия скве́рни, і спаси́, Бла́же, ду́ші на́ша.","Святи́й Бо́же, Святи́й Крі́пкий, Святи́й Безсме́ртний, поми́луй нас. Три́жди, і три покло́на.","Сла́ва Отцю́, і Си́ну, і Свято́му Ду́ху, і ни́ні і при́сно, і во ві́ки віко́в. Амі́нь.","Пресвята́я Тро́йце, поми́луй нас: Го́споди, очи́сти гріхи́ на́ша; Влади́ко, прости́ беззако́нія на́ша; Святи́й, посіти́ і ісціли́ не́мощі на́ша, і́мене Твоєго́ ра́ди.","Го́споди, поми́луй. Тричі.","Слава, і нині:","О́тче наш, І́же єси́ на Небесі́х, да святи́ться і́м'я Твоє́, да при́йдеть Ца́рствіє Твоє́, да бу́деть во́ля Твоя́, я́ко на Небесі́, і на землі́. Хліб наш насу́щний даждь нам днесь; і оста́ви нам до́лги на́ша, я́коже і ми оставля́єм должнико́м на́шим; і не введи́ нас во іскуше́ніє, но ізба́ви нас от лука́ваго."]},{"h":"Тропарі, глас 6","ps":["Поми́луй нас, Го́споди, поми́луй нас; / вся́каго бо отві́та недоумі́юще, / сію́ Ті моли́тву я́ко Влади́ці / грі́шнії прино́сим: поми́луй нас.","Слава:","Го́споди, поми́луй нас, / на Тя бо упова́хом; / не прогні́вайся на ни зіло́, / ніже́ пом'яни́ беззако́ній на́ших, / но при́зри і ни́ні, я́ко благоутро́бен, / і ізба́ви ни от враг на́ших: / Ти бо єси́ Бог наш, / і ми лю́діє Твої́, / всі діла́ руку́ Твоє́ю, / і і́м'я Твоє́ призива́єм.","І нині:","Милосе́рдія две́рі отве́рзи нам, / благослове́нная Богоро́дице, / наді́ющіїся на Тя да не поги́бнем, / но да ізба́вимся Тобо́ю от бід: / Ти бо єси́ спасе́ніє ро́да христия́нськаго.","Го́споди, поми́луй. (12 разів)","Слава, і нині:","Прийді́те, поклоні́мся Царе́ві на́шему Бо́гу. Покло́н.","Прийді́те, поклоні́мся і припаде́м Христу́, Царе́ві на́шему Бо́гу. Покло́н.","Прийді́те, поклоні́мся і припаде́м Самому́ Христу́, Царе́ві і Бо́гу на́шему. Покло́н."]},{"h":"Псалом 50","ps":["Поми́луй м'я, Бо́же, по вели́цій ми́лості Твоє́й, і по мно́жеству щедро́т Твої́х очи́сти беззако́ніє моє́. Найпа́че оми́й м'я от беззако́нія моєго́, і от гріха́ моєго́ очи́сти м'я; я́ко беззако́ніє моє́ аз зна́ю, і гріх мой предо мно́ю єсть ви́ну. Тебі́ єди́ному согріши́х, і лука́воє пред Тобо́ю сотвори́х; я́ко да оправди́шися во словесі́х Твої́х, і побіди́ши, внегда́ суди́ти Ті. Се бо в беззако́ніїх зача́т єсьм, і во грісі́х роди́ м'я ма́ти моя́. Се бо і́стину возлюби́л єси́, безві́стная і та́йная прему́дрости Твоєя́ яви́л мі єси́. Окропи́ши м'я іссо́пом, і очи́щуся; оми́єши м'я, і па́че сні́га убілю́ся. Слу́ху моєму́ да́си ра́дость і весе́ліє; возра́дуються ко́сті смире́нния. Отврати́ лице́ Твоє́ от гріх мої́х, і вся беззако́нія моя́ очи́сти. Се́рдце чи́сто сози́жди во мні, Бо́же, і дух прав обнови́ во утро́бі моє́й. Не отве́ржи мене́ от лиця́ Твоєго́, і Ду́ха Твоєго́ Свята́го не отими́ от мене́. Возда́ждь мі ра́дость спасе́нія Твоєго́, і Ду́хом Влади́чним утверди́ м'я. Научу́ беззако́нния путе́м Твої́м, і нечести́вії к Тебі́ обратя́ться. Ізба́ви м'я от крове́й, Бо́же, Бо́же спасе́нія моєго́; возра́дується язи́к мой пра́вді Твоє́й. Го́споди, устні́ мої́ отве́рзеши, і уста́ моя́ возвістя́ть хвалу́ Твою́. Я́ко а́ще би восхоті́л єси́ же́ртви, дал бих у́бо: всесожже́нія не благоволи́ши. Же́ртва Бо́гу дух сокруше́н; се́рдце сокруше́нно і смире́нно Бог не унічижи́ть. Ублажи́, Го́споди, благоволе́нієм Твої́м Сіо́на, і да сози́ждуться сті́ни Ієрусали́мськія. Тогда́ благоволи́ши же́ртву пра́вди, возноше́ніє і всесожега́ємая; тогда́ возложа́ть на олта́р Твой тельці́."]},{"h":"Канон покаянний до Господа нашого Ісуса Христа для чоловіків і жінок, винних у гріху убивства дітей (читається келійно)","ps":[]},{"h":"Глас 6. Пісня 1","ps":["Ірмос: Я́ко по су́ху пішеше́ствовав Ізра́їль, / по бе́здні стопа́ми, / гони́теля фарао́на / ви́дя потопля́єма, / Бо́гу побі́дную піснь пої́м, вопія́ше.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я.","Ни́ні приступи́х аз, грі́шний(ая) і обремене́нний(ая) гріхо́м детоуби́йства, к Тебі́, Влади́ці і Бо́гу моєму́; / не смі́ю же взира́ти на не́бо, то́кмо молю́ся, глаго́ля: / даждь мі, Го́споди, ум, / да пла́чуся діл мої́х го́рко.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я.","О, го́ре мні грі́шному(єй)! / Па́че всіх челові́к окая́нен єсьм, / покая́нія ність во мні; / даждь мі, Го́споди, сле́зи, / да пла́чуся діл мої́х го́рко.","Сла́ва Отцю́, і Си́ну, і Свято́му Ду́ху.","Безу́мне, окая́нне челові́че, / в нераді́нії о покая́нії вре́м'я губи́ши; / поми́сли житіє́ твоє́, і обрати́ся ко Го́споду Бо́гу, / і пла́чися о ді́ліх твої́х го́рко.","І ни́ні і при́сно, і во ві́ки віко́в. Амі́нь.","Богородичен: Ма́ти Бо́жия Пречи́стая, / воззри́ на м'я грі́шнаго(ую), і от сі́ті дия́воли ізба́ви м'я, / і на путь покая́нія наста́ви м'я, / да пла́чуся діл мої́х го́рко."]},{"h":"Пісня 3","ps":["Ірмос: Ність свят, / я́коже Ти, Го́споди Бо́же мой, / вознеси́й рог ві́рних Твої́х, Бла́же, / і утверди́вий нас на ка́мені / іспові́данія Твоєго́.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я.","Внегда́ поста́влені бу́дуть престо́ли на Суди́щі Стра́шнім, / тогда́ всіх челові́к діла́ облича́ться; / го́ре та́мо бу́деть грі́шному(єй), в му́ку отсила́ємому(єй); / і то ві́дущи, душе́ моя́, пока́йся от злих діл твої́х.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я.","Пра́ведници возра́дуються, а грі́шнії воспла́чуться; / тогда́ нікто́же возмо́жеть помощи́ нам, / но діла́ на́ша осу́дять нас; / ті́мже пре́жде конця́ пока́йся от злих діл твої́х.","Сла́ва Отцю́, і Си́ну, і Свято́му Ду́ху.","Уви́ мні великогрі́шному(єй), / і́же(я́же) ді́ли і ми́сльми оскверни́вся(шися), / ні ка́плі слез імі́ю от жестосе́рдія; / ни́ні возни́кни от землі́, душе́ моя́, / і пока́йся от злих діл твої́х.","І ни́ні і при́сно, і во ві́ки віко́в. Амі́нь.","Богородичен: Се взива́єть, Госпоже́, Син Твой, і поуча́єть нас на до́броє, / аз же грі́шний(ая) добра́ всегда́ бі́гаю; / но Ти, Ми́лостивая, поми́луй м'я, / да пока́юся от злих мої́х діл.","Го́споди, поми́луй. Тричі."]},{"h":"Сідален, глас 6","ps":["Помишля́ю день стра́шний і пла́чуся дія́ній мої́х лука́вих: / ка́ко отвіща́ю Безсме́ртному Царю́, / іли́ ко́їм дерзнове́нієм воззрю́ на Судію́, блу́дний(ая) аз? / Благоутро́бний О́тче, Си́не Єдиноро́дний і Ду́ше Святи́й, поми́луй м'я.","Слава, і нині, Богородичен:","Свя́зан(а) мно́гими ни́ні плени́цями гріхо́в / і содержи́м(а) лю́тими страстьми́ і біда́ми, / к Тебі́ прибіга́ю, моєму́ спасе́нію, і вопію́: / помози́ мі, Ді́во, Ма́ти Бо́жия."]},{"h":"Пісня 4","ps":["Ірмос: Христо́с моя́ си́ла, / Бог і Госпо́дь, / честна́я Це́рков / боголі́пно поє́ть, взива́ющи / от сми́сла чи́ста, о Го́споді пра́зднующи.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я.","Широ́к путь зді і уго́дний сла́сті твори́ти, / но го́рко бу́деть в послі́дній день, / єгда́ душа́ от ті́ла разлуча́тися бу́деть; / блюди́ся от сих, челові́че, Ца́рствія ра́ди Бо́жия.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я.","Почто́ по́хоть і блуд безу́мне твори́ши, / сластьми́ ми́ра сего́ пленя́єшися, / любо́в роди́тельську попира́єши / і своє́ беззащи́тноє ча́до убива́єши? / Пока́йся у́бо, душе́ моя́, Ца́рствія ра́ди Бо́жия.","Сла́ва Отцю́, і Си́ну, і Свято́му Ду́ху.","О безу́мний челові́че, / доко́лі угліба́єши, я́ко пчела́, собира́ющи бога́тство твоє́? / Вско́рі бо поги́бнеть, я́ко прах і пе́пел; / но бо́ліє взищи́ Ца́рствія Бо́жия.","І ни́ні і при́сно, і во ві́ки віко́в. Амі́нь.","Богородичен: Богоро́дице, поми́луй м'я грі́шнаго(ую), / і в доброді́телі укріпи́, / і соблюди́ м'я, да на́глая смерть не похи́тить м'я негото́ваго(ую), / і доведи́ м'я, Ді́во, Ца́рствія Бо́жия."]},{"h":"Пісня 5","ps":["Ірмос: Бо́жиїм сві́том Твої́м, Бла́же, / у́тренюющих Ті ду́ші любо́вію озари́, молю́ся, / Тя ві́діти, Сло́ве Бо́жий, / і́стиннаго Бо́га, / от мра́ка гріхо́внаго взива́юща.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я.","Воспом'яни́ гріхи́ твоя́, окая́нний челові́че, / ка́ко себ'ялю́біє, сребролю́біє, жестокосе́рдіє і по́хоть чадоуби́йцею соді́лаша тя. / Душе́ моя́ грі́шная, того́ ли восхоті́ла єси́?","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я.","Трепе́щуть мі у́ди, всі́ми бо сотвори́х вину́: / очи́ма взира́яй, уши́ма сли́шай, / язи́ком зла́я глаго́ляй, / всего́ себе́ геє́нні предая́й; / душе́ моя́ грі́шная, сего́ ли восхоті́ла єси́?","Сла́ва Отцю́, і Си́ну, і Свято́му Ду́ху.","Блудника́ і разбо́йника ка́ющася прия́л єси́, Спа́се, аз же єди́н(а) лі́ностію гріхо́вною отягчи́хся і злим діло́м порабо́тихся; душе́ моя́ грі́шная, сего́ ли восхоті́ла єси́?","І ни́ні і при́сно, і во ві́ки віко́в. Амі́нь.","Богородичен: Ди́вная і ско́рая Помо́щнице всім челові́ком, Ма́ти Бо́жия, / помози́ мні недосто́йному(єй), / душа́ бо моя́ грі́шная того́ восхоті́."]},{"h":"Пісня 6","ps":["Ірмос: Жите́йськоє мо́ре / воздвиза́ємоє зря напа́стей бу́рею, / к ти́хому приста́нищу Твоєму́ прите́к, вопію́ Ті: / возведи́ от тлі живо́т мой, Многоми́лостиве.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я.","Житіє́ на землі́ блу́дно пожи́х і ду́шу во тьму преда́х, / ни́ні у́бо молю́ Тя, Ми́лостивий Влади́ко: / свободи́ м'я от рабо́ти человікоуби́йці дия́вола / і даждь мі ра́зум твори́ти во́лю Твою́.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я.","Кому́ уподо́билася єси́, душе́ моя́? / Ка́їну окая́нному пе́рвому уби́йці і І́роду беззако́нному детоуби́йце. / Но Ти, Го́споди, істо́ргни м'я от гріха́ сего́ / і даждь мі се́рдце твори́ти за́повіді Твоя́.","Сла́ва Отцю́, і Си́ну, і Свято́му Ду́ху.","Воспряни́, окая́нний челові́че, к Бо́гу, воспом'яну́в своя́ согріше́нія, / припа́дая ко Творцю́, слезя́ і стеня́; / Той же, я́ко милосе́рд, дасть ті ум зна́ти во́лю Свою́.","І ни́ні і при́сно, і во ві́ки віко́в. Амі́нь.","Богородичен: Богоро́дице Ді́во, / от ви́димаго і неви́димаго зла сохрани́ м'я, Пречи́стая, / і прийми́ моли́тви моя́, і донеси́ я Си́ну Твоєму́, / да дасть мі ум твори́ти во́лю Єго́.","Го́споди, поми́луй. Тричі.","Слава, і нині:"]},{"h":"Кондак, глас 6","ps":["Душе́ моя́, почто́ гріха́ми богаті́єши, / почто́ во́лю дия́волю твори́ши, / в чесо́м наде́жду полага́єши? / Преста́ни от сих і обрати́ся к Бо́гу с пла́чем, зову́щи: / милосе́рде Го́споди, поми́луй м'я грі́шнаго(ую)."]},{"h":"Ікос","ps":["Поми́сли, душе́ моя́, го́ркий час сме́рти / і Стра́шний Суд Творця́ твоєго́ і Бо́га: / А́нгели бо гро́знії по́ймуть тя, душе́, / і во ві́чний огнь введу́ть: / у́бо пре́жде сме́рти пока́йся, вопію́щи: / Го́споди, поми́луй м'я грі́шнаго(ую)."]},{"h":"Пісня 7","ps":["Ірмос: Росода́тельну у́бо пещ / соді́ла А́нгел / преподо́бним отроко́м, / халде́ї же опаля́ющеє / велі́ніє Бо́жиє мучи́теля увіща́ вопи́ти: / благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я.","Не наді́йся, душе́ моя́, на тлі́нноє бога́тство і на непра́ведноє собра́ніє, / вся бо сія́ не ві́си кому́ оста́виши, но возопи́й: / поми́луй м'я, Христе́ Бо́же, в чадоуби́йстві пови́ннаго(ую).","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я.","Не упова́й, душе́ моя́, на тіле́сноє здра́віє і на скоромимоходя́щую красоту́, / ви́диши бо, я́ко си́льнії і младі́ї умира́ють; но возопи́й: / поми́луй м'я, Христе́ Бо́же, чадоуби́йцю скве́рнаго(ую).","Сла́ва Отцю́, і Си́ну, і Свято́му Ду́ху.","Воспом'яни́, душе́ моя́, ві́чноє житіє́, Ца́рство Небе́сноє, угото́ванноє святи́м, / і тьму кромі́шную і гнів Бо́жий злим, і возопи́й: / поми́луй м'я, Христе́ Бо́же, тя́жко согріши́вшаго(ую).","І ни́ні і при́сно, і во ві́ки віко́в. Амі́нь.","Богородичен: Припади́, душе́ моя́, к Бо́жієй Ма́тері і помоли́ся Той, / єсть бо ско́рая Помо́щниця ка́ющимся, / умо́лить Си́на Христа́ Бо́га, / і поми́луєть м'я покая́ніє принося́щаго(ую)."]},{"h":"Пісня 8","ps":["Ірмос: Із пла́мене преподо́бним ро́су істочи́л єси́ / і пра́веднаго же́ртву водо́ю попали́л єси́: / вся бо твори́ши, Христе́, то́кмо є́же хоті́ти. / Тя превозно́сим во вся ві́ки.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я.","Ка́ко не і́мам пла́катися, єгда́ помишля́ю о соде́янном мно́ю, / вім бо зол мої́х мно́жество, дітоуби́йця сий(су́щи). / Что у́бо ча́ю і на что наді́юся? / То́кмо даждь мі, Го́споди, пре́жде конця́ покая́ніє.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я.","О, Го́споди, жи́зні Пода́телю! / За мно́гая Твоя́ бла́га возда́х Тебі́ злом, окая́нний(ая), / отверго́х пренебе́сний дар жи́зні / і дарова́нная Тобо́ю ча́да погуби́х, / но во смире́нії молю́: / даждь мні, Го́споди, прежде́ конця́ покая́ніє.","Сла́ва Отцю́, і Си́ну, і Свято́му Ду́ху.","Ві́рую, я́ко при́йдеши суди́ти живи́х і ме́ртвих, / і всі во своє́м чи́ну ста́нуть, / ста́рії і младі́ї, влади́ки і кня́зі, ді́ви і свяще́нници; / гді обря́щуся аз? / Сего́ ра́ди вопію́: / даждь мі, Го́споди, пре́жде конця́ покая́ніє.","І ни́ні і при́сно, і во ві́ки віко́в. Амі́нь.","Богородичен: Пречи́стая Богоро́дице, / прийми́ недосто́йную моли́тву мою́, / і сохрани́ м'я от на́глия сме́рти, / і да́руй мі пре́жде конця́ покая́ніє."]},{"h":"Пісня 9","ps":["Ірмос: Бо́га / челові́ком невозмо́жно ви́діти, / на Него́же не смі́ють чи́ни А́нгельстії взира́ти; / Тобо́ю же, Всечи́стая, яви́ся челові́ком / Сло́во воплоще́нно, Єго́же велича́юще, / с Небе́сними во́ї Тя ублажа́єм.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я.","Ни́ні к вам прибіга́ю, А́нгели, Арха́нгели і вся Небе́сния Си́ли, у Престо́ла Бо́жия стоя́щії, / молі́теся ко Творцю́ своєму́, / да ізба́вить ду́шу мою́ от му́ки ві́чния.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я.","Ни́ні пла́чуся к вам, святі́ї патріа́рсі, ца́ріє і проро́ци, / апо́столи і святи́теліє і всі ізбра́ннії Христо́ви: / помозі́те мі на Суді́, / да спасе́ть ду́шу мою́ от си́ли вра́жия.","Сла́ва Отцю́, і Си́ну, і Свято́му Ду́ху.","Ни́ні к вам воздіжу́ ру́ці, святі́ї му́ченици, / пусти́нници, ді́вственници, пра́ведници і всі святі́ї, / моля́щіїся ко Го́споду за весь мир, / да поми́луєть м'я в час сме́рти моєя́.","І ни́ні і при́сно, і во ві́ки віко́в. Амі́нь.","Богородичен: Ма́ти Бо́жия, помози́ мі, на Тя си́льні наді́ющемуся(єйся), / умоли́ Си́на Своєго́, да очи́стить м'я от тя́жкаго гріха́ детоуби́йства / і покая́нія моєго́ ра́ди да́руєть проще́ніє, / єгда́ ся́деть судя́й живи́х і ме́ртвих. Амі́нь."]},{"h":"Потім","ps":["Досто́йно єсть я́ко воі́стину блажи́ти Тя, Богоро́дицю, Присноблаже́нную і Пренепоро́чную і Ма́тер Бо́га на́шего. Честні́йшую Херуви́м і сла́внійшую без сравне́нія Серафи́м, без істлі́нія Бо́га Сло́ва ро́ждшую, су́щую Богоро́дицю Тя велича́єм. Поклін.","Трисвяте. Слава, і нині: Пресвята́я Тро́йце: Го́споди, поми́луй. Тричі. Слава, і нині: О́тче наш:"]},{"h":"Тропар, глас 1","ps":["Об'я́тія О́тча отве́рсти мі потщи́ся, / блу́дно моє́ іжди́х житіє́, / на бога́тство неіждива́ємоє взира́яй щедро́т Твої́х, Спа́се: / ни́ні обнища́вшеє моє́ да не пре́зриши се́рдце. / Тебі́ бо, Го́споди, умиле́нієм зову́: / согріши́х, на Не́бо і пред Тобо́ю.","Слава, і нині, Богородичен:","Упова́ніє христия́н, Пресвята́я Ді́во, / Єго́же родила́ єси́ Бо́га па́че ума́ же і сло́ва, / непреста́нно моли́ с го́рніми си́лами, / да́ти оставле́ніє гріхо́в нам всім, / і ісправле́ніє житія́, ві́рою і любо́вію при́сно Тя чту́щим.","Го́споди, поми́луй. (40 разів)"]},{"h":"Молитва","ps":["Го́споди, Ісу́се Христе́, Си́не Бо́жий, Істо́чниче жи́зні і безсме́ртія, прише́дий в мир грі́шния спасти́! При́зри на нас, недосто́йних рабо́в Твої́х, ви́ю се́рдця і тілесе́ пред вели́чеством сла́ви Твоєя́ приклоня́ющих, согріши́хом бо, беззако́нновахом, непра́вдовахом пред Тобо́ю, но, на щедро́ти Твоя́ і ми́лость Твою́ упова́юще, со слеза́ми мо́лим: благоутро́бне і всеми́лостиве Го́споди, прости́ і поми́луй нас, любо́в Твою́ отве́ргших, зако́н єва́нгельський попра́вших, страстьми́ ум свой ослепи́вших, чад свої́х в безу́мії уби́вших, іни́х к сему́ сме́ртному гріху́ подви́гших іли́ престу́пному їх намі́ренію не возбрани́вших.","Ві́ми, Го́споди, я́ко досто́йни єсьми́ огня́ геє́нськаго і ві́чния му́ки, но і́мами і человіколю́бія Твоєго́ о́брази: разбо́йника, митаря́, блудни́цю, блу́днаго си́на, і́же покая́нієм отверзе́ніє две́рей Ца́рствія Небе́снаго і поми́лованіє улучи́вших. Ті́мже ко мно́жеству щедро́т Твої́х взива́єм: прийми́ і́скреннєє раская́ніє на́ше і се́рдце, оскверне́нноє безмі́рними гріха́ми, человіколю́бне очи́сти.","При́зри, всеси́льне Го́споди, на лю́ди Твоя́, вразуми́ бра́тій і сесте́р на́ших, творя́щих беззако́нія; возсія́й і́стиною Твоє́ю в сердця́х заблу́дших і во тьмі пребива́ющих, загради́ уста́ нечести́вая і лука́вая, дітоуби́йство пропове́дующая; просвіти́ ра́зум ма́терей, чад свої́х во чре́ві своє́м умерщвля́ющих; удержи́ ру́ку врача́-детоуби́йці всеси́льною десни́цею Твоє́ю; пресіки́ твори́моє крова́воє беззако́ніє.","О, многоми́лостиве і долготерпіли́ве Го́споди! Моли́твами Пречи́стия Твоєя́ Ма́тере, Влади́чиці на́шея Богоро́диці і Присноді́ви Марі́ї і всіх святи́х, найпа́че хода́тайством святи́х му́чеников младе́нцев, во Вифлеє́мі от І́рода убіє́нних, да́руй нам вре́м'я на покая́ніє, я́ко да, по за́повідем Твої́м пожи́вше, настоя́щих зол і бу́дущих ві́чних мук свободі́мся і со благо́ю наде́ждою і і́стинним увіре́нієм к та́мошнему ми́ру по́йдем, прославля́юще Безнача́льнаго Твоєго́ Отця́, с Ни́мже благослове́н єси́, со Пресвяти́м і Благи́м і Животворя́щим Твої́м Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Потім","ps":["Честні́йшую Херуви́м і сла́внійшую без сравне́нія Серафи́м, без істлі́нія Бо́га Сло́ва ро́ждшую, су́щую Богоро́дицю Тя велича́єм.","Слава, і нині:","Го́споди, поми́луй. Тричі.","Го́споди Ісу́се Христе́, Си́не Бо́жий, моли́тв ра́ди Пречи́стия Твоєя́ Ма́тере, преподо́бних і богоно́сних оте́ць на́ших і всіх святи́х, поми́луй і спаси́ нас, я́ко Благ і Человіколю́бець. Амі́нь."]}],"notes":[]},{"u":"Канон подячний до Пресвятої Богородиці","e":"Canon of thanksgiving to the Most Holy Theotokos","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Отве́рзу уста́ моя́, / і напо́лняться Ду́ха, / і сло́во отри́гну Цари́це Ма́тері, / і явлю́ся, сві́тло торжеству́я, / і воспою́, ра́дуяся, Тоя́ чудеса́.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Христо́ву кни́гу одушевле́нную, запечатлі́нную Тя Ду́хом, / вели́кий Арха́нгел, Чи́стая, зря возглаша́ше Ті: / ра́дуйся, ра́дости прия́телище, / Є́юже прама́терняя кля́тва разріши́ться.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Ада́мово ісправле́ніє, ра́дуйся / Ді́во Богоневі́сто, а́дово умерщвле́ніє. / Ра́дуйся Всенепоро́чная, пала́то всіх Царя́: / ра́дуйся, престо́ле о́гненний Вседержи́теля.","Слава: Цві́те неув'яда́ємий, ра́дуйся / єди́на прозя́бшая я́блоко благово́нноє. / Ра́дуйся ро́ждшая благоуха́ніє єди́наго Царя́. / Ра́дуйся Неіскуобра́чная, ми́рові спасе́ніє.","І нині: Чистоти́ сокро́вище, ра́дуйся, / Є́юже от паде́нія на́шего воста́хом. / Ра́дуйся, сладкоуха́нний кри́не Влади́чице, / ві́рних благоуха́яй, кади́ло благово́нноє, / і ми́ро многоце́нноє."]},{"h":"Пісня 3","ps":["Ірмос: Твоя́ пісносло́вці, Богоро́дице, / Живи́й і Незави́стний Істо́чниче, / лик себі́ совоку́пльшія, духо́вно утверди́, / в Боже́ственній Твоє́й сла́ві / вінце́в сла́ви сподо́би.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Клас прозя́бшая Боже́ственний, я́ко ни́ва неора́нная я́ві, / ра́дуйся одушевле́нная трапе́зо, хліб живо́тний вмі́щшая. / Ра́дуйся, живо́тния води́ істо́чниче неістоща́ємий, Влади́чице.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Ю́нице Юнця́ ро́ждшая непоро́чнаго, ра́дуйся ві́рним. / Ра́дуйся А́гнице, ро́ждшая Бо́жіяго А́гнця, / взе́млющаго ми́ра всего́ прегріше́нія. / Ра́дуйся те́плоє очисти́лище.","Слава: У́тро світлі́йшеє, ра́дуйся / єди́на Со́лнця нося́щая Христа́, сві́та жили́ще. / Ра́дуйся, тьму разруши́вшая, / і мра́чния бі́си отню́д отгна́вшая.","І нині: Ра́дуйся, две́ре єди́на, / Є́юже Сло́во про́йде єди́но, / вереї́ і врата́ а́дова, Влади́чице, Рождество́м Твої́м сокруши́вшая. / Ра́дуйся, Боже́ственний вхо́де спаса́ємих, Богоневі́сто."]},{"h":"Пісня 4","ps":["Ірмос: Сідя́й в Сла́ві / на Престо́лі Божества́ / во о́блаці ле́гці, / при́йде Ісу́с Пребоже́ственний, / Нетлі́нною Дла́нію / і спасе́ зову́щия: / сла́ва, Христе́, си́лі Твоє́й.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Во гла́сіх пі́ній, Ді́во / Тебі́ вопіє́м Всепі́тая: / ра́дуйся, ту́чная горо́ і усире́нная Ду́хом. / Ра́дуйся сві́щниче, і ста́мно ма́нну нося́щая, / услажда́ющая всіх благочести́вих чу́вства.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Очисти́лище ми́ру, ра́дуйся, Пречи́стая Влади́чице. / Ра́дуйся лі́ствице, от землі́ всіх возви́сившая благода́тію. / Ра́дуйся мо́сте, воі́стину преводя́й всіх / от сме́рти к животу́ пою́щих Тя.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Небе́с преви́шшая, ра́дуйся, землі́ основа́ніє / в Твої́х ложесна́х Пречи́стая, нетру́дно носи́вшая. / Ра́дуйся червлени́це, багряни́цю Боже́ственную омочи́вшая, / от крове́й Твої́х, Царе́ві си́лам.","Слава: Законода́вця ро́ждшая і́стиннаго, ра́дуйся Влади́чице, / беззако́нія всіх ту́не очища́ющаго. / Недові́домая глубино́, висото́ неізрече́нная, браконеїску́сная, / Є́юже ми обожи́хомся.","І нині: Тя іспле́тшую ми́рові нерукоплете́нний віне́ць пісносло́вим, / ра́дуйся, Тебі́ Ді́во зову́ще: / храни́лище всіх і огражде́ніє, і утвержде́ніє, / і свяще́нноє прибі́жище."]},{"h":"Пісня 5","ps":["Ірмос: Ужасо́шася вся́чеськая / о Боже́ственній сла́ві Твоє́й: / Ти бо, Неіскусобра́чная Ді́во, / імі́ла єси́ во утро́бі над всі́ми Бо́га / і родила́ єси́ Безлі́тнаго Си́на, / всім воспіва́ющим Тя / мир подава́ющая.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Путь ро́ждшая жи́зні, ра́дуйся Пренепоро́чная, / от пото́па гріхо́внаго мир спа́сшая: / ра́дуйся Богоневі́сто, сли́шаніє і глаго́ланіє стра́шноє: / ра́дуйся пребива́ніє Влади́ки тва́рі.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Крі́пость і утвержде́ніє челові́ков, ра́дуйся Пречи́стая, / мі́сто освяще́нія сла́ви, умерщвле́ніє а́дово, черто́же всесві́тлий. / Ра́дуйся а́нгелов ра́досте: / ра́дуйся по́моще ві́рно моля́щихся Тебі́.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Огнеобра́зная колесни́це Сло́ва, ра́дуйся Влади́чице, / одушевле́нний раю́, дре́во посреді́ іму́щи жи́зні Го́спода, / Єго́же сла́дость оживотворя́єть ві́рою причаща́ющихся, і тлі подклони́вшихся.","Слава: Укріпля́ємі си́лою Твоє́ю, ві́рно вопіє́м Ті: / ра́дуйся, гра́де всіх Царя́, / пресла́вная і достосли́шанная о Не́йже глаго́лана би́ша я́ві, горо́ несіко́мая: / ра́дуйся глубино́ неізмі́римая.","І нині: Простра́нноє селе́ніє Сло́ва, ра́дуйся Пречи́стая, / сосу́де, Боже́ственний би́сер проізве́дшая. / Ра́дуйся, всечу́дноє всіх к Бо́гу примире́ніє, / блажа́щих Тя Богоро́дице всегда́."]},{"h":"Пісня 6","ps":["Ірмос: Боже́ственноє сіє́ і всечестно́є / соверша́юще пра́зднество, / Богому́дрії, Богома́тере, / прийді́те, рука́ми воспле́щим, / от Нея́ ро́ждшагося Бо́га сла́вим.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Черто́же Сло́ва нескве́рний, вина́ всіх обоже́нія, / ра́дуйся Пречи́стая, проро́ков оглаше́ніє: / ра́дуйся, апо́столов удобре́ніє.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","От Тебе́ роса́ ука́ну, пла́мень многобо́жія угаси́вшая. / Тім вопіє́м Ті: / ра́дуйся, руно́ одушевле́нноє, є́же Гедео́н, Ді́во, предви́ді.","Слава: Се Тебі́ Ді́во ра́дуйся, зове́м: / приста́нище нам бу́ди вла́ющимся, / і оти́шіє в пучи́ні скорбе́й, / і собла́знов всіх бори́теля.","І нині: Ра́дости вина́, облагодати́ наш по́мисл, є́же зва́ти Тебі́: / ра́дуйся неопали́мая купино́, о́блаче всесві́тлий, / ві́рния непреста́нно осіня́ющий."]},{"h":"Пісня 7","ps":["Ірмос: Не послужи́ша тва́рі Богому́дрії, / па́че Созда́вшаго, / но о́гненноє преще́ніє му́жеськи попра́вше, / ра́довахуся, пою́ще: / препі́тий отце́в Госпо́дь і Бог благослове́н єси́.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Воспіва́єм Тя вопію́ще: / ра́дуйся, колесни́це со́лнця у́мнаго, / лозо́ і́стинная, грозд зрі́лий возді́лавшая, вино́ істоча́ющий, / ду́ші веселя́щеє ві́рою Тя сла́в'ящих.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Врача́ всіх челові́к ро́ждшая, ра́дуйся Богоневі́сто, / же́зле та́йний, цвіт неув'яда́ємий процві́тшій, / ра́дуйся Влади́чице, Є́юже ра́дости наполня́ємся, і жизнь наслі́дствуєм.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Віти́йствующий не мо́жеть язи́к, Влади́чице, пісносло́вити Тя, / па́че бо серафи́мов возви́силася єси́, ро́ждши Царя́ Христа́. / Єго́же моли́ гра́ду сему́ ізба́витися от мно́гих іскуше́ній.","Слава: Хва́лять Тя блажа́ще конці́, і любо́вію зову́ть Тебі́: / ра́дуйся сви́тче, в не́мже пе́рстом О́тчим написа́ся Сло́во, Чи́стая. / Єго́же моли́, в кни́зі живо́тній / рабо́м Твої́м написа́тися Богоро́дице.","І нині: Мо́лим, раби́ Твої́, і приклоня́єм колі́но се́рдця на́шего: / приклони́ у́хо Твоє́, Чи́стая, / і спаси́ скорбми́ погружа́ємия при́сно, / і соблюди́ от вся́каго вра́жия пліне́нія Твой град, Богоро́дице."]},{"h":"Пісня 8","ps":["Ірмос: О́троки благочести́вия в пещі́ / Рождество́ Богоро́дичо спасло́ єсть, / тогда́ у́бо образу́ємоє, / ни́ні же ді́йствуємоє, / вселе́нную всю воздвиза́єть пі́ти Тебі́: / Го́спода по́йте діла́ / і превозносі́те Єго́ во вся ві́ки.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Ложесни́ Сло́во прия́ла єси́, / вся нося́щаго носи́ла єси́, / млеко́м пита́ла єси́, / ма́нієм пита́ющаго вселе́нную всю, Чи́стая, Єму́же поє́м: / Го́спода по́йте діла́, і превозносі́те во вся ві́ки.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Мойсе́й уразумі́ в купині́ вели́коє та́їнство Рождества́ Твоєго́: / о́троци же прообрази́ша сіє́ я́вственніє / посреді́ огня́ стоя́ще, і не опаля́ємі, нетлі́нная свята́я Ді́во. / Тім Тя почита́єм во вся ві́ки.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Пре́жде пре́лестію обнажи́вшіїся / в ри́зу нетлі́нія облеко́хомся Рождество́м Твої́м: / і сідя́щії во тьмі прегріше́ній, світ ви́діхом, / сві́та жили́ще, Отрокови́це. / Тім Тя поє́м во вся ві́ки.","Слава: Ме́ртвії Тобо́ю оживля́ються, / Жизнь бо іпоста́сную родила́ єси́, / німі́ї пре́жде, благоглаго́ливи бива́ють, / прокаже́ннії очища́ються, неду́зі отгоня́ються, / духо́во возду́шних мно́жества побіжда́ються, / Ді́во, челові́ков спасе́ніє.","І нині: Ми́ру ро́ждшая спасе́ніє, / і́мже от землі́ на висоту́ взя́ти би́хом, / ра́дуйся всеблагослове́нная, покро́ве і держа́во, / стіно́ і утвержде́ніє пою́щим, Чи́стая: / Го́спода по́йте діла́, і превозносі́те во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Всяк земноро́дний / да взигра́ється, Ду́хом просвіща́єм, / да торжеству́єть же Безпло́тних умо́в єстество́, / почита́ющеє свяще́нноє торжество́ Богома́тере, / і да вопіє́ть: / ра́дуйся, Всеблаже́нная, / Богоро́дице Чи́стая Присноді́во.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Да Тебі́, ві́рнії, ра́дуйся зове́м, / Тобо́ю ра́дости прича́стници би́вше присносу́щния, / ізба́ви нас напа́стей, ва́рварськаго пліне́нія, і вся́кия іни́я ра́ни, / за мно́жество, Отрокови́це, прегріше́ній, / находя́щия челові́ком согреша́ющим.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Яви́лася єси́ просвіще́ніє на́ше і утвержде́ніє. / Ті́мже вопіє́м Ті: / ра́дуйся звіздо́ незаходи́мая, вводя́щая в мир вели́коє Со́лнце. / Ра́дуйся, Єде́м отве́рзшая заключе́нний, Чи́стая. / Ра́дуйся сосу́де, ми́ро неістощи́моє на Тя ізлія́нноє приє́мшій.","Приспів: Пресвята́я Богоро́дице, спаси́ нас.","Ста́нем благогові́йно в дому́ Бо́га на́шего, і возопії́м: / ра́дуйся, ми́ру Влади́чице. / Ра́дуйся Марі́є, Госпоже́ всіх нас. / Ра́дуйся, єди́на непоро́чная в жена́х і до́брая. / Ра́дуйся, сто́лпе о́гненний, вводя́щий во ви́шнюю жизнь челові́чество.","Слава: Голуби́це Ми́лостиваго ро́ждшая, ра́дуйся Присноді́во: / преподо́бних всіх, ра́дуйся похвало́, страда́льцев вінча́ніє. / Ра́дуйся всіх пра́ведних Боже́ственноє удобре́ніє, / і нам ві́рним спасе́ніє.","І нині: Пощади́, Бо́же, наслі́діє Твоє́, / гріхи́ на́ша вся презрі́в ни́ні, / на сіє́ імі́я моля́щую Тя, / на землі́ безсі́менно Тебі́ Ро́ждшую, / вели́кия ра́ди ми́лости восхоті́вшаго / вообрази́тися, Христе́, в челові́чество."]},{"h":"Молитва до Пресвятої Богородиці","ps":["Нескве́рная, Небла́зная, Нетлі́нная, Пречи́стая, Чи́стая Ді́во, Богоневі́сто Влади́чице, я́же Бо́га Сло́ва челові́ком пресла́вним Твої́м Рождество́м соєдини́вшая, і отри́нувшеєся єстество́ ро́да на́шего небе́сним совоку́пльшая: я́же ненаде́жних єди́на Наде́жда, і бори́мих по́моще, гото́воє заступле́ніє к Тебі́ притека́ющих, і всіх христия́н прибі́жище. Не гнуша́йся мене́ грі́шнаго, скве́рнаго, скве́рними по́мисли, і словеси́, і дія́ньми всего́ себе́ непотре́бна сотво́рша, і ра́зумом лі́ності сласте́й житія́ раба́ би́вша; но я́ко человіколюби́ваго Бо́га Ма́ти, человіколю́бне умилосе́рдися о мні грі́шнім і блу́днім, і прийми́ моє́, є́же от скве́рних усте́н приноси́моє Тебі́ моле́ніє, і Твоєго́ Си́на, і на́шего Влади́ку і Го́спода, ма́тернєє Твоє́ дерзнове́ніє употребля́ющи, моли́, да отве́рзеть і мні человіколю́бния утро́би Своєя́ бла́гости, і презрі́в моя́ безчи́сленная прегріше́нія, обрати́ть м'я к покая́нію, і Свої́х за́повідей ді́лателя іску́сна яви́ть м'я. І предста́ни мні при́сно, я́ко ми́лостивая, і милосе́рдая, і благолюби́вая, в настоя́щем у́бо житії́ те́плая Предста́тельнице і Помо́щнице, сопроти́вних наше́ствія отгоня́ющи, і ко спасе́нію наставля́ющи м'я: і во вре́м'я ісхо́да моєго́ окая́нную мою́ ду́шу соблюда́ющи, і те́мния зра́ки лука́вих бісо́в дале́че от нея́ отгоня́ющи: в стра́шний же день суда́ ві́чния м'я ізбавля́ющи му́ки, і неізрече́нния сла́ви Твоєго́ Си́на і Бо́га на́шего наслі́дника м'я показу́ющи. Ю́же і да улучу́, Влади́чице моя́, Пресвята́я Богоро́дице, Твої́м хода́тайством і заступле́нієм, благода́тію і человіколю́бієм Єдиноро́днаго Си́на Твоєго́, Го́спода і Бо́га і Спа́са на́шего Ісу́са Христа́. Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м, і Пресвяти́м, і Благи́м, і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в, амі́нь."]},{"h":"Молитва друга до Пресвятої Богородиці","ps":["Прийми́, всеблагомо́щная, пречи́стая госпоже́ Влади́чице Богороди́тельнице, сія́ честни́я да́ри, Тебі́ єди́ній прикла́дния, от нас недосто́йних рабо́в Твої́х, от всіх родо́в ізбра́нная, всіх тва́рей небе́сних і земни́х ви́шшая я́вльшаяся. Поне́же бо Тебе́ ра́ди бисть Госпо́дь сил с на́ми, і Тобо́ю Си́на Бо́жия позна́хом, і сподо́бихомся свята́го Ті́ла Єго́, і пречи́стия Кро́ве Єго́. Ті́мже блаже́нна єси́ в ро́діх родо́в, богоблаже́нная, херуви́мов світлі́йши, і серафи́мов честні́йши су́щая. І ни́ні, всепі́тая Пресвята́я Богоро́дице, не преста́й моля́щися о нас недосто́йних рабі́х Твої́х, є́же ізба́витися нам от вся́каго сові́та лука́ваго, і от вся́каго обстоя́нія: і сохрани́тися нам неврежде́нним от вся́каго ядови́таго прило́га дия́вольськаго. Но да́же до конця́ моли́твами Твої́ми неосужде́нних нас соблюди́: я́ко да Твої́м заступле́нієм і по́мощію спаса́ємі, сла́ву, хвалу́, благодаре́ніє і поклоне́ніє за вся, в Тро́йці єди́ному Бо́гу і всіх Созда́телю возсила́єм, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Канон усім святим","e":"Canon to All Saints","secs":[{"h":"Тропар, глас 2","ps":["Апо́столи, му́ченици і проро́ци, святи́теліє, преподо́бнії і пра́веднії, до́брі по́двиг соверши́вшії і ві́ру соблю́дшії, дерзнове́ніє іму́ще ко Спа́су, о нас Того́, я́ко Бла́га, молі́те спасти́ся, мо́лимся, душа́м на́шим."]},{"h":"Канон, глас 8. Пісня 1","ps":["Ірмос: Піснь возсле́м лю́діє чу́дному Бо́гу на́шему, свободи́вшему Ізра́їля от рабо́ти, піснь побі́дную пою́ще і вопію́ще: поє́м Тебі́ Єди́ному Влади́ці.","Приспів: Всі святі́ї, молі́те Бо́га о нас.","Проро́чеський собо́ре, апо́стольськоє сосло́віє, му́ченик во́їнства, Влади́ку всіх молі́те спасти́ся мні, прегріше́нії мно́гими обдержи́мому.","Приспів: Всі святі́ї, молі́те Бо́га о нас.","Ієра́ршеський собо́ре, преподо́бнії і пра́веднії всі, благ ві́чних улучи́ти молі́теся, ві́рою вас блажа́щим.","Слава: Всіх святи́х Твої́х, Го́споди, воспіва́єм чи́ни, я́ко моли́твами їх озаря́єши ду́ші на́ша: Ти бо єси́ Світ непристу́пний, неві́дінія мрак отгоня́яй, присносу́щними Твої́ми сві́тлостьми.","І нині: Пресвята́я Ді́во Ма́ти, я́же Бо́га, Пресвято́є Сло́во, родила́ єси́, освяти́ всіх ві́рою Тя со всі́ми святи́ми сла́в'ящих, мо́лимтися."]},{"h":"Пісня 3","ps":["Ірмос: Ти єси́ утвержде́ніє притека́ющих к Тебі́, Го́споди, Ти єси́ Світ омраче́нних, і поє́ть Тя дух мой.","Приспів: Всі святі́ї, молі́те Бо́га о нас.","Свяще́ннійший лик вас Боже́ственних проро́к велича́єм, і му́ченик мно́жество, пострада́вших крі́пко, почита́єм моля́щеся: да ю́же сла́ву получи́сте, сея́ і ми прича́стници би́ти сподо́бимся ва́шими моли́твами.","Приспів: Всі святі́ї, молі́те Бо́га о нас.","Святі́йшії Христо́ви ієра́рсі, і честні́ї преподо́бних собо́ри, со всі́ми святи́ми о всіх нас Человіколю́бця Бо́га молі́те, мо́лим ви.","Слава: Зако́ну повину́ющеся Твоєму́, уго́дников Твої́х собо́ри, многообра́зними доброді́тельми освіти́шася: сего́ ра́ди наслі́дници би́ша оби́телей Твої́х Небе́сних, Влади́ко Царю́: ї́хже моли́твами, да і нас та́можде всели́ши, Преми́лостиве.","І нині: Богора́дованная Чи́стая, со всі́ми проро́ки, му́дрими, апо́столи, священному́ченики і со всі́ми пра́ведними, моли́ Го́спода, я́ко да соверше́нноє разріше́ніє прегріше́ній при́ймем."]},{"h":"Пісня 4","ps":["Ірмос: Усли́шах, Го́споди, смотре́нія Твоєго́ та́їнство, разумі́х діла́ Твоя́ і просла́вих Твоє́ Божество́.","Приспів: Всі святі́ї, молі́те Бо́га о нас.","Восхваля́єм вас, благоглаго́ливії проро́ци, і воспіва́єм богови́дці апо́столи, со всі́ми до́брі о Го́споді тече́ніє соверша́вшими: я́ко да моли́твами ва́шими і ми настоя́щаго житія́ тече́ніє богоуго́дно соверши́ти возмо́жем.","Приспів: Всі святі́ї, молі́те Бо́га о нас.","Я́ко многосві́тлия зві́зди, доброді́телей сві́тлостію озаря́єте ві́рних ісполне́нія, преподо́бнії отці́ на́ші, і вся Бо́жії уго́дниці: сего́ ра́ди вас ублажа́єм.","Слава: Совоку́плься собо́р святи́х Твої́х, Го́споди, ра́ди любве́, і тоя́ наслажда́ющеся, со А́нгели лику́єть о Тебі́, Всеви́дче Го́споди всіх: є́гоже ликовствова́нія да і нас сподо́биши, моли́твами уго́дников Твої́х, Всеси́льне.","І нині: Єди́на Бо́га Воплоще́ннаго ро́ждши, Всесвята́я, Того́ умоли́ в день стра́шний всіх нас спасти́, і жи́зні ві́чния, і сві́та сподо́бити, єго́же зрять всі до́брі угоди́вшії."]},{"h":"Пісня 5","ps":["Ірмос: У́тренююще вопіє́м Ті, Го́споди, спаси́ ни: Ти бо єси́ Бог наш, ра́зві Тебе́ іно́го не ві́ми.","Приспів: Всі святі́ї, молі́те Бо́га о нас.","Святи́теліє, проро́ци, преподо́бнійшії отці́ і богоно́сці, луча́ми Ду́ха просвіща́юще всю твар, тьму разоря́йте страсте́й на́ших, мо́лим ви.","Приспів: Всі святі́ї, молі́те Бо́га о нас.","Ра́ни ва́ша і я́зви, врагу́ яви́шася я́зви неісці́льния: я́зви же ни́ні ісціля́ють всім ві́рним, страда́льці Госпо́дні.","Слава: Ієра́рхи Твоя́, і священному́ченики, і вся святи́я просвіти́вий, Го́споди, тіх моли́твами уще́дри м'я, ві́дий безмі́рная моя́ прегріше́нія.","І нині: Пречи́стая Ді́во, похвало́ му́чеников, преподо́бних і пра́ведних, і всіх святи́х, от вся́каго мучи́тельства лука́ваго ізми́ м'я, молю́ся."]},{"h":"Пісня 6","ps":["Ірмос: Ри́зу мні пода́ждь сві́тлу, одія́йся сві́том я́ко ри́зою, Многоми́лостиве Христе́ Бо́же наш.","Приспів: Всі святі́ї, молі́те Бо́га о нас.","Денни́ця світоза́рная позна́ні би́сте на землі́, благоче́стія сві́том озари́вше ві́рния, пресла́внії Христо́ви ору́жници і святи́теліє пра́веднії.","Приспів: Всі святі́ї, молі́те Бо́га о нас.","Умерщвле́ни би́вше ран мно́гих наведе́ньми, жизнь і́стинную наслі́довасте: вку́пі молі́те Христа́ спасти́ вся ві́рния, святі́ї му́ченици.","Слава: Сла́ва прему́дрим святи́телем, і преподо́бним, і всім святи́м, Ти єси́, Христе́: моли́твами їх лю́ди Твоя́ уще́дри, ї́хже Своє́ю кро́вію, я́ко Человіколю́бець, стяжа́л єси́.","І нині: Воспіва́єм Тя ві́рнії, Богора́дованная Влади́чице: Препі́таго бо Бо́га роди́ла єси́. Єго́же моли́, Пречи́стая, гра́ду і лю́дем Твої́м в ми́рі спасти́ся."]},{"h":"Кондак, глас 8","ps":["Я́ко нача́тки єстества́ Насади́телю тва́рі, вселе́нная прино́сить Ті, Го́споди, богоно́сния му́ченики: тіх моли́твами в ми́рі глубо́ці, Це́рков Твою́, жи́тельство Твоє́, Богоро́дицею соблюди́, Многоми́лостиве."]},{"h":"Ікос","ps":["І́же по всей землі́ му́чившіїся, і на Небеса́ пресели́вшіїся, і́же стра́сті Христо́ви подража́вшії, і стра́сті на́ша отье́млющії, зді днесь собира́ються, перворожде́нних показу́юще Це́рков, я́ко го́рнія о́браз содержа́щу, і Христу́ вопію́щу: Бог мой єси́ Ти, Богоро́дицею соблюди́ м'я, Многоми́лостиве."]},{"h":"Пісня 7","ps":["Ірмос: О́троци благочести́вії во Вавило́ні о́бразу злато́му не поклони́шася, но посреді́ о́гненния пе́щі ороша́ємі, піснь воспіва́ху, глаго́люще: превозноси́мий отце́в і нас, Бо́же, благослове́н єси́.","Приспів: Всі святі́ї, молі́те Бо́га о нас.","Святи́х чи́ни, во святи́х почива́ющаго немо́лчно восхваля́юще, пи́щі небе́сния наслажда́єтеся, і ра́дующеся лику́єте пою́ще: отце́в на́ших Бо́же, благослове́н єси́.","Приспів: Всі святі́ї, молі́те Бо́га о нас.","Світозра́чнії святи́теліє, і преподо́бнії, і проро́ци, і священному́ченик досточу́дноє мно́жество, і в по́стничестві просія́вшії сві́тло, при́сно о нас молі́теся, да поми́ловані бу́дем, пою́щії с ва́ми: отце́в на́ших Бо́же, благослове́н єси́.","Слава: Ра́дующеся поє́м Твої́х, Го́споди, всіх святи́х собо́р отвсю́ду собра́вшихся, і ро́ди вку́пі, і досто́їнства, і жи́тельства, і с ни́ми поє́м зову́ще: отце́в на́ших Бо́же, благослове́н єси́.","І нині: С му́ченики, Пречи́стая, с преподо́бними отці́, с проро́ки і всі́ми святи́ми, во святи́х Єди́наго Почива́ющаго умоли́ всіх освяти́ти нас, славосло́в'ящих Тя во вся ві́ки."]},{"h":"Пісня 8","ps":["Ірмос: Богоглаго́ливії о́троци в пещі́, со огне́м пла́мень попира́юще поя́ху: благослові́те діла́ Госпо́дня, Го́спода.","Приспів: Всі святі́ї, молі́те Бо́га о нас.","Святи́теліє, проро́ци, апо́столи, му́ченици і всі святі́ї, по́двиг сконча́вше, свяще́нноє улучи́сте водворе́ніє со А́нгели: с ни́ми же просі́те очище́нія всім нам і ве́лія ми́лости.","Приспів: Всі святі́ї, молі́те Бо́га о нас.","Умертви́вше плоть болі́зньми мно́гими, жи́зні сподо́бистеся бу́дущия, преподо́бнії: ю́же получи́ти і нам молі́теся, уго́дниці Бо́жії, мо́лим ви.","Слава: Свяще́нници Твої́, Христе́, пра́вдою облече́ни преподо́бне і всі святі́ї от ві́ка, ни́ні ку́пно ра́дуються, Твою́ добро́ту зря́ще Боже́ственную ясні́йше: ю́же зрі́ти і нас, ра́ди святи́х Твої́х предста́тельства сподо́би, Человіколю́бче.","І нині: Богороди́тельнице Чи́стая, со всі́ми проро́ки, і му́ченики, і преподо́бними, священному́ченики і со всі́ми святи́ми, уще́дрити нас Всеми́лостиваго Спа́са моли́, мо́лимтися."]},{"h":"Пісня 9","ps":["Ірмос: Воі́стину Богоро́дицю Тя іспові́дуєм, спасе́ннії Тобо́ю, Ді́во Чи́стая, с безпло́тними ли́ки Тя велича́юще.","Приспів: Всі святі́ї, молі́те Бо́га о нас.","Вас, священноді́йственнії па́стиріє, проро́к святи́х лик, пра́ведних безчи́сленноє мно́жество, му́ченик собо́р, по́стников, ді́вственников і всіх святи́х, свяще́нними пі́сньми ублажа́єм, да мо́лите всіх Вла́дику о спасе́нії душ на́ших.","Приспів: Всі святі́ї, молі́те Бо́га о нас.","Я́ко служи́теліє Влади́ці, священнотаї́нници я́вльшеся, совокупи́стеся служи́телем небе́сним: с ни́миже о нас моле́нія приносі́те, мо́лим вас.","Слава: Со священному́ченики ку́пно, і со всі́ми проро́ки, ублажа́єм вся преподо́бния і пра́ведния, ді́ви і же́ни сві́тло до́блествовавшия: тіх мольба́ми, Христе́, ізба́ви геє́нни ду́ші на́ша.","І нині: Щедролюби́ваго Бо́га ро́ждшая пло́тію, со святи́ми всі́ми моли́ Того́ при́сно от бід спасти́ нас, всегда́ Тя велича́ющих, Ма́ти Ді́во Чи́стая."]},{"h":"Молитва","ps":["Бо́же Святи́й і во святи́х почива́яй, трисвяти́м гла́сом на Небесі́ от А́нгел воспіва́ємий, на землі́ от челові́к во святи́х Свої́х хвали́мий; да́вий Святи́м Твої́м Ду́хом коєму́ждо благода́ть по мі́рі дарова́нія Христо́ва, і то́ю поста́вивий Це́ркві Твоє́й святі́й о́ви Апо́столи, о́ви проро́ки, о́ви же благові́стники, о́ви па́стирі і учи́тели, ї́хже сло́вом про́повіді, Тебі́ Самому́ ді́йствующему вся во всіх, мно́зі соверши́шася святі́ї в ко́ємждо ро́ді і ро́ді, разли́чними доброді́тельми благоугоди́вшії Тебі́, і к Тебі́, нам о́браз до́брих по́двигов свої́х оста́вивше, в ра́дості преше́дшії, гото́ві, в не́мже са́мі іскуше́ни би́ша, і нам напа́ствуємим помога́ти. Сих святи́х всіх воспомина́я і їх богоуго́дноє похваля́я житіє́, Тебі́ Самаго́ в них ді́йствовавшаго восхваля́ю і о́ніх благотворе́нія Твоя́ дарова́нія би́ти ві́руя, прилі́жно молю́ Тя, Свя́те святи́х, даждь мі, грі́шному, послі́довати їх уче́нію, житію́, любве́, ві́рі, долготерпі́нію, і їх моли́твенною по́мощію, па́че же Твоє́ю вседі́йствующею благода́тію, небе́сния с ни́ми сподо́битися сла́ви, хва́ляще Пресвято́є і́м'я Твоє́, Отця́ і Си́на і Свята́го Ду́ха во ві́ки. Амі́нь."]},{"h":"Молитва","ps":["О преблаже́ннії уго́дниці Бо́жії, всі святі́ї, предстоя́щії Престо́лу Пресвяти́я Тро́йці і наслажда́ющіїся неізрече́ннаго блаже́нства! Се ни́ні, в день о́бщаго ва́шего торжества́, ми́лостивно при́зріте на нас, ме́ньших бра́тій ва́ших, принося́щих вам сіє́ хвале́бноє пі́ніє і хода́тайством ва́шим прося́щих ми́лості і отпуще́нія гріхо́в у Преблага́го Го́спода: ві́ми бо, воі́стину ві́ми, я́ко вся, єли́ка восхо́щете, іспроси́ти у Него́ мо́жете. Ті́мже у́бо смире́нно мо́лимся вам: молі́те Ми́лостиваго Влади́ку, да пода́сть нам дух ва́шея ре́вности ко хране́нію святи́х Єго́ за́повідей, я́ко да те́кше по стопа́м ва́шим, возмо́жем земно́є по́прище в доброді́тельном житії́ без поро́ка прейти́ і в покая́нії дости́гнути пресла́вних селе́ній ра́йських, і та́мо ку́пно с ва́ми прославля́ти Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Канон за спочилих","e":"Canon for the departed","secs":[{"ps":["Моли́твами святи́х оте́ць на́ших, Го́споди Ісу́се Христе́ Бо́же наш, поми́луй нас. Амі́нь.","Святи́й Бо́же, Святи́й крі́пкий, Святи́й безсме́ртний, поми́луй нас. (Читається тричі, з хресним знаменням і поясним поклоном.)","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","Пресвята́я Тро́йце, поми́луй нас; Го́споди, очи́сти гріхи́ на́ша; Влади́ко, прости́ беззако́нія на́ша; Святи́й, посіти́ і ісціли́ не́мощі на́ша, і́мене Твоєго́ ра́ди.","Го́споди, поми́луй. (тричі)","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","О́тче наш, І́же єси́ на небесі́х, да святи́ться і́м'я Твоє́, да при́йдеть Ца́рствіє Твоє́, да бу́деть во́ля Твоя́, я́ко на небесі́ і на землі́. Хліб наш насу́щний даждь нам днесь; і оста́ви нам до́лги на́ша, я́коже і ми оставля́єм должнико́м на́шим; і не введи́ нас во іскуше́ніє, но ізба́ви нас от лука́ваго.","Го́споди, поми́луй. (12 разів)","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","Прийді́те, поклоні́мся Царе́ві на́шему Бо́гу. (поклін)","Прийді́те, поклоні́мся і припаде́м Христу́, Царе́ві на́шему Бо́гу. (поклін)","Прийді́те, поклоні́мся і припаде́м Самому́ Христу́, Царе́ві і Бо́гу на́шему. (поклін)"]},{"h":"Псалом 90","ps":["Живи́й в по́мощі Ви́шняго, в кро́ві Бо́га небе́снаго водвори́ться. Рече́ть Го́сподеві: засту́пник мой єси́ і прибі́жище моє́, Бог мой, і упова́ю на Него́. Я́ко Той ізба́вить тя от сі́ті ло́вчі, і от словесе́ м'яте́жна. Плещма́ Свої́ма осіни́ть тя, і под крилі́ Єго́ наді́єшися, ору́жієм оби́деть тя і́стина Єго́. Не убої́шися от стра́ха нощна́го, от стрі́ли летя́щия во дні, от ве́щі во тьмі преходя́щия, от сря́ща і бі́са полу́деннаго. Паде́ть от страни́ твоєя́ ти́сяща, і тьма одесну́ю тебе́, к тебі́ же не прибли́житься. Оба́че очи́ма твої́ма смо́триши і воздая́ніє грі́шников у́зриши. Я́ко Ти, Го́споди, упова́ніє моє́; Ви́шняго положи́л єси́ прибі́жище твоє́. Не при́йдеть к тебі́ зло, і ра́на не прибли́житься тілесі́ твоєму́. Я́ко А́нгелом Свої́м запові́сть о тебі́, сохрани́ти тя во всіх путеіх твої́х. На рука́х во́зьмуть тя, да не когда́ преткне́ши о ка́мень но́гу твою́. На а́спида і васили́ска насту́пиши, і попере́ши льва і змі́я. Я́ко на М'я упова́, і ізба́влю ї: покри́ю ї, я́ко позна́ і́м'я Моє́. Воззове́ть ко Мні, і усли́шу єго́, с ним єсьм в ско́рбі, ізму́ єго́ і просла́влю єго́, долгото́ю дній іспо́лню єго́ і явлю́ єму́ спасе́ніє Моє́.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","Аллилу́я, аллилу́я, аллилу́я, сла́ва Тебі́, Бо́же. (тричі)","Го́споди, поми́луй. (тричі)"]},{"h":"Тропар, глас 8","ps":["Глубино́ю му́дрости человіколю́біє вся стро́яй і поле́зная всім подава́яй, Єди́не Соді́телю, упоко́й, Го́споди, ду́ші раб Твої́х, на Тя бо упова́ніє возложи́ша, Творця́ і Зижди́теля і Бо́га на́шего.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","Богородичен: Те́бі і сті́ну, і приста́нище і́мами, і моли́твенницю благоприя́тну к Бо́гу, Єго́же родила́ єси́, Богоро́дице Безневі́стная, ві́рних спасе́ніє."]},{"h":"Псалом 50","ps":["Поми́луй м'я, Бо́же, по вели́цій ми́лості Твоє́й, і по мно́жеству щедро́т Твої́х очи́сти беззако́ніє моє́. Найпа́че оми́й м'я от беззако́нія моєго́, і от гріха́ моєго́ очи́сти м'я. Я́ко беззако́ніє моє́ аз зна́ю, і гріх мой предо мно́ю єсть ви́ну. Те́бі єди́ному согріши́х і лука́воє пред Тобо́ю сотвори́х, я́ко да оправди́шися во словесі́х Твої́х і побіди́ши, внегда́ суди́ти Ті. Се бо, в беззако́ніїх зача́т єсьм, і во грісі́х роди́ м'я ма́ти моя́. Се бо, і́стину возлюби́л єси́, безві́стная і та́йная прему́дрости Твоє́й яви́л мі єси́. Окропи́ши м'я іссо́пом, і очи́щуся, оми́єши м'я, і па́че сні́га убілю́ся. Слу́ху моєму́ да́си ра́дость і весе́ліє, возра́дуються ко́сті смире́нния. Отврати́ лице́ Твоє́ от гріх мої́х, і вся беззако́нія моя́ очи́сти. Се́рдце чи́сто сози́жди во мні, Бо́же, і дух прав обнови́ во утро́бі моє́й. Не отве́ржи мене́ от лиця́ Твоєго́, і Ду́ха Твоєго́ Свята́го не отими́ от мене́. Возда́ждь мі ра́дость спасе́нія Твоєго́ і Ду́хом влади́чним утверди́ м'я. Научу́ беззако́нния путе́м Твої́м, і нечести́вії к Тебі́ обратя́ться. Ізба́ви м'я от крове́й, Бо́же, Бо́же спасе́нія моєго́, возра́дується язи́к мой пра́вді Твоє́й. Го́споди, устні́ мой отве́рзеши, і уста́ моя́ возвістя́ть хвалу́ Твою́. Я́ко а́ще би восхоті́л єси́ же́ртви, дал бих у́бо, всесожже́нія не благоволи́ши. Же́ртва Бо́гу дух сокруше́н, се́рдце сокруше́нно і смире́нно Бог не унічижи́ть. Ублажи́, Го́споди, благоволе́нієм Твої́м Сіо́на, і да сози́ждуться сті́ни Ієрусали́мськія. Тогда́ благоволи́ши же́ртву пра́вди, возноше́ніє і всесожега́ємая, тогда́ возложа́ть на олта́р Твой тельці́."]},{"h":"Канон, глас 8. Пісня 1","ps":["Ірмос: Во́ду проше́д, я́ко су́шу, і єги́петськаго зла ізбіжа́в, ізра́їльтянин вопія́ше: Ізба́вителю і Бо́гу на́шему пої́м.","Приспів: Ди́вен Бог во святи́х Свої́х, Бог Ізра́їлев (поклін).","Сме́ртію смерть Христо́ву, і страстьми́ Страсть подража́вше честну́ю, му́ченици всі Боже́ственния і блаже́нния жи́зні получи́ша.","Поко́й, Го́споди, душі́ усо́пших раб Твої́х (поклін).","Ю́ности прегріше́нія презря́ і гріхи́ превосходя́, Христе́ Спа́се, пре́жде усо́пшия раби́ Твоя́ со ізбра́нними Твої́ми сопричти́.","Слава: Ю́же получи́ша сла́ву же і ра́дость, і́же блаже́нноє стяжа́вше пребива́ніє, пода́ждь бога́тно Твої́м рабо́м, я́же прия́л єси́, Многоми́лостиве.","І нині: Зачала́ єси́ Сло́во О́тчеє, пло́ті соєдини́вшеєся по іпоста́си, Є́же із Тебе́, всенепоро́чная Отрокови́це, ад Боже́ственною си́лою упраздни́вшеє."]},{"h":"Пісня 3","ps":["Ірмос: Небе́снаго кру́га Верхотво́рче Го́споди, і Це́ркві Зижди́телю, Ти мене́ утверди́ в любві́ Твоє́й, жела́ній кра́ю, ві́рних утвержде́ніє, Єди́не Человіколю́бче.","Приспів: Ди́вен Бог во святи́х Свої́х, Бог Ізра́їлев (поклін).","Очи́стившеся дре́вняго прароди́тельнаго паде́нія креще́нієм і па́ки порожде́нієм, струя́ми же крове́й свої́х окропи́вшеся, Христу́, блаже́ннії, сца́рствуєте.","Поко́й, Го́споди, душі́ усо́пших раб Твої́х.","І́же мертв во́лею поло́жся во гро́бі і живу́щия во гробі́х взива́яй, Спа́се, благоволи́, я́же от нас прия́л єси́, в селе́ніїх пра́ведних Твої́х сим водворя́тися.","Слава: Благоутро́бієм Боже́ственния Твоєя́, Влади́ко, і соєсте́ственні разуміва́ємия бла́гости умоле́н бива́я, гріхо́в разріше́ніє пода́в рабо́м Твої́м, Спа́се, упоко́й.","І нині: Вопло́щся із чре́ва Твоєго́, і бив Челові́к, І́же ізря́дне сий єди́н человіколю́бець, спаса́єть челові́ка от врат сме́ртних, Богома́ти Пречи́стая, єди́на всепі́тая.","Го́споди, поми́луй (тричі)."]},{"h":"Сідален, глас 6","ps":["Воі́стину суєта́ вся́чеськая, житіє́ же сінь і со́ніє, і́бо всу́є м'яте́ться всяк земноро́дний, я́коже рече́ Писа́ніє: єгда́ мир приобря́щем, тогда́ во гроб вселі́мся, іді́же вку́пі ца́ріє і ни́щії. Ті́мже, Христе́ Бо́же, преста́вльшихся упоко́й, я́ко человіколю́бець.","Сла́ва і ни́ні, Богоро́дичен: Всесвята́я Богоро́дице, во вре́м'я живота́ моєго́ не оста́ви мене́, челові́чеському предста́тельству не вві́ри м'я, но Сама́ заступи́ і поми́луй м'я."]},{"h":"Пісня 4","ps":["Ірмос: Ти моя́ крі́пость, Го́споди, Ти моя́ і си́ла, Ти мой Бог, ти моє́ ра́дованіє, не оста́вль ні́дра О́тча, і на́шу нищету́ посіти́в. Тім с проро́ком Авваку́мом зову́ Ті: си́лі Твоє́й сла́ва, Человіколю́бче.","Приспів: Ди́вен Бог во святи́х Свої́х, Бог Ізра́їлев (поклін).","Да Твоєя́, Влади́ко, сла́ви у́зрять, і сві́тлость Твою́ світода́тельную на небесі́х получа́ть сві́тло, всяк вид муче́ній носи́ти претерпі́ша му́ченици Боже́ственнії, Тебі́, Христе́, пою́ще: си́лі Твоє́й сла́ва, Человіколю́бче.","Поко́й, Го́споди, душі́ усо́пших раб Твої́х.","Мно́гі оби́телі у Тебе́, Спа́се, суть, по достоя́нію всім разділя́єми, по мі́рі доброді́телей: ти́я у́бо, Ще́дре, іспо́лнити сих сподо́би, я́же ві́рою преста́вльшіяся, благоче́стно Тебі́ вопію́щия: си́лі Твоє́й сла́ва, Человіколю́бче.","Слава: Ра́вен нам челові́к яви́лся єси́, Безсме́ртне, всім ра́вно смерть претерпі́л єси́ і жи́зні показа́л єси́ путь, єя́же преста́вльшіяся сподо́би, я́ко человіколю́бець, проще́ніє согріше́ній, я́ко Влади́ка подава́я, і сві́та прича́стіє да́руй.","І нині: Ти ві́рних похвала́ єси́, Безневі́стная, Ти предста́тельниця і Ти прибі́жище христия́н: стіна́ і приста́нище, к Си́ну Твоєму́ мольби́ но́сиши, Всенепоро́чная, і спаса́єши от бід і́же ві́рою і любо́вію Богоро́дице Чи́стую Тя веду́щия."]},{"h":"Пісня 5","ps":["Ірмос: Вску́ю м'я отри́нул єси́ от лиця́ Твоєго́, Сві́те незаходи́мий, і покри́ла м'я єсть чужда́я тьма, окая́ннаго; но обрати́ м'я і к сві́ту за́повідей Твої́х путі́ моя́ напра́ви, молю́ся.","Приспів: Ди́вен Бог во святи́х Свої́х, Бог Ізра́їлев (поклін).","Несказа́нния Твоєя́ сла́ви і є́же па́че сло́ва Твоєго́ блаже́нства, в селе́ніїх святи́х, іді́же глас красе́н пра́зднующих, преста́вленния к безстра́стній жи́зні, уще́дрив, сподо́би, Єди́не Человіколю́бче.","Поко́й, Го́споди, душі́ усо́пших раб Твої́х.","Іді́же чи́ни а́нгельстії, іді́же пра́ведних собо́ри ра́дуються, Авраа́ма в ні́дріх всели́, Спа́се, раби́ Твоя́, і со дерзнове́нієм стра́шному і Боже́ственному Престо́лу предста́ти благоволи́, Благоутро́бне.","Слава: Очище́ніє нам яви́лся єси́, пра́вда же і ізбавле́ніє, і я́звою Твоє́ю на́ша не́мощі уврачева́л єси́. Ти у́бо, Ще́дре, я́ко благ, преста́вльшіяся в сла́дості ра́йстій учини́.","І нині: Ми́лостивно, Ми́лостиве, челові́чества мі́ру восприя́л єси́, І́же Боже́ственния сла́ви преви́шшими украша́яй возвише́ньми, от Діви́чеських ложе́сн плоть приє́м одушевле́ну, слове́сну, є́юже смерть погуби́л єси́."]},{"h":"Пісня 6","ps":["Ірмос: Очи́сти м'я, Спа́се, мно́га бо беззако́нія моя́, і із глубини́ зол возведи́, молю́ся, к Тебі́ бо возопи́х, і усли́ши м'я, Бо́же спасе́нія моєго́.","Приспів: Ди́вен Бог во святи́х Свої́х, Бог Ізра́їлев (поклін).","Му́ченици Твої́, Спа́се, мно́гія муки́ претерпі́ша, любо́вію Твоє́ю душа́ми уязви́вшеся святі́ї, Твоєя́ жела́юще присносу́щния сла́ви і сла́дкаго Твоєго́ прича́стія.","Поко́й, Го́споди, душі́ усо́пших раб Твої́х.","Чре́во врага́ сме́ртію растерза́л єси́, Спа́се, і вся я́же в нем ю́зники воскреси́л єси́, живо́т дарова́вий, єго́же преста́вленния, Благоді́телю, сподо́би.","Слава: Слез і воздиха́нія су́щия во а́ді раби́ Твоя́ свободи́, Спа́се: я́ко єди́н бо благоутро́бен, от'ял єси́ вся́кую сле́зу от вся́каго лиця́ ві́рно благослов'я́щих Тя.","І нині: І́же єстество́м Соді́тель, соді́тельствується в ложесна́х Твої́х, по́лний, я́ко Бог, істощава́ється, Всенепоро́чная: єди́н Безсме́ртний, за всіх спасе́ніє умира́єть сме́ртію.","Го́споди, поми́луй (тричі). Сла́ва і ни́ні."]},{"h":"Кондак, глас 8","ps":["Со святи́ми упоко́й, Христе́, душі́ раб Твої́х, іді́же ність болі́знь, ні печа́ль, ні воздиха́ніє, но жизнь безконе́чная."]},{"h":"Ікос","ps":["Сам єди́н єси́ Безсме́ртний, сотвори́вий і созда́вий челові́ка; земні́ї у́бо от землі́ созда́хомся і в зе́млю ту́южде по́йдем, я́коже повелі́л єси́ созда́вий м'я і реки́й мі: я́ко земля́ єси́ і в зе́млю отидеши, а́може всі челові́ци по́йдем, надгро́бноє рида́ніє творя́ще піснь: аллилу́я, аллилу́я, аллилу́я."]},{"h":"Пісня 7","ps":["Ірмос: О́троци євре́йстії в пе́щі попра́ша пла́мень дерзнове́нно і на ро́су огнь преложи́ша, вопію́ще: благослове́н єси́, Го́споди Бо́же, во ві́ки.","Приспів: Ди́вен Бог во святи́х Свої́х, Бог Ізра́їлев (поклін).","Все жела́ніє му́чеников простре́ся ко єди́ному Влади́ці, любо́вію Тому́ соєдиня́ємоє, і пою́щеє: благослове́н єси́, Го́споди Бо́же, во ві́ки.","Поко́й, Го́споди, душі́ усо́пших раб Твої́х.","Подає́ши ві́рою преставльшимся сві́тлость Боже́ственнаго Ца́рствія, нетлі́нія оде́жду да́руяй вопію́щим: благослове́н єси́, Го́споди Бо́же, во ві́ки.","Слава: Іспо́лни ра́дости і весе́лія я́же преста́вил єси́ раби́ Твоя́, Ще́дре, сподо́бивий їх взива́ти Тебі́ і пі́ти: благослове́н єси́, Го́споди Бо́же, во ві́ки.","І нині: Разріша́я Є́вину кля́тву, в пренепоро́чную всели́лся єси́ Ді́ву, благослове́нія істо́чник істоча́я вопію́щим: благослове́н, Пречи́стая, Плод Твоєго́ чре́ва."]},{"h":"Пісня 8","ps":["Ірмос: Мусикі́йським орга́ном согласующим і лю́дем безчи́сленним, покланяющимся о́бразу в Деї́рі, три о́троци не повину́вшеся, Го́спода воспіва́ху і славословля́ху во вся ві́ки.","Приспів: Ди́вен Бог во святи́х Свої́х, Бог Ізра́їлев (поклін).","Землени́я по́двиги проше́дше, небе́сния прия́ша вінці́ му́ченици і́стиннії, вопію́ще Ті непреста́нно: Го́спода по́йте і превозносі́те Єго́ во вся ві́ки.","Поко́й, Го́споди, душі́ усо́пших раб Твої́х.","Соше́д в ров преіспо́днійший, і́же во гробі́х живу́щия воскреси́л єси́ живонача́льною дла́нію і по́дал єси́ рабо́м Твої́м, ві́рою пре́жде усо́пшим поко́й, Ще́дре.","Слава: Я́ко істо́чник жи́зні присносу́щния, я́ко сла́дости сий пото́к, раби́ Твоя́, благоче́стно к Тебі́ преста́вленния сподо́би пі́ти і славосло́вити Тя во вся ві́ки.","І нині: Марі́є Ді́во Богоро́дице, я́же Бо́га Спа́са челові́ком ро́ждшая тіле́сно, спаса́й ві́рою пою́щия Твоє́ Рождество́, і превозносящия во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Устраши́ся всяк слух неізрече́нна Бо́жия снизхо́жденія, я́ко Ви́шній во́лею сни́де да́же і до пло́ті, от Діви́чеськаго чре́ва бив Челові́к. Ті́мже Пречи́стую Богоро́дицю, ві́рнії, велича́єм.","Приспів: Ди́вен Бог во святи́х Свої́х, Бог Ізра́їлев (поклін).","Іму́ще, му́ченици Христо́ви, непобіди́мую крі́пость, і неодолі́ємую, уничижи́сте мучи́телей безбо́жноє велі́ніє, і Ца́рствія Небе́снаго я́ві сподо́бистеся, просвіща́ємі Тро́їчними заря́ми, достохва́льнії.","Поко́й, Го́споди, душі́ усо́пших раб Твої́х.","Разруши́ся ад го́ркий, разруши́вшу Ті єго́, Человіколю́бче, і воскреси́вшу я́же от ві́ка та́мо спящия; но і ни́ні, я́ко благ, преше́дшия к Тебі́, Благоутро́бне, невече́рняго сві́та Твоєго́ сподо́би.","Слава: Весь єси́, Спа́се, сла́дость, весь єси́ жела́ніє і любо́во воі́стину ненаси́тная, весь єси́ добро́та несказа́нная, преста́вльшіяся у́бо к Тебі́, Твоєя́ красоти́ наслажда́тися благоволи́ і Боже́ственния добро́ти Твоєя́ сподо́би.","І нині: Спаси́ м'я, Ма́ти Бо́жия, ро́ждшая Христа́ Спа́са моєго́, Бо́га і Челові́ка, сугу́ба єстество́м, не іпоста́сію: єдиноро́дна у́бо от Отця́, із Тебе́ же перворо́дна всея́ тва́рі; Єго́же в сугу́бом єстестві́ велича́єм.","Досто́йно єсть я́ко воі́стину блажи́ти Тя, Богоро́дицю, присноблаже́нную і пренепоро́чную і Ма́тер Бо́га на́шего. Честні́йшую Херуви́м і сла́внійшую без сравне́нія Серафи́м, без істлі́нія Бо́га Сло́ва ро́ждшую, су́щую Богоро́дицю, Тя велича́єм (поклін).","Святи́й Бо́же, Святи́й крі́пкий, Святи́й безсме́ртний, поми́луй нас. (тричі)","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","Пресвята́я Тро́йце, поми́луй нас; Го́споди, очи́сти гріхи́ на́ша; Влади́ко, прости́ беззако́нія на́ша; Святи́й, посіти́ і ісціли́ не́мощі на́ша, і́мене Твоєго́ ра́ди.","Го́споди, поми́луй. (тричі)","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","О́тче наш, І́же єси́ на небесі́х, да святи́ться і́м'я Твоє́, да при́йдеть Ца́рствіє Твоє́, да бу́деть во́ля Твоя́, я́ко на небесі́ і на землі́. Хліб наш насу́щний даждь нам днесь; і оста́ви нам до́лги на́ша, я́коже і ми оставля́єм должнико́м на́шим; і не введи́ нас во іскуше́ніє, но ізба́ви нас от лука́ваго."]},{"h":"Тропарі, глас 4","ps":["Со ду́хи пра́ведних сконча́вшихся ду́ші раб Твої́х, Спа́се, упоко́й, сохраня́я їх во блаже́нній жи́зні, я́же у Тебе́, Человіколю́бче.","В поко́їщі Твоє́м, Го́споди, іді́же всі святі́ї Твої́ упокоєва́ються, упоко́й ду́ші раб Твої́х, я́ко Єди́н єси́ Человіколю́бець.","Слава: Ти єси́ Бог, соше́дий во ад і у́зи окова́нних разріши́вий, Сам і ду́ші раб Твої́х упоко́й.","І нині: Єди́на чи́стая і непоро́чная Ді́во, Бо́га без сі́мене ро́ждшая, моли́ спасти́ся душа́м їх.","Го́споди, поми́луй. (40 разів)"]},{"h":"Молитва","ps":["Пом'яни́, Го́споди Бо́же наш, во ві́рі і наде́жді живота́ ві́чнаго преста́вльшагося раба́ Твоєго́ (або: преставльшуюся рабу Твою) (ім’я), і я́ко Благ і Человіколю́бець, отпуща́яй гріхи́ і потребля́яй непра́вди, осла́би, оста́ви і прости́ вся во́льная єго́ (єя) согріше́нія і нево́льная, ізба́ви єго́ (ю) ві́чния му́ки і огня́ геє́нськаго, і да́руй єму́ (ей) прича́стіє і наслажде́ніє ві́чних Твої́х благ, угото́ванних лю́б'ящим Тя: а́ще бо і согріши́, но не отступи́ от Тебе́, і несумні́нно во Отця́ і Си́на і Свята́го Ду́ха, Бо́га Тя, в Тро́йці сла́вимаго, ві́рова: і Єди́ницю в Тро́йці і Тро́йцю в Єди́нстві правосла́вно да́же до послі́дняго своєго́ іздиха́нія іспові́да. Ті́мже ми́лостив тому́ (той) бу́ди, і ві́ру, я́же в Тя, вмі́сто діл вміни́, і со святи́ми Твої́ми, я́ко Щедр, упоко́й: ність бо челові́ка, і́же поживе́ть і не согріши́ть. Но Ти єди́н єси́ кромі́ вся́каго гріха́ і пра́вда Твоя́ пра́вда во ві́ки, і Ти єди́н Бог ми́лости і щедро́т і человіколю́бія, і Тебі́ сла́ву возсила́єм, Отцю́ і Си́ну і Свято́му Ду́ху, ни́ні і при́сно і во ві́ки віко́в, амі́нь."]},{"h":"Або","ps":["Пом'яни́, Го́споди Бо́же наш, во ві́рі і наде́жді живота́ ві́чнаго усо́пших раб Твої́х (імена), і я́ко благ і Человіколю́бець, отпуща́яй гріхи́, і потребля́яй непра́вди, осла́би, оста́ви, і прости́ вся во́льная їх согріше́нія і нево́льная, возставля́я їх во свято́є второ́є прише́ствіє Твоє́ в прича́стіє ві́чних Твої́х благ, ї́хже ра́ди в Тя Єди́наго ві́роваша, і́стиннаго Бо́га і Человіколю́бця; я́ко Ти єси́ воскресе́ніє і живо́т, і поко́й рабо́м Твої́м (імена), Христе́ Бо́же наш, і Те́бі сла́ву возсила́єм, со безнача́льним Твої́м Отце́м, і с Пресвяти́м Ду́хом, ни́ні і при́сно і во ві́ки віко́в, амі́нь.","Честні́йшую Херуви́м і сла́внійшую без сравне́нія Серафи́м, без істлі́нія Бо́га Сло́ва ро́ждшую, су́щую Богоро́дицю, Тя велича́єм.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху, і ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь.","Го́споди, поми́луй. (тричі) Го́споди, благослови́.","Го́споди Ісу́се Христе́, Си́не Бо́жий, моли́твами Пречи́стия Твоє́й Ма́тере, преподо́бних і богоно́сних оте́ць на́ших і всіх святи́х поми́луй і упоко́й ду́ші раб Твої́х (імена) і всіх правосла́вних христия́н в безконе́чния ві́ки, я́ко благ і человіколю́бець, амі́нь.","Рабо́м Бо́жиїм преставльшимся, отце́м і бра́тіям на́шим і всім правосла́вним христия́ном, о ни́хже і помина́ніє твори́м, ві́чная па́м'ять. (тричі)","Читаємо тричі тропар з поклонами: Поко́й, Го́споди, ду́ші усо́пших раб Твої́х (поклін), і єли́ко в житії́ сем я́ко челові́ци согріши́ша, Ти же, я́ко Человіколю́бець Бог, прости́ їх і поми́луй (поклін), ві́чния муки́ ізба́ви (поклін), Небе́сному Ца́рствію прича́стники учини́ (поклін), і душа́м на́шим поле́зная сотвори́ (поклін)."]}],"notes":[]},{"u":"Канон Воскресний","e":"Canon of the Resurrection","secs":[{"h":"Глас 6. Пісня 1","ps":["Ірмос: Я́ко по су́ху, пішеше́ствовав Ізра́їль / по бе́здні стопа́ми, / гони́теля фарао́на ви́дя потопля́єма, / Бо́гу побі́дную піснь / пої́м, вопія́ше.","Приспів: Сла́ва, Го́споди, свято́му Воскресе́нію Твоєму́.","Распросте́ртима дла́ньма на кресті́, / оте́чеськаго іспо́лнил єси́ благоволе́нія, благи́й Ісу́се, вся́чеськая. / ті́мже побі́дную піснь Тебі́ всі пої́м.","Стра́хом к Тебі́, я́ко раби́ня, смерть / повелі́на приступи́ Влади́ці живота́, / то́ю подаю́щему нам безконе́чний живо́т і воскресе́ніє.","Богородичен: Своєго́ приє́мши Соді́теля, я́ко Сам восхоті́, / от безсі́меннаго Твоєго́ чре́ва, па́че ума́ воплоща́єма, Чи́стая, / тва́рей воі́стину яви́лася єси́, Влади́чиця."]},{"h":"Пісня 3","ps":["Ірмос: Ність свят, / я́коже Ти, Го́споди Бо́же мой, / вознеси́й рог ві́рних Твої́х, Бла́же, / і утверди́вий нас на ка́мені / іспові́данія Твоєго́.","Приспів: Сла́ва, Го́споди, свято́му Воскресе́нію Твоєму́.","Бо́га распина́єма пло́тію зря́щи твар, растаява́шеся стра́хом: / но содержи́тельною дла́нію нас ра́ди Расп'я́таго, крі́пко держи́ма бі.","Сме́ртію смерть разоре́на лежи́ть окая́нная без диха́нія: / Живота́ бо не терп'я́щи боже́ственнаго прираже́нія, / умерщвля́ється крі́пкий, і да́рується всім воскресе́ніє.","Богородичен: Боже́ственнаго рождества́ Твоєго́, Чи́стая, / вся́кий єстества́ чин превосхо́дить чу́до: / Бо́га бо преєсте́ственні зачала́ єси́ во чре́ві, / і ро́ждши пребива́єши при́сно Ді́ва."]},{"h":"Пісня 4","ps":["Ірмос: Христо́с моя́ си́ла, / Бог і Госпо́дь, честна́я Це́рков / Боголі́пно поє́ть, взива́ющи, / от сми́сла чи́ста о Го́споді пра́зднующи.","Приспів: Сла́ва, Го́споди, свято́му Воскресе́нію Твоєму́.","Дре́во процвіло́ єсть, Христе́, і́стинния жи́зні: / крест бо водрузи́ся, / і напоє́н бив кро́вію і водо́ю от нетлі́ннаго Твоєго́ ребра́, / живо́т нам прозябе́.","Не ктому́ змій мні ло́жні обоже́ніє подлага́єть: / Христо́с бо богоді́латель челові́чеськаго єстества́, / ни́ні невозбра́нно стезю́ живота́ мні отве́рзе.","Богородичен: Я́ко воі́стину неізвіща́нна і непостижи́ма, / я́же Твоєго́ боголі́пнаго, Богоро́дице, суть рождества́, / су́щим на землі́ і на небесі́, Присноді́во, та́їнства."]},{"h":"Пісня 5","ps":["Ірмос: Бо́жиїм / сві́том Твої́м, Бла́же, / у́треннюющих Ті ду́ші любо́вію озари́, молю́ся, / Тя ві́діти, Сло́ве Бо́жий, / і́стиннаго Бо́га, / от мра́ка гріхо́внаго взива́юща.","Приспів: Сла́ва, Го́споди, свято́му Воскресе́нію Твоєму́.","Уступа́ють мні херуви́ми ни́ні, / і пла́менноє ору́жіє, Влади́ко, плещи́ мні дає́ть, / Тя ви́дівше, Сло́ве Бо́жий, і́стиннаго Бо́га, / разбо́йнику путь сотво́ршаго в рай.","Не ктому́ бою́ся, є́же в зе́млю, Влади́ко Христе́, возвраще́нія: / Ти бо от землі́ м'я возве́л єси́ забве́нна, / благоутро́бія ра́ди мно́гаго, / к висоті́ нетлі́нія воскресе́нієм Твої́м.","Богородичен: І́же Богоро́дицю Тя от душі́, Влади́чице ми́ра блага́я, / іспові́дающих спаси́: / Тебі́ бо предста́тельство непобори́моє і́мами, / і́стинную Богороди́тельницю."]},{"h":"Пісня 6","ps":["Ірмос: Жите́йськоє мо́ре, / воздвиза́ємоє зря напа́стей бу́рею, / к ти́хому приста́нищу Твоєму́ прите́к, вопію́ Ті: / возведи́ от тлі живо́т мой, / Многоми́лостиве.","Приспів: Сла́ва, Го́споди, свято́му Воскресе́нію Твоєму́.","Распина́єм, Влади́ко, гвоздьми́ у́бо, / кля́тву ю́же на нас потреби́л єси́: / копіє́м же пробода́єм в ребро́, / ада́мово рукописа́ніє растерза́в, мир свободи́л єси́.","Ада́м низведе́ся, ле́стію зап'я́т бив, ко а́дові про́пасти: / но і́же єстество́м Бог же і ми́лостив, / сшел єси́ на взиска́ніє, / і на ра́му поне́с, совоскреси́л єси́.","Богородичен: Пречи́стая Влади́чице, / ро́ждшая челові́ком ко́рмчію Го́спода, / страсте́й мої́х непостоя́нноє і лю́тоє утоли́ смуще́ніє, / і тишину́ пода́ждь се́рдцю моєму́."]},{"h":"Кондак, глас 6","ps":["Живонача́льною дла́нію / уме́ршія от мра́чних удо́лій, / Жизнода́вець воскреси́во всіх Христо́с Бог, / воскресе́ніє подаде́ челові́чеському ро́ду: / єсть бо всіх Спаси́тель, / Воскресе́ніє і Живо́т, і Бог всіх."]},{"h":"Ікос","ps":["Крест і погребе́ніє Твоє́, Жизнода́вче, воспіва́єм ві́рнії, і покланя́ємся, / я́ко ад связа́л єси́, Безсме́ртне, я́ко Бог всеси́льний: / і ме́ртвия совоскреси́л єси́, і врата́ сме́ртная сокруши́л єси́, / і держа́ву а́дову низложи́л єси́, я́ко Бог. / Ті́мже земноро́днії славосло́вим Тя любо́вію, воскре́сшаго, / і низложи́вшаго вра́жию держа́ву всепа́губную, / і всіх воскреси́вшаго в Тя ві́ровавших, / і мир ізба́вльшаго от стріл змії́них, / і от пре́лести вра́жия, я́ко Бог всіх."]},{"h":"Пісня 7","ps":["Ірмос: Росода́тельну у́бо пещ соді́ла А́нгел / преподо́бним отроко́м, / халде́ї же опаля́ющеє / велі́ніє Бо́жиє / мучи́теля увіща́ вопи́ти: / благослове́н єси́, Бо́же оте́ць на́ших.","Приспів: Сла́ва, Го́споди, свято́му Воскресе́нію Твоєму́.","Рида́ющеє во стра́сті Твоє́й со́лнце, во мрак облече́ся, / і во дні по всей, Влади́ко, землі́ світ поме́рче, вопія́: / благослове́н єси́ Бо́же оте́ць на́ших.","Облеко́шася Христе́ схожде́нієм Твої́м во світ преіспо́дняя, / пра́отець же весе́лія іспо́лнь, яви́ся ликовству́я, взигра́ся, вопія́: / благослове́н єси́, Бо́же оте́ць на́ших.","Богородичен: Тобо́ю, Ма́ти Ді́во, / світ возсія́ всей вселе́нній сві́тлий: / Зижди́теля бо Ти всіх родила́ єси́ Бо́га, / Єго́же проси́, Всечи́стая, / нам низпосла́ти ві́рним ве́лію ми́лость."]},{"h":"Пісня 8","ps":["Ірмос: Із пла́мене преподо́бним ро́су істочи́л єси́, / і пра́веднаго же́ртву водо́ю попали́л єси́: / вся бо твори́ши, Христе́, то́кмо є́же хоті́ти. / Тя превозно́сим во вся ві́ки.","Приспів: Сла́ва, Го́споди, свято́му Воскресе́нію Твоєму́.","Іуде́йськия дре́вле пророкоуби́йці лю́ди, / богоуби́йці за́висть ни́ні соді́ла, / Тебі́ на крест возне́сшия, Сло́ве Бо́жий: / Єго́же превозно́сим во вся ві́ки.","Небе́снаго кру́га не оста́вил єси́, / і во ад соше́д, всего́ совоздви́гл єси́ / лежа́щаго во гно́їщі, Христе́, челові́ка, / Тя превознося́ща во вся ві́ки.","Богородичен: От Сві́та Світода́вця Сло́ва зачала́ єси́, / і ро́ждши неізрече́нно Сего́, просла́вилася єси́: / Дух бо в Тя, Отрокови́це, Бо́жий всели́ся. / Ті́мже Тя поє́м во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Бо́га / челові́ком не возмо́жно ви́діти, / на Него́ же не смі́ють чи́ни А́нгельстії взира́ти; / Тобо́ю бо, Всечи́стая, яви́ся челові́ком / Сло́во воплоще́нно, / Єго́ же велича́юще, / с Небе́сними во́ї / Тя ублажа́єм.","Приспів: Сла́ва, Го́споди, свято́му Воскресе́нію Твоєму́.","Страсте́й неприча́стен Ти преби́л єси́, Сло́ве Бо́жий, / пло́тію приобщи́вся страсте́м: / но ріши́ши от страсте́й челові́ка, / страсте́м бив страсть, Спа́се наш: / єди́н бо єси́ безстра́стен, і всеси́лен.","Тлю сме́ртную приє́м, тлі́нія соблю́л єси́ ті́ло Твоє́ невку́сно, / Твоя́ же животворя́щая і боже́ственная, Влади́ко, душа́, во а́ді не оста́влена бисть: / но я́коже от сна воскре́с, нас совоздви́гл єси́.","Троїчен: Бо́га Отця́, Си́на собезнача́льна, / всі челові́ци устна́ми у́бо чи́стими сла́вим, / неізрече́нную же і пресла́вную Ду́ха Всесвята́го си́лу чтим: / єди́на бо єси́ всеси́льная Тро́йця неразлу́чная."]}],"notes":[]},{"u":"Келійний покаянний канон на Страсну седмицю єпископа Єремії Нижньогородського","e":"Cell canon of repentance for Holy Week by Bishop Jeremiah of Nizhny Novgorod","secs":[{"h":"Пісня 1","ps":["Ірмос: Спаси́телю Бо́гу, в мо́рі лю́ди немо́крими нога́ми наста́вльшему, і фарао́на со всево́їнством пото́пльшему, Тому́ Єди́ному пої́м, я́ко просла́вися.","Поми́луй м'я, Бо́же, поми́луй м'я! (Покло́н)","Душе́ моя́, душе́ моя́! Гряди́й Госпо́дь на во́льную страсть, на́шего ра́ди спасе́нія, рече́ возлю́бленним Свої́м ученико́м: се, восхо́дим во Ієрусали́м, і предає́ться Син Челові́чеський. Гряди́ і ти вслід Єго́, нося́щи ко Кресту́ Єго́ вся беззако́нія твоя́, і ка́ющися в них, взива́й:","Поми́луй м'я Бо́же, поми́луй м'я!","Душе́ моя́, душе́ моя́! Гряди́й Госпо́дь на во́льную за тя смерть, на путі́ во Ієрусали́м, во Вифа́нії, воскреси́ четверодне́внаго смердя́щаго Ла́заря. Припади́, о душе́, ко Го́споду і моли́, да воскреси́ть Он от сме́рти гріхо́вния і тя, вопію́щую с Дави́дом:","Поми́луй м'я Бо́же, поми́луй м'я!","Душе́ моя́, душе́ моя́! Глаго́леть Христо́с і тебі́, я́коже Ма́рфі і Марі́ї, сестра́м уме́ршаго Ла́заря: Аз єсьм Воскреше́ніє і Живо́т, ві́руяй в М'я, а́ще і у́мреть, оживе́ть. Ві́руй у́бо всемогу́щей си́лі Христа́ Спаси́теля, упова́й на безпредельную бла́гость Єго́ і с непоколеби́мою ві́рою взива́й:","Поми́луй м'я Бо́же, поми́луй м'я!","Душе́ моя́, душе́ моя́! О Ла́зарі уме́ршем і во гро́бі лежа́щем пла́каше Ма́рфа, пла́каше і́на сестра́ єго́ Марі́я, пла́каху єго́ дру́зі, пла́каше Сам Госпо́дь.","Ти ли не воспла́чеши о твоє́м Ла́заре, об умі́, во гро́бі страсте́й і чувственности погребенном? Ти ли до конця́ пребу́деши окамененна, не научи́вшися моли́тися Христу́ і взива́ти:","Поми́луй м'я Бо́же, поми́луй м'я!","Го́споди, реко́ста Ма́рфа і Марі́я Го́споду, а́ще би єси́ бил зді, не би у́мерл брат наш.","То́єжде сло́во і ми с тобо́ю, душе́ моя́, рцем Го́споду: не низве́рглся би в сінь сме́ртную ум наш, не ізнемогла би во́ля на́ша, не усну́ла би со́вість, не возобладали би се́рдцем стра́сті, а́ще би Ти, Го́споди, бил с на́ми, а́ще ми не удалили би́хом Тебі́ свої́ми гріхи́ і безстра́шієм, а́ще в нераскаянности своє́й не преста́ли би́хом взива́ти:","Поми́луй м'я Бо́же, поми́луй м'я!","Душе́ моя́, душе́ моя́! По глаго́лу Христа́ Бо́га: Ла́заре, гряди́ вон,— ізи́де уме́рий, об'я́зан рука́ма і нога́ма. О, а́ще би ді́йствієм і си́лою всемогущия благода́ті Христо́ви і ум, твой історглся от связующих Єго́ страстни́х помисло́в і сатани́нських об'язаній, даби́ нелі́ностно взива́л:","Поми́луй м'я Бо́же, поми́луй м'я!","Душе́ моя́, душе́ моя́! Воскре́сшему Ла́зарю повелі́ а́біє Госпо́дь іти́: разрішіте́ єго́, рече́ Жизнода́тель, і оста́віте іти́. Не бу́ди і ти, в Та́їнствах Креще́нія і покая́нія обновившися, недви́жима і бездейственна, но доброшествуй по путі́ спасе́нія, не престаю́щи приме́ром свої́м і други́я наставля́ющи взива́ти:","Поми́луй м'я, Бо́же, поми́луй м'я.","Слава: Ла́зарева болі́знь ність к сме́рті, віща́ше Госпо́дь ученико́м Свої́м, но к сла́ві Бо́жієй. І воі́стину: не єди́н то́кмо сам воскре́сший Ла́зар і сестри́ єго́ со апо́столи, но і тьми ві́рующих просла́виша і ни́ні сла́в'ять Христа́ Воскресителя, і Єго́ Єдиносу́щнаго Отця́, і Ду́ха Свята́го. О, даби́ к сла́ві Пресвяти́я Тро́йці послужили твоя́, душе́ моя́, не́мощі і твої́ сме́ртнії неду́зі, об ї́хже ісціле́нії мо́лиши ти, взива́ющи Отцю́, і Си́ну, і Свято́му Ду́ху:","Поми́луй м'я Бо́же, поми́луй м'я!","І нині: О Пресвята́я Ді́во Богоро́дице! О дру́же Христо́в Ла́заре, о други́ні Христа́ і Пресвяти́я Ма́тере Єго́ Ма́рфо і Марі́є!","Помолі́теся Христу́ Бо́гу, да отвали́ть ка́мень нечу́вствія от ду́ха моєго́ і да да́руєть єму́ живо́т і си́лу пойти́ і принести́ посильния плоди́ покая́нія, уми́льно взива́ющу: поми́луй м'я Бо́же, поми́луй м'я!"]},{"h":"Пісня 2","ps":["Ірмос: Ви́діте, ви́діте, я́ко Аз єсьм Бог, воплоти́вийся от Пресвяти́я Ді́ви і расп'я́тієм Свої́м на Кресті́ поми́ловати і спасти́ вас прише́дий.","Поми́луй м'я Бо́же, поми́луй м'я!","Гряди́й Христо́с на во́льную на́шего ра́ди спасе́нія смерть, во Ієрусали́м торжественне вни́ти благоволи́. Мно́зі ти́сящи наро́да, сріта́юще Єго́, взива́ху: Оса́нна! Благослове́н Гряди́й! Ти же, о душе́ моя́, помишля́ющи о согріше́ніїх твої́х і всего́ ми́ра, вопи́й с Дави́дом:","Поми́луй м'я Бо́же, поми́луй м'я!","Іуде́є, Го́спода с гори́ Єлео́нськия провожда́юще во град Ієрусали́м, і́же бисть уже́ кро́вію мно́гих проро́к обагре́н і кро́вію Самаго́ Богочелові́ка імі́ обагри́тися, ри́зи своя́ по путі́ постила́ху. Ти же, о душе́ моя́, воспом'янувши предрече́нноє проро́ки і Господом, повергнися до́лу, в стра́сі і тре́петі взива́ющи:","Поми́луй м'я Бо́же, поми́луй м'я!","Ве́ліє усе́рдіє, ве́лію честь Го́споду іуде́є оказаху, єгда́ вшествоваше во Ієрусали́м на жреб'я́ті о́сли. Мно́зі от них ві́тві от древ рі́заху, да цві́ти і ли́ствієм їх украсять мі́ста, по ни́мже ше́ствова Госпо́дь ко хра́му Ієрусали́мському. Ти же, о душе́ моя́, отсіци́ то́є жестокосе́рдіє і ти́я стра́сті, я́же возведо́ша Го́спода на Крест, і не преста́ни взива́ти:","Поми́луй м'я Бо́же, поми́луй м'я!","Во вероломнем і христоубийственнем гра́де вни́де Госпо́дь в це́рков Бо́жию, і ізгна́ із нея́ продающия і купующия, і трапе́зи торжнико́в ниспроверже. О, коли́коє мно́жество неподо́бних і недосто́йних помисло́в, чувствованій і жела́ній гнізди́ться в тебі́, душе́ моя́! Ізгони́ у́бо їх і взива́й:","Поми́луй м'я Бо́же, поми́луй м'я!","Храм Мой храм моли́тви нарече́ться, рече́ Госпо́дь, вразумля́я свяще́нников і старі́йшин іуде́йських, ви же сотвори́сте і мі́стом ку́пли і верте́пом разбо́йников. О, кольми́ пра́ведне уко́р сей все́ю си́лою мно́гажди па́даше і па́даєть і на нас с тобо́ю, о душе́ моя́! Возскорби о такові́м стра́стнім ізвращенії і взива́й:","Поми́луй м'я Бо́же, поми́луй м'я!","По ізгна́нії із хра́ма купу́ющих і продаю́щих, безпреп'ятственне возмого́ша приступи́ти ко Го́споду хромі́ї, сліпі́ї і про́чії боля́щії. Приступи́ша они́, і а́біє получи́ти ісціле́ніє сподо́бишася. Приступи́ ко Го́споду і ти, душе́ моя́, душе́ слепотствующая, хромлющая і разсла́бленная, приступи́ і воззови́ к Нему́:","Поми́луй м'я Бо́же, поми́луй м'я!","Всим, до єди́наго, видящим сла́ву вше́ствія Твоєго́, Го́споди, во град і чуде́с, Тобо́ю соверше́нних, досто́яше повергнутися к стопа́м Твої́м і благогові́йні іспові́дати Тя Христо́м Бо́жиїм і обітова́нним Спаси́телем. Но сліпі́ї вожди́ народнії ожесточишася і негодова́ху на тіх, і́же оса́нна Тебі́ воспеваша. Храни́ся і блюди́ся, о душе́ моя́, от такови́я зло́би і ожесточе́нія, ча́сто віща́ющи: поми́луй м'я Бо́же, поми́луй м'я!","Слава: Чи́стая і невинная уста́ отроко́в іуде́йських возглаша́ху Ті на путі́ і в хра́мі, Христе́, оса́нна! Аз же, грі́шний, мої́ми нечи́стими усти́ ве́чер і у́тро взива́ю Тебі́ і Отцю́ Твоєму́, і Свято́му Ду́ху: Поми́луй м'я Бо́же, поми́луй м'я!","І нині: Во ве́чер днесь Госпо́дь, ви́шед із гра́да, оста́ви єго́. Мене́ же, о Христі́ Ісу́се, за малові́ріє моє́ і за мно́гая гріхи́ не оста́ви во ве́чер моєго́ житія́, бу́ди со мно́ю при сме́рти і по сме́рті, моли́твами Пресвяти́я Богоро́диці і свята́го А́нгела Храни́теля моєго́, да я́коже ни́ні, тогда́ умиле́нно взива́ю: Поми́луй м'я Бо́же, поми́луй м'я!"]},{"h":"Пісня 3","ps":["Ірмос: Си́лою Креста́ Твоєго́ Христе́, утверди́ моє́ помишле́ніє, во є́же пі́ти і сла́вити спаси́тельноє Твоє́ расп'я́тіє.","Поми́луй м'я Бо́же, поми́луй м'я!","О, блаже́нная ві́сі Вифанія! В ней бо жительствоваху святі́ї дру́зі Го́спода: Ла́зар, Ма́рфа і Марі́я, в ней мно́гажди витаху і упокоєвахуся Богочелові́к, Ма́тер Єго́ Пречи́стая і апо́столи. О́ная удосто́їся ви́діти велича́йшеє от Христо́вих чуде́с, воскреше́ніє Ла́заря. Та́мо благоволи́ Госпо́дь проводи́ти послі́днія нощі́ пред но́щію Гефсиманською. Душе́ моя́, душе́ моя́! Стоя́й при две́ріх се́рдця і толки́й, вни́деть Он і к тебі́ і водвори́ться у тебе́, я́коже во Вифа́нії, а́ще усли́шим глас Єго́, а́ще покаємся і усе́рдно на́чнем взива́ти:","Поми́луй м'я Бо́же, поми́луй м'я!","У́тру би́вшу, Госпо́дь, возвращался во Ієрусали́м, Влади́ка, дая́й пи́щу вся́кой пло́ті, взалка́. Сія́ а́лчба тіле́сная Го́спода, я́ко Челові́ка, да оживи́ть в па́м'яті твоє́й, душе́ моя́, ту́ю духо́вную Боже́ственную а́лчбу Христо́ву, є́юже ви́ну а́лчеть Он твоєго́ обраще́нія і сего́ покаяннаго гла́са:","Поми́луй м'я Бо́же, поми́луй м'я!","Не обрі́те Госпо́дь ні єди́наго плода́ на смоко́вниці, при путі́ стоявшей, і осуди́ ю на ві́чноє безпло́діє, рек: да ніколи́же от тебе́ бу́деть плода́ во ві́ки. Чесого́ ожида́ти тебі́, душе́ моя́, я́ко не сего́ стра́шнаго гла́са, а́ще не при́йдеши в чу́вство і не принесе́ши плодо́в покая́нія, взива́ющи:","Поми́луй м'я Бо́же, поми́луй м'я!","Імі́йте ві́ру Бо́жию, веща Госпо́дь Петру́, смоко́вниці, а́біє по глаго́лу Христо́ву ізсшей, див'ящемуся. Амі́нь, глаго́лю вам: вся, єли́ка а́ще моля́щеся про́сите, ві́руйте, я́ко при́ймете. Не унива́й у́бо, душе́ моя́, зря в себі́ ні́кия оста́нки плода́ о́наго дре́ва позна́нія добра́ і зла: єди́нім манове́нієм Го́спода ізшуть они́ і ізторгнуться, а́ще ві́ру Бо́жию стя́жем і не преста́нем взива́ти:","Поми́луй м'я Бо́же, поми́луй м'я!","Мно́гоє мно́жество слове́с ізреко́ша Го́споду во хра́мі кни́жници і фарисе́є: ко́єю вла́стію сія́ твори́ши, торжнико́в ізгоня́ющи? Досто́їть ли дань дая́ти ке́сарю? — і про́чая. Ти же, о душе́ моя́, нічто́же ми́слі, нічто́же глаго́ли, ра́зві сего́ Дави́дова словесе́:","Поми́луй м'я Бо́же, поми́луй м'я!","Челові́к ні́кий імі́ два си́на, рече́ Госпо́дь, от ни́хже єди́н пре́жде оказа́ отцю́ непослуша́ніє, но по́сліжде, раска́явся, і́де на повелі́нноє ді́ло. Други́й, обіща́вся іспо́лнити во́лю отця́, не іспо́лни ю. Сему́ вероломному си́ну послі́довала єси́, душе́ моя́, і́бо безстра́шні преступала єси́ обі́ти, при Креще́нії да́нния, і обра́щшися к покая́нію, лі́ностно мо́лишися і с нераді́нієм взива́єши:","Поми́луй м'я Бо́же, поми́луй м'я!","Душе́ моя́, душе́ моя́! І тебі́ вві́рен бисть вертогра́д, во є́же храни́ти і возделоватії, вертогра́д Богонасажде́нний і опло́том Єва́нгелія і благода́ті огражденний. Ти же, окая́нная, уподо́билася єси́ злим ді́лателем, і́же не то́кмо плодо́во Владике не возда́ша, но і де́рзостні Єго́ преогорчи́ша, ка́йся у́бо і пла́чущи взива́й:","Поми́луй м'я Бо́же, поми́луй м'я!","Слава: В Ца́рствіє Небе́сноє, в Ца́рствіє Сві́та і блаже́нства, призива́єть нас, грі́шних, Бог в Тріє́х Іпоста́сіх: Оте́ць, Син і Дух Святи́й. Ти же, душе́ моя́, подо́бно о́ним званим в при́тчі Госпо́дні, де́рзостні отріва́єши небе́сноє зва́ніє Пресвяти́я Тро́йці, вини́ ні́кия представля́ющи, не вступавши на путь, в Ца́рствіє Бо́жиє веду́щий, не каєшися і не взива́єши: поми́луй м'я Бо́же, поми́луй м'я!","І нині: Стра́шний глаго́л ізрече́ Домовлади́ка, узрі́в на трапе́зі Своє́й челові́ка, необолченна в одія́ніє прили́чно по безстрашію і презорству: возьмі́те єго́ і вве́рзіте во тьму кромі́шнюю. О, Пресвята́я Ді́во Богоро́дице! Да не усли́шу за мою́ наготу́ і безобра́зіє сего́ стра́шнаго суда́, даждь мі день і нощ ка́ятися і взива́ти: Поми́луй м'я Бо́же, поми́луй м'я!"]},{"h":"Пісня 4","ps":["Ірмос: Усли́шах слух си́ли Креста́ Твоєго́, я́ко рай отве́рзеся їм, і возопи́х: сла́ва расп'я́тію Твоєму́, Го́споди.","Поми́луй м'я Бо́же, поми́луй м'я!","Гряди́й Госпо́дь на во́льную всеспаси́тельную страсть і смерть, смиря́я іуде́єв, рече́: воздаді́те Бо́жия Бо́гові, ке́сарева ке́сареві. Ти же, душе́ моя́, не послужи́ла єси́ достодолжне ні Бо́гу, ні бли́жнему. Ка́йся у́бо і взива́й:","Поми́луй м'я Бо́же, поми́луй м'я!","Гряди́й Госпо́дь на во́льную на́шего ра́ди спасе́нія смерть, законнику вопроси́вшему: ка́я за́повідь бо́льши єсть в зако́ні, отвіщава́ше: возлю́биши Го́спода Бо́га твоєго́ всім се́рдцем твої́м і все́ю крі́постію твоє́ю, і всім помишле́нієм твої́м, сія́ єсть пе́рвая і бо́льшая за́повідь. Ти же, о душе́ моя́, не то́кмо все́ю полното́ю ми́слі і се́рдця, но ніже́ ча́стію їх не возлюби́ла єси́ і не лю́биши Го́спода Бо́га Созда́теля, Промисли́теля і Іскупи́теля твоєго́; воздохни́ о сем нечу́вствії і окамене́нії твоє́м, і воззови́:","Поми́луй м'я Бо́же, поми́луй м'я!","Втора́я, пе́рвой подо́бная, за́повідь єсть, по глаго́лу Го́спода: возлю́биши бли́жняго твоєго́, я́ко себе́. Ти же, душе́ моя́, на мі́сто чи́стій любве́ ко бли́жнему, самолюбствуєши, користолюбствуєши, похотствуєши, завиствуєши. О, усугу́би у́бо і утрой покая́нний твой вопль:","Поми́луй м'я Бо́же, поми́луй м'я!","Гряди́й Госпо́дь на во́льную страсть і смерть, повелі́ слу́шати і ти́я наста́вники, і́же глаго́лють, но не творя́ть; ти же, душе́ моя́, не послу́шала єси́ і не слушавши богодохнове́нних і духоно́сних учи́телей: проро́ков, апо́столов, отце́в і па́стирей Це́ркве богому́дрих. Ка́йся о сем і взива́й:","Поми́луй м'я Бо́же, поми́луй м'я!","Гряди́й Госпо́дь на во́льную страсть і смерть, гро́зно возгласи́: го́ре тім кни́жником і лицемі́ром, і́же очища́ють вні́шняя стекляниць і блю́да, внутр же суть по́лни хище́нія і непра́вди. Го́ре, го́ре тебі́, душе́ моя́, об очище́нії свої́х помишле́ній не радящей, язи́ком то́кмо, а не і се́рдцем ку́пно взивающей:","Поми́луй м'я Бо́же, поми́луй м'я!","Гряди́й Христо́с на во́льную страсть і смерть, возвісти́ і вообрази́ ученико́м Свої́м второ́є прише́ствіє Своє́, всеобщий Суд, кончи́ну ми́ра. Помишля́ющи о сих, ужасни́ся, душе́ моя́, бо́дрствуй, ка́йся, і взива́й:","Поми́луй м'я Бо́же, поми́луй м'я!","Юро́дивим, но не му́дрим ді́вам уподо́билася єси́ ти, душе́ моя́, і не іму́щи єле́я благи́х діл, лише́на бу́деши ца́рствія небе́снаго, а́ще не при́йдеши в чу́вство покая́нія і не воззове́ши во́плем крі́пким:","Поми́луй м'я Бо́же, поми́луй м'я!","Слава: Не поревнова́ла єси́ ти, душе́ моя́, рабу́ ві́рному і до́брому, до́брі умножившему вві́ренний єму́ от Го́спода тала́нт; но уподо́билася єси́ рабу́ ліни́вому, да́нний єму́ тала́нт в зе́млю сокри́вшему, і я́ко неключимая, вве́ржена бу́деши во тьму кромі́шнюю, а́ще не поспіши́ши оста́нок житія́ твоєго́ проводи́ти в труді́х і покая́нії, ви́ну взива́ющи: Поми́луй м'я Бо́же, поми́луй м'я!","І нині: О, Пресвята́я і Преблагослове́нная Присноді́во Марі́є! Да не усли́шу с ді́вами юро́дивими стра́шнаго словесе́: не вім вас,— даждь мі і усти́, і се́рдцем непреста́нно взива́ти: Поми́луй м'я Бо́же, поми́луй м'я!"]},{"h":"Пісня 5","ps":["Ірмос: Просвіще́ніє во тьмі лежа́щих, спасе́ніє отча́янних, Христе́ Спа́се мой, к Тебі́ У́треннюю, Царю́ ми́ра, просвіти́ м'я сія́нієм Твої́м, іно́го бо ра́зві Тебе́ Бо́га не зна́ю.","Го́споди, пре́жде да́же до конця́ не поги́бну, спаси́ м'я.","Гряди́й Госпо́дь на во́льную страсть і смерть, предизобразі, ка́ко при́йдеть на коне́ць віко́во в сла́ві Своє́й, і всі святі́ї А́нгели с Ним, ка́ко ся́деть на Престо́лі сла́ви Своєя́, ка́ко соберу́ться пред Ним всі наро́ди, ка́ко разлучи́ть всіх челові́ков, і пра́ведних поста́вить одесну́ю, а грі́шников ошу́юю. Усли́шавши, душе́ моя́, сія́ послі́дняя віща́нія Госпо́дня, ужасни́ся Суда́ сего́ і в покая́нії взива́й:","Го́споди, пре́жде да́же до конця́ не поги́бну, спаси́ м'я.","Взалка́хся, рече́ть Госпо́дь су́щим одесну́ю, і даєте́ Мі я́сти; ти же, о душе́ моя́, напитала ли єси́ Христа́ в ли́ці ме́ньших бра́тій? Ка́йся у́бо і вопи́й:","Го́споди, пре́жде да́же до конця́ не поги́бну, спаси́ м'я.","Возжада́хся, рече́ть Госпо́дь пра́ведним, призива́я їх в ца́рствіє Своє́, і напоі́сте М'я, стра́нен біх, і введо́сте М'я. Ти же, грі́шная душе́ моя́, ні ча́ші води́ студе́ния, ні приюта і упокоє́нія не предложила єси́ со Авраамовим усе́рдієм Го́споду, жа́ждущему і стра́нну в ли́ці ни́щих і убо́гих. Сокрушайся у́бо, болі́знуй і взива́й:","Го́споди, пре́жде да́же до конця́ не поги́бну, спаси́ м'я.","Наг біх, і оді́ясте М'я, бо́лен, і посіти́сте М'я, в темни́ці біх, і прийдо́сте ко Мні, рече́ть Госпо́дь наслі́дником ві́чнаго блаже́нства. Ти же, о душе́ моя́, ні єди́наго от сих благи́х діл сотвори́ла єси́ ме́ньшей бра́тії Христо́вой. Чесого́ за твоє́ жестокосе́рдіє ожида́ти тебі́, я́ко не геє́нни, а́ще не припадеши к Человіколю́бцю со слеза́ми і моле́нієм:","Го́споди, пре́жде да́же до конця́ не поги́бну, спаси́ м'я.","Гряди́й Госпо́дь на во́льную страсть і смерть, благоволи́ вни́ти в дом Си́мона, от прока́зи ісцеленнаго, і вечеря́ти у него́ со святи́ми ученики́ Свої́ми і со Пресвято́й Ма́терію Своє́ю. Жена́ же ні́кая та́мо, прия́в сосу́д ми́ра многоці́ннаго, возлива́ше о́ноє на главу́ Го́спода, ку́пно с ми́ром сле́зи любве́ і благодарности к Нему́ ізлива́ющи. І ти, грі́шная душе́ моя́, пролива́ющи сле́зи покая́нія і і́ми но́зі Го́спода ороша́ющи, взива́й:","Го́споди, пре́жде да́же до конця́ не поги́бну, спаси́ м'я.","Гряди́й Госпо́дь на во́льную страсть прибли́жися ко Ієрусали́му, і воззрі́в нань, пла́кася о нем, пла́кася об ожесточеннем осліпле́нії єго́ і о предстоящем бі́дствії єго́. Пла́чі і ти, душе́ моя́, помишля́ющи зла́я діла́ твоя́ і стра́шноє наказа́ніє за ня, пла́чі, взива́ющи:","Го́споди, пре́жде да́же до конця́ не поги́бну, спаси́ м'я.","Душе́ моя́, душе́ моя́, сли́шала єси́ соболезнующеє, но і стра́шноє послі́днєє сло́во Го́спода ко Ієрусали́му і всему́ наро́ду іуде́йському: Ієрусали́ме, Ієрусали́ме! Коль кра́ти восхоті́х собра́ти ча́да твоя́, я́коже ко́кош собира́єть птенці́ своя́ под крилі́, і не восхоті́сте. Се оставля́ється дом ваш пуст! Устраши́ся, убо́йся, да не оста́вить тя благода́ть Бо́жия за противле́ніє твоє́, і во́плем ве́ліїм воззови́:","Го́споди, пре́жде да́же до конця́ не поги́бну, спаси́ м'я!","Слава: Вся си́ли твоя́, о душе́ моя́, да при́йдуть і покло́няться Бо́гу Отцю́, Бо́гу Си́ну і Бо́гу Ду́ху Свято́му, і да воззову́ть: Тро́йце Свята́я, Єдиносу́щная, Єдинодержавная! Пре́жде да́же до конця́ не поги́бну, спаси́ м'я.","І нині: Гряде́ть, гряде́ть Воплоти́вийся от Тебе́, Пресвята́я Ді́во, Єдиноро́дний Син Бо́жий во́лею пострада́ти і расп'я́тися на Кресті́, да спасе́ть м'я вопію́ща: Го́споди, пре́жде да́же до конця́ не поги́бну, спаси́ м'я!"]},{"h":"Пісня 6","ps":["Ірмос: Моли́тву пролію́ ко Го́споду і Тому́ возвіщу́ печа́лі моя́, я́ко зол душа́ моя́ іспо́лнися, і живо́т мой, а́ду прибли́жися, і молю́ся, я́ко Іо́на: от тлі, Бо́же, возведи́ м'я.","Поми́луй м'я Бо́же, поми́луй м'я!","Сія́ нощ, в ню́же Христо́с наш пре́дан бисть от злонра́внаго ученика́ Своєго́ і бисть істязу́єм, біє́м, пору́ган, су́дим і осужде́н, от віко́в єсть предопреділе́нная, вели́кая і стра́шная нощ, ю́же сотвори́ Госпо́дь, да не во сні і дреманії прово́дим ю, душе́ моя́, но во бді́нії, во умиле́нії і в сле́зном взиванії:","Поми́луй м'я Бо́же, поми́луй м'я!","Душе́ моя́, душе́ моя́! Прини́кни в Сіонськую го́рницю і виждь, ка́ко вопло́щшеєся Сло́во, Богочелові́к, пред Та́йною Вечерію преклоня́ється ниць і умива́єть но́зі ученико́м, да сокруши́ть горди́ню твою́ і смире́нію тя научи́ть. Ти же не уразумі́ла єси́ сего́, не послі́довала єси́ примі́ру Го́спода твоєго́; пока́йся у́бо і взива́й:","Поми́луй м'я Бо́же, поми́луй м'я!","Душе́ моя́, душе́ моя́! Петру́, і́же весь бі чист, предлежаше лише́нним би́ти ча́сти со Христо́м, а́ще не умиються но́зі єго́ от Го́спода. Ка́ко у́бо возмо́жеши ти наслі́довати ца́рствіє небе́сноє, а́ще благода́ть Ду́ха Свя́та не очи́стить се́рдце твоє́ і помишле́нія нечи́стия, скве́рния, слеза́ми покая́нія неомовенния, і а́ще не воззове́ши ко Очисти́телю:","Поми́луй м'я Бо́же, поми́луй м'я!","Святі́ї апо́столи Пе́тре, Іоа́нне, Іа́кове, Андре́є, і всі святі́ї сла́внії єдинона́десяте апо́столи! Лобиза́ю ва́ша но́ги, омития пречи́стима рука́ма Госпо́днима, лобиза́ю ва́ша руки́, приявшия от Го́спода на Та́йній Ве́чері под ви́дом хлі́ба Ті́ло Єго́ і под ви́дом вина́ са́мую Кров Єго́. Молю́ ви, научі́те м'я прийма́ти сіє́ чу́дноє Бра́шно і Питіє́ со стра́хом і любо́вію, і с покая́нним моле́нієм:","Поми́луй м'я Бо́же, поми́луй м'я!","О, блаже́нни і преблаженни ушеса́ ва́ша, сли́шавшая вещавшаго вам Го́спода: приймі́те, яді́те, сіє́ єсть Ті́ло Моє́, є́же за ви ломи́моє во оставле́ніє гріхо́в; пи́йте от нея́ всі, сія́ єсть Кров Моя́, я́же за ви і за мно́гія ізлива́ємая во оставле́ніє гріхо́в! Ва́шими моли́твами, святі́ї апо́столи, да причтуся к тьмочисленному мно́жеству спаси́тельно і животворно приє́млющих Ті́ло і Кров Христо́ву; да причтуся к ним і аз, вопію́щий і взива́ющий:","Поми́луй м'я Бо́же, поми́луй м'я!","Гряди́й Госпо́дь на во́льную страсть ве́лію любо́в к вам, святі́ї апо́столи, і ко всім Свої́м, су́щим в ми́рі, показа́ і, уми́в но́ги ва́ша і оте́р їх ле́нтієм, неізрече́нно вя́щшую і бо́льшую любо́в і благода́ть Свою́ яви́, преподав в пи́щу і в питіє́ Ті́ло і Кров Свою́. О, а́ще би ти, душе́ моя́, уразумі́ла висоту́, глубину́, широту́ і бесконечность сея́ любве́ Христо́ви, а́ще би благонаде́жно і со дерзнове́нієм возмогла́ взива́ти:","Поми́луй м'я Бо́же, поми́луй м'я!","По Та́йній Ве́чері рече́ Госпо́дь Си́мону Петру́: Си́моне, Си́моне! Се сатана́ про́сить, даби́ сі́ял вас, я́ко пшени́цю, Аз же моли́хся о тебі́. Душе́ моя́, душе́ моя́! А́ще Петру́ угрожаше такови́й страх, не па́че ли тебі́? Моли́ся у́бо, да не оскуді́єть ві́ра твоя́ ніколи́же, найпа́че же при ісхо́ді твоє́м із ми́ра сего́; моли́ся ко Христу́ Бо́гу і взива́й:","Поми́луй м'я Бо́же, поми́луй м'я!","Слава: Ко Отцю́ Моєму́ гряду́, глаго́леть Госпо́дь, утіша́я ученики́ Своя́ пред ісхо́дом із Сіо́нськия го́рници в Гефсима́нію і по́сліжде на Голго́фу. І Аз умолю́ Отця́, і іна́го Уті́шителя дасть вам, Ду́ха Свята́го, Ду́ха І́стини. Ко ходатайственному моле́нію Си́на Бо́жия, совокупи́ і ти, душе́ моя́, покаянную моли́тву свою́ і взива́й к Нему́ і Єго́ Отцю́, і Ду́ху Свято́му: Поми́луй м'я Бо́же, поми́луй м'я!","І нині: Боля́щую ду́шу мою́ ісціли́, Ро́ждшая всіх Взе́млющаго неду́ги, і научи́ м'я благоприя́тні на вся́коє вре́м'я і на вся́кий час, па́че же в час сме́ртний взива́ти: Поми́луй м'я Бо́же, поми́луй м'я!"]},{"h":"Пісня 7","ps":["Ірмос: Согріши́хом, беззако́нновахом, непра́вдовахом пред Тобо́ю; ніже́ соблюдо́хом, ніже́ сотвори́хом, я́коже запові́дал єси́ нам, но не преда́ждь нас до конця́, отце́в Бо́же.","Поми́луй м'я Бо́же, поми́луй м'я!","Гряди́й Госпо́дь по Та́йній Ве́чері в Гефсима́нію, глаго́ла ученико́м Свої́м: Аз єсьм Лоза́ і́стинная, і Оте́ць Мой ді́латель єсть, вся́ку ро́згу о Мні не творя́щую плода́, Он отсіка́єть. Ти, о душе́ моя́, ні в ю́ності, ні в лі́та му́жеська, ніже́ во ста́рчестві не принесла́ єси́ плода́ уго́днаго Отцю́ Небе́сному. Страши́ся у́бо, да не отсі́чена бу́деши от живоно́сния Лози́ Христа́ і взива́й:","Поми́луй м'я Бо́же, поми́луй м'я!","На путі́ Своє́м от Сіо́на в Гефсима́нію віща́ше Христо́с: а́ще кто во Мні не пребу́деть, ізвергнеться вон, я́коже непло́дная вітв, і і́зсхнеть, і во огнь ввергнеться. Ти, о душе́ моя́, а́ще і сочета́лася єси́ со Христо́м во святі́м Креще́нії, но не пребила́ єси́ во соу́зе с Ним і вероломне преступи́ла єси́ обі́ти твоя́. Чесого́ же ожида́ти тебі́, я́ко не ізверже́нія вон із черто́га небе́снаго, а́ще, ка́ющися і пла́чущи о вероломстві твоє́м, не уми́лостивиши Го́спода сле́зним во́плем:","Поми́луй м'я Бо́же, поми́луй м'я!","Дух Святи́й, Єго́же обіща́л єсть Госпо́дь посла́ти от Отця́ возлю́бленним ученико́м Свої́м, ви́ну пребу́деть Уті́шителем і миродателем, неверующим же обличи́тель яви́ться. І, прише́д, Он, я́коже рече́ Госпо́дь, гряди́й на страда́ніє, обличи́ть мир о грісі́ і о пра́вді, і о суді́. Недосто́йная утіше́нія Ду́ха Уті́шителя, грі́шная душе́ моя́, прими́ смире́нно Єго́ обличительноє вразумле́ніє і не преста́ни взива́ти:","Поми́луй м'я Бо́же, поми́луй м'я!","Прини́кни, о душе́ моя́, і виждь, я́ко Христо́с Госпо́дь, ко Гефсима́нії прибли́жився, приклоня́єть колі́ни Своя́, возво́дить о́чі Своя́ на не́бо, моля́щеся Отцю́ Своєму́ о Себі́ Самі́м: О́тче! При́йде час страда́ній Мої́х за спасе́ніє ми́ра. Мо́литься об апо́століх: О́тче Святи́й! Соблюди́ їх во і́м'я Твоє́, да бу́дуть єди́но, я́коже і Ми. Мо́литься о всіх ві́рующих: Не о сих же молю́ то́кмо, но і о ві́рующих словесе́ їх ра́ди в М'я. Да і ти, душе́ моя́, о́бщниця бу́деши си́ли і плодо́в сей вели́кия Первосвященничеськия моли́тви Христо́ви, ві́руй в Него́, іспові́дуй Єго́, ка́йся в согріше́ніїх свої́х і взива́й:","Поми́луй м'я Бо́же, поми́луй м'я!","Приско́рбна єсть душе́ моя́ да́же, до сме́рти, глаго́ла Госпо́дь в саду́ Гефсиманстем. О чесо́м то́кмо скорби́ть і печа́луєть Всеблаже́нний, Вседовольний, Всесоверше́нний? Скорби́ть, я́ко ми, неблагодарная твар, вся за́повіді Бо́жії преступи́хом, я́ко правосу́діє Єго́ оскорби́хом і не ка́ємся, не чу́вствуєм гні́ва Бо́жия і не взива́єм:","Поми́луй м'я Бо́же, поми́луй м'я!","Син Бо́жий, Богочелові́к, в саду́ Гефсиманстем скорби́ть, тоскуєть, па́даєть ниць, толи́ко крі́пці мо́литься, я́ко моля́щуся Єму́, бі пот Єго́, я́ко ка́плі кро́ве, ка́плющия на зе́млю. Ми же, о душе́ моя́, в нечу́вствії єсьми́, дремлем, спим і не взива́єм:","Поми́луй м'я Бо́же, поми́луй м'я!","Что спі́те, рече́ Госпо́дь Петру́ і двум синово́м Зеведеовим, восставше молі́теся, да не вни́дете в напа́сть. Восстани, воспряни́ і ти, душе́ моя́, моли́ся і взива́й:","Поми́луй м'я Бо́же, поми́луй м'я!","Єгда́ Христо́с, Хода́тай наш, в саду́ Гефсиманстем скорбе ско́рбію смертельною, бі моля́ся до по́та кроваваго і предая́ всего́ Себе́ во во́лю Отця́ Небе́снаго, взива́я: О́тче, а́ще во́лиши мимонести́ от Мене́ ча́шу сію́, оба́че не Моя́ во́ля, но Твоя́ да бу́деть; тогда́ яви́ся к Нему́ А́нгел Госпо́день і укріпля́ше Всеси́льнаго. По́слеться А́нгел і ко вся́цій душі́, предающей себі́ во во́лю Бо́жию, кающейся і крі́пці вопіющей:","Поми́луй м'я Бо́же, поми́луй м'я!","Слава: В час, єгда́ сла́дці бесі́дова Госпо́дь со ученики́ на путі́ в Гефсима́нію, єгда́ моли́ся Он пре́жде да́же не вни́ти в сад і в самі́м саду́, в час сей несчастнейший от архієре́й Кая́фа совіща́ с несчастнейшим от всіх земноро́дних Іу́дою, ка́ко удо́біє я́ти Го́спода, і вдая́ше буйствующую толпу стражником со ору́жії, і ідо́ша ті́ї та́йними і глухи́ми сто́гни Свята́го Гра́да, да не у́зрять їх наро́ди Ієрусалимстії. А́нгели же і Арха́нгели ужаса́хуся і трепета́ху, ви́дяще сіє́ лука́воє богоубийственноє ше́ствіє. Ми же, о душе́ моя́, в сокруше́нії се́рдця не преста́нем взива́ти: Поми́луй м'я Бо́же, поми́луй м'я!","І нині: О, уві́діте і уразумі́йте сію́ стра́шную та́йну собо́рища, Іу́дою предводимаго, опа́сні сокриваємую от вас і от всего́ наро́да; разумі́йте ю святи́я жени́: Марі́є Магдали́но, Саломіє і други́я, і Пречи́стая Ді́ва Ма́тер Го́спода, і взивайте со мно́ю вку́пі: Поми́луй м'я Бо́же, поми́луй м'я!"]},{"h":"Пісня 8","ps":["Ірмос: Ужасни́ся боя́йся не́бо, і да подви́жаться основа́нія землі́: се бо в мертвеці́х вміня́ється во ви́шніх Живи́й і во гроб мал странноприє́млеться. Єго́же стра́сті пом'яні́те, погребе́ніє воспо́йте і превозносі́те Єго́ во вся ві́ки.","Поми́луй м'я Бо́же, поми́луй м'я!","Вопроси́ ні́когда Госпо́дь проро́ка Ієремі́ю: что ви́диши? Вопрошу́ і аз тя, грі́шная душе́ моя́, что ти ви́диши, на лице́ Го́спода взира́ющи і в нощ сію́ Єму́ послі́дующи? Ви́жду Го́спода моєго́ Ісу́са Христа́ в саду́ Гефсиманстем ятаго, свя́заннаго, чрез пото́ко Ке́дрський ведомаго наглими, слуга́ми Каяфовими; ви́жду Єго́ єди́ним от учени́к пре́даннаго, всі́ми про́чими оста́вленнаго, ужаса́юся і взива́ю:","Поми́луй м'я Бо́же, поми́луй м'я!","Ви́жду Го́спода моєго́, Єдиноро́днаго Си́на Бо́жия Ісу́са Христа́, ко А́нні, те́стю Каяфину приведеннаго, та́мо об уче́нії Єго́ істязуємаго, в лани́ту заушаємаго. Ви́жду сія́ і ужаса́юся, помишля́я, я́ко гріси́ на́ші вино́ю толи́каго унічиже́нія Христо́ва, і вопію́:","Поми́луй м'я Бо́же, поми́луй м'я!","Ви́жду Го́спода моєго́ свя́заннаго, окровавленнаго і от А́нни ко Кая́фі первосвященнику ведомаго, сли́шу зді мно́гая ло́жная на Него́ свиді́тельства і наві́ти; ви́жду, ка́ко Он, я́ко а́гнець безгла́сний, не отверза́єть уст Свої́х во є́же защити́ти Себі́, ви́жду сія́ і, окаявая свою́ нетерпеливость і малоду́шіє, взива́ю:","Поми́луй м'я Бо́же, поми́луй м'я!","Ви́жду, ка́ко Госпо́дь мой Всесвяти́й, Ісу́с Христо́с от Кая́фи первосвяще́нника і от несми́сленнаго собо́рища іуде́йськаго обвинен, ка́ко оглаше́н богохульником і законопреступником; ка́ко осужде́н на смерть, ка́ко, мно́гі поруга́нія і біє́нія претерпі́в, вве́ржен в темни́цю до у́трія; ви́жду сія́ і ужаса́юся, помина́я, я́ко за мої́ гріхи́ стра́ждеть Госпо́дь, і взива́ю:","Поми́луй м'я Бо́же, поми́луй м'я!","Ви́жду, ка́ко а́біє нау́тріє Госпо́дь, свя́занний і стрего́мий, із темни́ці ізведе́н, ка́ко представлен Кая́фі послі́дняго допроса ра́ди во о́бщем всіх суді́й іуде́йських собра́нії, і ка́ко, тве́рдо я́сні Го́споду отвіща́вшу, я́ко єсть Мессія, всі єдиногласне ізреко́ша пови́нен єсть сме́рті. Ви́жду сія́ і, ві́дая, я́ко мої́х ра́ди беззако́ній Оте́ць пре́дал єсть Си́на Своєго́ на смерть, сле́зно взива́ю:","Поми́луй м'я Бо́же, поми́луй м'я!","Ви́жду, ка́ко мно́гая стра́жа, с самими судія́ми іуде́йськими, повлекоша Го́спода, во дворі́ Кая́фи ізмученнаго, к Понті́йському Пила́ту, да преда́сть Єго́ на кре́стную смерть; ка́ко власти́тель сей, а́ще і мно́зі би́ша обвинительнії во́пли, ні єди́ния обрі́те вини́ в Небе́снім Осужденнике, і ка́ко непреклонне іуде́йськия нача́льниці, я́ко ізверги, жажда́ху ви́діти Го́спода на Кресті́. Ви́жду сія́ і ужаса́яся о толи́цій зло́бі і осліпле́нії се́рдця челові́чеськаго, с пла́чем вопію́:","Поми́луй м'я Бо́же, поми́луй м'я!","Ви́жду, ка́ко Го́спода моєго́ Ісу́са Христа́, а́ще і я́ві для всіх непови́нен бі, по стогнам Ієрусали́ма влачать от єди́наго суди́лища до друга́го: от Пила́та ко І́роду Галилейському; ка́ко Он во дворі́ сего́ уби́йці Предте́чева уничиже́н бисть, осмеян, к безу́мним причте́н; ка́ко во оде́жді посмія́нія па́ки в преторію Пила́та приведе́н. Ви́жду сія́, стижду́ся діл мої́х; таково́є поруга́ніє Го́споду сла́ви повлекших, і не престаю́ взива́ти:","Поми́луй м'я Бо́же, поми́луй м'я!","Слава: Ви́жду, ка́ко малоду́шний Пила́ть, зверськую неістовую зло́бу враго́в Го́спода укроти́ти жела́я, преда́ Єго́ бесчеловечним во́їном на многообра́зная муче́нія. Ка́ко они́ пречи́стоє ті́ло Єго́ обнажи́ша, ка́ко к позорному столбу Єго́ прив'яза́ша, ка́ко бичами і терновими розгами по главі́ і раменам Єго́ ударя́ху, ка́ко вінце́м от те́рнія венчаху, ка́ко руга́хуся, преклоня́ющеся пред Ним, по лицю́ ударя́юще і о́чі Єму́ закрива́юще. Ви́жду сія́ і ужаса́юся, поєли́ку за моє́ окая́нство та́ко стра́ждеть Госпо́дь, поверга́юся ниць і тисящекратно взива́ю: поми́луй м'я Бо́же, поми́луй м'я, Бо́же О́тче, поми́луй м'я, Бо́же Сло́ве, поми́луй м'я, Бо́же Душе́ Святи́й, поми́луй м'я!","І нині: О, Пресвята́я і Преблагослове́нная Ді́во Марі́є! А́ще і пре́дан в руки́ враго́в Сладча́йший Ісу́с, превожделі́ннійший Син Твой, а́ще і пору́ган, ізмучен і я́ко злоді́й осужде́н обетованний Іскупи́тель ми́ра, но Бо́жий єсть Син, Госпо́дь небесе́ і землі́. Пом'яни́ м'я во Ца́рствії Єго́ і во Твоє́м с Ним соцарствії, пом'яни́ і спаси́ ду́шу мою́, вопію́щую к Нему́: Поми́луй м'я Бо́же, поми́луй м'я!"]},{"h":"Пісня 9","ps":["Ірмос: Не рида́й Мене́ Ма́ти, зря́щи во гро́бі, Єго́ же во чре́ві без сі́мене зачала́ єси́ Си́на: возста́ну бо і просла́влюся, і вознесу́ со славой непреста́нно, я́ко Бог, ві́рою і любо́вію Тя величающия.","Поми́луй м'я Бо́же, поми́луй м'я!","Вопроше́н бисть проро́к Ієремия втори́цею от Го́спода: что ти ви́диши? Вопрошу́ і аз тебі́, многогрі́шная душе́ моя́, что ти ви́диши? Что ви́диши днесь, в шести́й день Страстни́я і стра́шния Седьми́ці? Ви́жду Го́спода Ісу́са Христа́ долготерпіли́вно і безмо́лвно внима́ющаго чтомому с лифостротона Липатову приговору, є́же да ра́сп'ят бу́деть на Кресті́; ви́жду Єго́ гряду́щаго на Голго́фу і под тя́жестію несомаго Їм Креста́ ізнемога́ющаго; іду́ в слід Єго́, покланя́юся Єму́ і, моля́ взя́ти і моя́ вся согріше́нія на всеочистительний Крест, взива́ю:","Поми́луй м'я Бо́же, поми́луй м'я!","Ви́жду пречи́стоє, пресвято́є, от Пречи́стия і Пресвяти́я Ді́ви Марі́ї неізрече́нно рожде́нноє Христа́ моєго́ ті́ло за спасе́ніє ми́ра на Кресті́ вознесе́нноє, все окровавленноє, все уя́звленноє, от ног до глави́ ці́лости не іму́щеє, ви́жду і в тре́петі іспові́дуя расп'я́тому Богочеловеку гріхи́ ю́ности і неві́дінія моєго́, взива́ю:","Поми́луй м'я Бо́же, поми́луй м'я!","Ви́жду те пресветлеї о́чі, я́же на всіх благоприветливо і любе́зні взираста, от ї́хже воззрі́нія печа́льнії утешахуся, унилії ободряхуся, грі́шнії к покая́нію обраща́хуся; ви́жду сі́ї радостотворнеї о́чі Христо́ви за моя́ нечи́стая і лука́вая воззрі́нія потемненними, кро́вію обліянними, і, ка́яся о мно́зім от мене́ злоупотребленії чуднейшаго із всіх чувств тіле́сних, вопію́ і не преста́ну вопи́ти:","Поми́луй м'я Бо́же, поми́луй м'я!","Ви́жду причистая уста́, от ни́хже непреста́нно струїся неізсяка́ємий пото́к небе́сния сла́дости, я́же ізрекаху сладча́йшия глаго́ли живота́, сві́та і прему́дрости; ви́жду сі́ї уста́ Христа́ моєго́, за праздносло́віє, буєсло́віє, злосло́віє, кощу́нство мої́х усте́н о́цтом і же́лчію напоєнними, жалею о всіх грехах язи́ка моєго́ і взива́ю:","Поми́луй м'я Бо́же, поми́луй м'я!","Ви́жду пречи́стая, к моли́тві на́шей преблагопослушливая ушеса́ Го́спода моєго́ Ісу́са Христа́, за гріхи́ мої́х уше́с, за моє́ сли́шаніє клеве́ть і наві́тов на бли́жняго, пересудов і осужде́нія нача́льства, за отвраще́ніє от сли́шанія Бо́жия сло́ва, за сія́ і іни́я моя́ гріхи́ преогорченнима і мно́гих поноше́ній, руганій і злі́йших обвиненій ісполненнима. Поверга́юся пред расп'ятим Господом мої́м Спаси́телем і взива́ю:","Поми́луй м'я Бо́же, поми́луй м'я!","Ви́жду ру́ці, пречи́стії ру́ці, от ї́хже прикоснове́нія смерть содрога́шеся, я́же всецелебним бі́ста врачевство́м проти́ву вся́каго неду́га і вся́кия болі́зні, в ни́хже ма́лия хлі́би до преізобилія умножа́хуся, я́ко да мно́гія ти́сящи наситять, ви́жду сі́ї ру́ці Го́спода моєго́ за беззако́нная дія́нія ру́ку моє́ю о́стрими желі́зними гвоздьми́ пронзеннима, от в'яза́нія посинелима, кров оби́льною струє́ю істочающима; ви́жду їх і жа́лостію істаява́ю, і в сокруше́нії о содеяннем мно́ю во всем житії́ моє́м, взива́ю:","Поми́луй м'я Бо́же, поми́луй м'я!","Ви́жду но́зі, я́же шествоваста по вода́м, я́ко по су́ху, я́же грі́шниця оми́ слеза́ми свої́ми і прия́т отпуще́ніє гріхо́м свої́м; но́зі, ї́хже а́ще кто сподо́биться би́ти подножієм, ви́шше ми́ра всего́ бу́деть, ви́жду сі́ї пречи́стії но́зі моєго́ Го́спода Ісу́са Христа́ за богопроти́вноє хожде́ніє моє́ю но́гу по многоразли́чним путе́м непра́вд і нече́стія, я́коже і ру́ці Єго́, ко Кресту́ пригвожденнима, пото́ки кро́ве ліющима, ви́жду їх, содрага́юся, воспомина́я хожде́нія і ісхожде́нія моя́, і в покая́нії взива́ю: Поми́луй м'я Бо́же, поми́луй м'я!","Слава: Ви́жду Го́спода моєго́, на Кресті́, во є́же спасти́ м'я стра́ждущаго, жа́ждою пали́маго, сли́шащаго поноше́нія, надсмеянія і руга́нія, ви́жду со́лнце помрачи́вшеєся, зе́млю трясущуюся, ка́меніє распадающеєся, сли́шу поледнєє сло́во Расп'я́таго: О́тче, в ру́ці Твої́ предаю́ дух Мой. Ви́жду Жизнода́вця бездиха́нна і уме́рша, трепе́щу, ужаса́юся і бія́ в пе́рси моя́ многогрі́шния, всім существо́м мої́м взива́ю: поми́луй м'я Бо́же, поми́луй м'я!","І нині: Ви́жду Пресвяту́ю, Пречи́стую Ді́ву Марі́ю у Креста́ Го́спода і Си́на Своєго́ предстоя́щую, ору́жієм жа́лости і ско́рби ма́терней пронзеннную. Ви́жду, ка́ко єди́н от во́їн ре́бра Го́споду прободе́ і а́біє кров і вода́ ізидо́ша. Ви́жду Никоди́ма і Іо́сифа, трепетними рука́ми снемлющия со Креста́ пречи́стоє ті́ло Єго́, в плащани́цю чи́стую то облекающия і во гро́бі но́ві полагающия. Покланя́юся Єму́, лобиза́ю живоно́сния я́зви Єго́, і ниць повергнувся, усти́ і всім се́рдцем взива́ю і пою́: поми́луй м'я Бо́же, поми́луй м'я!"]},{"h":"Молитва","ps":["О, Пресвята́я Ді́во, Ма́ти расп'я́таго за м'я Го́спода моєго́! О, святи́й А́нгеле Храни́телю мой! О святи́й Предте́че Госпо́день Іоа́нне і свята́я Марі́є Магдали́но! О, святі́ї апо́столи Пе́тре і Па́вле, Іоа́нне, Іа́кове і про́чії! О, святи́теліє Христо́ві Нико́лає, Дими́тріє, Митрофа́не, Філаре́те і Ти́хоне! О, преподо́бнії отці́ Анто́ніє і Феодо́сіє Кі́єво-Пече́рстії, Се́ргіє і Ни́коне Радонежстії, Серафи́ме Саро́вський, Амвро́сіє і про́чії отці́ О́птинськия і всі преподо́бнії! О, святі́ї пра́веднії Іоа́нне Кронштадський і Алексі́є Моско́вський! О, свята́я великому́ченице Варва́ро і про́чії му́ченици! О, святі́ї новому́ченици і іспові́дниці росси́йстії! О, святі́ї блаже́ннії Ксе́ніє і Матро́но і про́чії блаже́ннії і юро́дивия Христо́ви! Яві́те мні грі́шному небе́сную ми́лость ва́шу, і ї́миже ві́сте судьба́ми, благоустройте, да не бу́деть отринове́н покая́нний вопль мой, но да при́йметься і да вознесе́ться ко Престо́лу Пресвяти́я Тро́йці, Отця́ і Си́на, і Свята́го Ду́ха, і да низведе́ть в ду́шу мою́ світ, і ми́ра, і успокоє́ніє, сла́дость і ві́чноє неот'ємлемоє ра́дованіє о Ду́сі Свя́те, Єму́ же со Отце́м і Сино́м бу́ди сла́ва і поклоне́ніє во ві́ки. Амі́нь."]}],"notes":[]},{"u":"Канон преподобному Паїсію Великому за померлих без покаяння","e":"Canon to St Paisius the Great for those who died without repentance","secs":[{"h":"Тропар, глас 2","ps":["Боже́ственною любо́вію от ю́ности распала́єм, преподо́бне, вся кра́сная, я́же в ми́рі, возненави́ді, Христа́ єди́наго возлюби́л єси́, сего́ ра́ди в пусти́ню всели́ся, іді́же сподо́бися Боже́ственнаго посіще́нія, Єго́же неудо́б зрі́ти і а́нгельськима очи́ма, паде́, поклони́ся. Вели́кий же Дарода́тель, я́ко Человіколю́бець рече́ к тебі́: не ужаса́йся, возлю́бленний Мой, діла́ твоя́ уго́дна Мні. Се даю́ тебі́ дар: о ко́єм-ли́бо грі́шниці помо́лишися, отпу́стяться єму́ гріси́. Ти же в чистоті́ се́рдця твоєго́ возгорі́ся, приє́м во́ду і прикосну́ся Неприкоснове́нному, уми́ но́зі Єго́ і, во́ду пив, да́ром чуде́с обогати́ся, боля́щия ісціля́ти, бі́си от челові́к отгоня́ти і грі́шники от муки́ моли́твою своє́ю ізбавля́ти. О преподо́бне о́тче Паї́сіє, молю́ тя, да умо́лиши і о мні, я́коже тебі́ Бог обітова́, і́бо от сих грі́шник пе́рвий аз єсьм, да дасть мі Госпо́дь вре́м'я покая́нія і прости́ть моє́ согріше́ніє, я́ко Благи́й і Человіколю́бець, да со всі́ми і аз воспою́ Єму́: аллилу́я. (двічі)","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху. І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Богородичен: Вся па́че сми́сла, вся пресла́вная Твоя́, Богоро́дице, та́їнства, чистото́ю запечатлі́нна, і ді́вством храни́ма, Ма́ти разумі́ся нело́жна, Бо́га ро́ждши і́стиннаго, Того́ моли́ спасти́ся душа́м на́шим."]},{"h":"Канон, глас 6. Пісня 1","ps":["Ірмос: Помо́щник і Покрови́тель бисть мні во спасе́ніє, Сей мі єсть Бог, і просла́влю Єго́. Бог отця́ моєго́ і вознесу́ Єго́, сла́вно бо просла́вися.","Приспів: Преподо́бне о́тче Паї́сіє Вели́кий, моли́ Бо́га о нас.","І́же вся умудря́ющему Бо́гу моли́ся, преподо́бне о рабі́ своє́м, да отве́рзеть мі устні́ недостоїнії, і двигнеть мі язи́к недоумі́нний. Тісноту́ же і худогла́сіє, о́тче, разве́рзі благода́тію, і́же в тебі́ Свята́го Ду́ха, к пі́нію чуде́с твої́х.","Приспів: Преподо́бне о́тче Паї́сіє Вели́кий, моли́ Бо́га о нас.","Начну́ у́бо достохва́льноє і душеполе́зноє житіє́ твоє́ от младе́нства. І́же дре́вле Єги́пет вели́каго во проро́ціх проізнесе́ Мойсе́я, і́же к Бо́гу присвоє́нієм і вели́кими чудеси́ просла́вися. Та́ко і ни́ні втори́цею просла́влен показа́ся Єги́пет, тебе́ ра́ди, о́тче Паї́сіє, честни́м і́менем твої́м і мно́гими доброді́тельми обогати́ся, є́же дарова́ тебі́ Госпо́дь, Єго́же моли́, да спасе́ть душа́ на́ша.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","В Ца́рство Небе́сноє вшед у́зьким путе́м і приско́рбним по за́повіді Влади́ки своєго́ Христа́, преподо́бне о́тче Паї́сіє, широ́кий і простра́нний путь возненави́дів, распространьшійся мрак ума́ моєго́ отжени́, да возмогу́ ма́лоє сіє́ моле́ніє принести́ в пречестну́ю па́м'ять твою́.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Богородичен: Дух сокруше́н пода́ждь мі, Блага́я, смире́нно се́рдце, уму́ же чистоту́ і житію́ ісправле́ніє і прегріше́нієм оставле́ніє.","Катавасія: Ізба́ви от муки́ ві́чния усо́пшаго раба́ своєго́ (ім’я), преподо́бне о́тче Паї́сіє Вели́кий, я́ко всі по Бо́зі к тебі́ прибіга́єм, ти бо мо́лиши о нас Христа́ Бо́га на́шего (поклін). Го́споди, поми́луй (тричі з поклонами).","Або ця катавасія: Ізба́ви от бід раби́ своя́, преподо́бне о́тче Паї́сіє, я́ко всі по Бо́зі к тебі́ прибіга́єм, ти бо мо́лиши о нас Христа́ Бо́га на́шего (поклін). Го́споди, поми́луй (тричі з поклонами)."]},{"h":"Пісня 3","ps":["Ірмос: Утверди́, Го́споди, на ка́мені за́повідей Ті подви́гшеєся се́рдце моє́, я́ко Єди́н Свят єси́ і Госпо́дь.","Приспів: Преподо́бне о́тче Паї́сіє Вели́кий, моли́ Бо́га о нас.","Ка́меню ві́ри Петру́ апо́столу уподо́бился єси́, расп'я́ться ми́рові во всей жи́зні своє́й, преподо́бне Паї́сіє, і но́зі свої́ невозвра́тно к небе́сному ше́ствію упра́вил єси́, і го́рняго Ієрусали́ма дости́гл, со святи́ми предстоя́ Святі́й Тро́йці, моли́ о мні єди́наго Блага́го Человіколю́бця.","Приспів: Преподо́бне о́тче Паї́сіє Вели́кий, моли́ Бо́га о нас.","Благочести́ваго ко́рени пресві́тлая о́трасль, тебі́ ізбра́ Госпо́дь, а́нгел рече́ ма́тері твоє́й, сей Бо́гу уго́ден. Ти же от младе́нства крест свой взем, невозвра́тним путе́м Тому́ послі́дова, і возраста́ше лі́ти і ра́зумом ку́пно і благода́тію Бо́жиєю. Моли́ да́ти мі отпуще́ніє гріхо́в.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","О, Влади́ко Го́споди Ісу́се Христе́, кто не удиви́ться Твоєму́ человіколю́бію, єгда́ при́йде жела́ніє преподо́бному іночесько житіє́ получи́ти к ді́ланію за́повідій Твої́х, Твоє́ю благода́тію я́ко а́гнець непоро́чен ізведеся в пусти́ню, і дости́гл слове́сних ове́ць, і введе́ся к па́стирю блаже́нному Памве, і облече́ся во і́ночеський о́браз, в не́мже утверди́ і мене́ Го́споди, моли́твами преподо́бнаго Па́їсія, к ді́ланію за́повідій Твої́х.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Богородичен: Лю́тих м'я мук, і тьми кромі́шния і геє́нни, Твої́ми моли́твами свободи́, Ді́во, і́маши бо во́лю і си́лу, Го́спода ро́ждшая єди́наго Преблага́го.","Катавасія: Ізба́ви от муки́ ві́чния усо́пшаго раба́ своєго́ (ім’я), преподо́бне о́тче Паї́сіє Вели́кий, я́ко всі по Бо́зі к тебі́ прибіга́єм, ти бо мо́лиши о нас Христа́ Бо́га на́шего (поклін). Го́споди, поми́луй (тричі з поклонами).","Або ця катавасія: Ізба́ви от бід раби́ своя́, преподо́бне о́тче Паї́сіє, я́ко всі по Бо́зі к тебі́ прибіга́єм, ти бо мо́лиши о нас Христа́ Бо́га на́шего (поклін). Го́споди, поми́луй (тричі з поклонами)."]},{"h":"Сідален, глас 2","ps":["Ду́шу связа́в любо́вію Христо́вою, земна́я возненави́дів вся му́дре, водвори́лся єси́, о́тче преподо́бне, в пусти́нях і гора́х, разу́мнаго дре́ва вкуш сла́вне, а́нгельськи просія́л єси́. Ті́мже і мрак проше́д пло́ті своєя́, тьму отгна́л єси́ бісо́в Паї́сіє, і́нокующим пе́рвий, моли́ Христа́ Бо́га, гріхо́в оставле́ніє пода́ти, чту́щим любо́вію святу́ю па́м'ять твою́.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху. І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Богородичен: Ско́рий покро́в і по́мощ і ми́лость покажи́ на рабі́ Своє́м, Чи́стая, і во́лни укроти́ су́єтних помишле́ній, і па́дшую мі ду́шу возста́ви, Богоро́дице, вім бо, вім я́ко мо́жеши, єли́ко хо́щеши."]},{"h":"Пісня 4","ps":["Ірмос: Усли́ша проро́к прише́ствіє Твоє́, Го́споди, і убоя́ся, я́ко хо́щеши от Ді́ви роди́тися і челові́ком яви́тися, і глаго́лаше: усли́шах слух Твой і убоя́хся, сла́ва си́лі Твоє́й, Го́споди!","Приспів: Преподо́бне о́тче Паї́сіє Вели́кий, моли́ Бо́га о нас.","Законострадальчеськоє житіє́ от м'я́гких ногте́й восприї́м богому́дре Паї́сіє, да́же до конця́ преби́л єси́, я́ко боже́ствен до́блественник віне́ць прия́л єси́ побі́ди от всіх Ца́рствующаго, моли́твами свої́ми ізбавля́ти от муки́ грі́шники, от них же пе́рвий єсьм аз, не забу́ди мене́.","Приспів: Преподо́бне о́тче Паї́сіє Вели́кий, моли́ Бо́га о нас.","Іму́ще моли́твенника крі́пка блаже́нне Паї́сіє, і обе́щника печа́льним, предста́теля і побо́рника і хода́тая благоче́стна, от вся́ких спаса́ємся бід, напа́стей і обстоя́ній.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Ве́лію суде́б бе́здну імі́яй, Той тебі́ рече́: се, бо даю́ ті дар, да все є́же про́сиши от Отця́ Моєго́ во і́м'я Моє́, да́сться тебі́, о ко́єм ли́бо грешнике помо́лишися, оста́в'яться гріси́ того́: сего́ ра́ди припа́даю ті, о́тче Паї́сіє, імі́я бе́здну согріше́ній, да отпу́стить твої́ми моли́твами І́же тебе́ обітова́, я́ко Благ і Человіколю́бець.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Богородичен: Глаго́л провещай, єгда́ пра́во і́мам суди́тися, Богороди́тельнице, к Своєму́ Си́ну, Пренепоро́чная, да обря́щу Тя тогда́ прибі́жище і заступле́ніє держа́внійшеє, і мук всіх ізбавля́ющи.","Катавасія: Ізба́ви от муки́ ві́чния усо́пшаго раба́ своєго́ (ім’я), преподо́бне о́тче Паї́сіє Вели́кий, я́ко всі по Бо́зі к тебі́ прибіга́єм, ти бо мо́лиши о нас Христа́ Бо́га на́шего (поклін). Го́споди, поми́луй (тричі з поклонами).","Або ця катавасія: Ізба́ви от бід раби́ своя́, преподо́бне о́тче Паї́сіє, я́ко всі по Бо́зі к тебі́ прибіга́єм, ти бо мо́лиши о нас Христа́ Бо́га на́шего (поклін). Го́споди, поми́луй (тричі з поклонами)."]},{"h":"Пісня 5","ps":["Ірмос: Із нощі́ утреннююща, Человіколю́бче, просвіти́, молю́ся, і наста́ви м'я на повелі́нія Твоя́, і научи́ м'я, Спа́се, твори́ти во́лю Твою́.","Приспів: Преподо́бне о́тче Паї́сіє Вели́кий, моли́ Бо́га о нас.","Посто́м удруча́я ті́ло своє́ о́тче Паї́сіє, іногда́ по причаще́нії Ті́ла і Кро́ві Христо́ви, я́ко а́нгел се́дмдесят дній без пи́щі тіле́сния пребива́я, боже́ственную держа́ву неізрече́нную іму́щи, і возмо́гши в себі́ живо́тную содержа́ти си́лу благода́тію Твоє́ю, па́че пи́щнаго укрепленія, сла́ва держа́ві Твоє́й, Го́споди.","Приспів: Преподо́бне о́тче Паї́сіє Вели́кий, моли́ Бо́га о нас.","Я́ко Іоа́нн Крести́тель у́зьким і приско́рбним путе́м ходи́ти проізво́лил єси́. Но той на Іорда́ні узрі́в Зижди́теля своєго́, устраши́ся і вопія́ше: не смі́ю приступи́ти сі́но огню́. Ти же, о́тче Паї́сіє, в пусти́ні іногда́ я́вльшагося Го́спода, не моги́й пречи́стаго лиця́ Єго́ зрі́ти, пад тре́петом одержи́м. Он же ті рече́: не устраша́йся, сію́ пусти́ню напо́лню постниками тебі́. С ни́миже мо́лим, о́тче, не забу́ди нас, моли́твенник твої́х, поми́лованних би́ти.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Аз бо в нача́лі моя́ пред Тобо́ю зрю согріше́нія, і о мої́х беззако́ніїх молю́ Твоє́ милосе́рдіє, да простиши і покри́єши благоутро́бієм Твої́м мно́жество гріхо́в мої́х, і даждь мі про́чеє жи́зні сея́ вре́м'я безгрі́шно проводи́ти. Да удо́б на спасе́нія стезю́ поте́к, безпреткнове́нно к до́брому концю́ дости́гну Твоє́ю по́мощію, кромі́ бо Твоєя́ по́мощі і наставле́нія нічто́же бла́го соверши́ти, і ми́лость у Тебе́ получи́ти кто мо́жеть.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Богородичен: Ра́бськоє приношу́ Ті моле́ніє неразу́мний аз, і к Твоєму́ прибіга́ю благоутро́бному милосе́рдію, не отврати́ мене́, Чи́стая, посра́млена.","Катавасія: Ізба́ви от муки́ ві́чния усо́пшаго раба́ своєго́ (ім’я), преподо́бне о́тче Паї́сіє Вели́кий, я́ко всі по Бо́зі к тебі́ прибіга́єм, ти бо мо́лиши о нас Христа́ Бо́га на́шего (поклін). Го́споди, поми́луй (тричі з поклонами).","Або ця катавасія: Ізба́ви от бід раби́ своя́, преподо́бне о́тче Паї́сіє, я́ко всі по Бо́зі к тебі́ прибіга́єм, ти бо мо́лиши о нас Христа́ Бо́га на́шего (поклін). Го́споди, поми́луй (тричі з поклонами)."]},{"h":"Пісня 6","ps":["Ірмос: Возопи́х всім се́рдцем мої́м к ще́дрому Бо́гу, і усли́ша м'я от а́да преіспо́дняго, і возведе́ от тлі живо́т мой.","Приспів: Преподо́бне о́тче Паї́сіє Вели́кий, моли́ Бо́га о нас.","Безду́шная твар Іорда́н своєго́ Творця́ устиді́ся, вопія́ше: не могу́ Безгрі́шнаго оми́ти. Святи́й же ви́ді Го́спода, приї́м во́ду, прикосну́ся Неприкоснове́нному, уми́ но́зі Єго́. І пив во́ду, і прия́ дар ціли́ти неду́ги і прогони́ти от челові́к бі́си. Сего́ ра́ди і ми припа́даєм ті, о́тче, моли́твами твої́ми поми́луй нас от вся́ких бісо́вських наведе́ній.","Приспів: Преподо́бне о́тче Паї́сіє Вели́кий, моли́ Бо́га о нас.","По сла́ві Го́спода на́шего Ісу́са Христа́, обріто́хом тя, о́тче Паї́сіє, вели́коє прибі́жище, і засту́пника і тепла́ моли́твенника о грісі́х на́ших. Я́ко же пе́рвіє і́нока преста́вльшася, і христия́нства отчуждившася і во глубину́ а́дову па́губним безверієм низведе́ся, і єгда́ ощутився притече́ к тебі́, да умо́лиши Всеми́лостиваго. Ще́дрий же Госпо́дь яви́ся тебі́ і глаго́ла: о, уго́дниче Мой, добро́ єсть Моє́й любві́ подо́б'яся, пече́шися о грі́шних, ізволяяй муки́ прия́ти за їх ізбавле́ніє.","Приспів: Преподо́бне о́тче Паї́сіє Вели́кий, моли́ Бо́га о нас.","Принесе́ся моли́тва твоя́ і сле́зи к Бо́гу, я́ко благово́нний фимія́м, і же́ртва непоро́чна і благоприя́тна, і мене́ не забу́ди хода́тайством твої́м ко Пресвяті́й Богоро́дице, сле́зи умиле́нія да́си мі, оми́й гріхо́в мої́х бе́здну, ізба́ви м'я от сме́ртния глубини́. І не наді́ющимся пода́ждь ве́лію ми́лость, і прости́ їм согріше́нія.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Весь недоумі́нієм одержи́м єсьм, єгда́ прийму́ во умі́ той час стра́шний іспита́нія Судії́ і Бо́га, і пла́чуся і сі́тую і рида́ю, помина́я бе́здну зол мої́х. Ті́мже спаси́, Человіколю́бче, моли́твами Твоєго́ уго́дника преподо́бнаго Па́їсія, і ізба́ви м'я муки́, я́ко Благоутро́бен.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Богородичен: От се́рдця стена́нія приноша́ю Ті, Пренепоро́чная, Твоє́ прося́ благопреби́тноє заступле́ніє. Поми́луй всестрастну́ю мі ду́шу, умилосе́рдися, Ма́ти многоми́лостиваго Бо́га, ізба́вити м'я Суда́ і єзе́ра о́гненнаго.","Катавасія: Ізба́ви от муки́ ві́чния усо́пшаго раба́ своєго́ (ім’я), преподо́бне о́тче Паї́сіє Вели́кий, я́ко всі по Бо́зі к тебі́ прибіга́єм, ти бо мо́лиши о нас Христа́ Бо́га на́шего (поклін). Го́споди, поми́луй (тричі з поклонами).","Або ця катавасія: Ізба́ви от бід раби́ своя́, преподо́бне о́тче Паї́сіє, я́ко всі по Бо́зі к тебі́ прибіга́єм, ти бо мо́лиши о нас Христа́ Бо́га на́шего (поклін). Го́споди, поми́луй (тричі з поклонами).","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху. І ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Кондак, глас 2","ps":["Жите́йських молв оста́вль, безмо́лвноє житіє́ возлюби́л єси́, Крести́телю подо́б'яся всі́ми о́брази, с ни́мже тя почита́єм, о́тче отце́в Паї́сіє."]},{"h":"Ікос","ps":["Христо́в глас усли́шав, ше́ствовал єси́ во слід Того́ за́повідій, наг житія́ бив, отве́рг попече́нія і вся стяжа́нія і імі́нія, і бра́тій свої́х і любве́ ма́тере, богоно́сне Паї́сіє, єди́н в пусти́нях Бо́гові бесі́дуя ра́зумом, дарова́нія прия́л єси́, є́же мі посли́ в пі́сніх пою́щему, отце́в нача́льниче Паї́сіє."]},{"h":"Пісня 7","ps":["Ірмос: Согріши́хом, беззако́нновахом, непра́вдовахом пред Тобо́ю, ніже́ соблюдо́хом, ніже́ сотвори́хом, я́коже запові́да нам, но не преда́ждь нас до конця́, отце́в Бо́же.","Приспів: Преподо́бне о́тче Паї́сіє Вели́кий, моли́ Бо́га о нас.","Мно́гих гріхо́в іспо́лнен аз, і твоя́ моли́тва я́ко кади́ло благово́нно іспра́вися о́тче. Бе́здну гріхо́в мої́х потреби́, і буя́ющеє мо́ре зла́го житія́ ізсуши́, і напоє́ніє гні́вноє отжени́, і цілому́дренний ум моли́твами свої́ми утверди́, о́тче Паї́сіє.","Приспів: Преподо́бне о́тче Паї́сіє Вели́кий, моли́ Бо́га о нас.","Наста́вника тя і моли́твенника тепла́ іму́щи, і ско́раго помо́щника, я́ко сті́ну тве́рду і забра́ло недви́жимо і воєво́ду крі́пка і непобіди́ма мо́лим тя, не забу́ди моли́твенник твої́х, ізбавля́я от ві́янія печа́лі і наві́т вра́жиїх.","Приспів: Преподо́бне о́тче Паї́сіє Вели́кий, моли́ Бо́га о нас.","О, чу́до ве́ліє, во єди́н от дній сідя́щу ті, о́тче Паї́сіє, в пеще́рі, бисть ті глас глаго́ляй: мир тебі́, возлю́бленному Моєму́ уго́днику, ти же возста́в со стра́хом, і тре́петом одержи́м, паде́ поклони́ся і рече́: се, раб Твой, Го́споди. Сего́ ра́ди мо́лим тя, моли́ Человіколю́бця, да спасе́ть душі́ на́ша.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Даждь мі Христе́ ра́зум і терпі́ніє, є́же не осужда́ти согріша́ющих с киче́нієм фарисе́йським, но я́ко митаре́во покая́ніє прийми́, і я́ко блу́днаго си́на, Бо́же, ве́чері Твоє́й досто́йна м'я яви́, моли́твами преподо́бнаго Па́їсія, і гріхо́в проще́ніє мі да́руй.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Богородичен: Возни́кни, о, стра́стная душе́, возста́ни окая́нная, бий із глубини́ в пе́рси, і іспусти́ слез істо́чники, да тя поми́луєть, окая́нную, милосе́рдая Ма́ти Христа́ Бо́га.","Катавасія: Ізба́ви от муки́ ві́чния усо́пшаго раба́ своєго́ (ім’я), преподо́бне о́тче Паї́сіє Вели́кий, я́ко всі по Бо́зі к тебі́ прибіга́єм, ти бо мо́лиши о нас Христа́ Бо́га на́шего (поклін). Го́споди, поми́луй (тричі з поклонами).","Або ця катавасія: Ізба́ви от бід раби́ своя́, преподо́бне о́тче Паї́сіє, я́ко всі по Бо́зі к тебі́ прибіга́єм, ти бо мо́лиши о нас Христа́ Бо́га на́шего (поклін). Го́споди, поми́луй (тричі з поклонами)."]},{"h":"Пісня 8","ps":["Ірмос: Єго́же во́ї Небе́снії сла́в'ять і трепе́щуть Херуви́ми і Серафи́ми, вся́ко диха́ніє і твар, по́йте, благослові́те і превозносі́те Єго́ во ві́ки.","Приспів: Преподо́бне о́тче Паї́сіє Вели́кий, моли́ Бо́га о нас.","Благода́рно приноси́моє тебі́ пі́ніє сіє́ не пре́зри, о́тче Паї́сіє, но па́че прийми́ і ра́дости духо́вния іспо́лни, да без закосні́нія поклоню́ся твоєму́ о́бразу, іді́же єсть напи́сан, ісціле́нія всім подавающ.","Приспів: Преподо́бне о́тче Паї́сіє Вели́кий, моли́ Бо́га о нас.","Все преподо́бному житію́ поревнова́в богоуго́дних оте́ць, і́же от ві́ка пожи́вших, о́тче Паї́сіє, во смире́нії і по́стничестві Христа́ ра́ди всю жизнь свою́ му́ченичеськи сконча́л єси́, і от бісо́в нападе́нія мно́го претерпі́л єси́, і сих побіди́л. Сего́ ра́ди молю́ тя, о́тче, бу́йство, я́рость і небреже́ніє моли́твами твої́ми отри́ни от мене́.","Приспів: Преподо́бне о́тче Паї́сіє Вели́кий, моли́ Бо́га о нас.","Влади́ко Христе́ Бо́же Всеще́дрий, і́миже ві́си судьба́ми даждь мі ненави́діти дія́нія лука́ваго, Ти бо єси́ Бог наш реки́й: просі́те і при́ймете. Даждь любо́в от всея́ душі́ моєя́, моли́твами преподо́бнаго отця́ Па́їсія, твори́ти во́лю Твою́ спаси́тельную.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Молю́тися, на мні грі́шнім долготерпи́ Влади́ко, і не посіци́ мене́ я́ко непло́дноє дре́во посіче́нієм сме́ртним во огнь отсила́я, но плодоно́сна м'я сотвори́ моли́твами преподо́бнаго умоле́н бива́я, вре́м'я покая́нія мі даждь, я́ко Человіколю́бець.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Богородичен: Струї́ низпосли́ слез і стена́нія от душі́, сотвори́ мі, Чи́стая, внегда́ припа́дати к Твоєму́ покро́ву, я́ко да обря́щу разріше́ніє гріхо́в мої́х, Твоє́ю моли́твою.","Катавасія: Ізба́ви от муки́ ві́чния усо́пшаго раба́ своєго́ (ім’я), преподо́бне о́тче Паї́сіє Вели́кий, я́ко всі по Бо́зі к тебі́ прибіга́єм, ти бо мо́лиши о нас Христа́ Бо́га на́шего (поклін). Го́споди, поми́луй (тричі з поклонами).","Або ця катавасія: Ізба́ви от бід раби́ своя́, преподо́бне о́тче Паї́сіє, я́ко всі по Бо́зі к тебі́ прибіга́єм, ти бо мо́лиши о нас Христа́ Бо́га на́шего (поклін). Го́споди, поми́луй (тричі з поклонами)."]},{"h":"Пісня 9","ps":["Ірмос: Приі́мшая ра́дость от А́нгела, і ро́ждшая Созда́теля Своєго́, Ді́во, спаси́ Тебі́ величающия.","Приспів: Преподо́бне о́тче Паї́сіє Вели́кий, моли́ Бо́га о нас.","Ско́рий помо́щник бил єси́ преподо́бне, єще́ в жи́зні сей, іногда́ у преподо́бнаго ста́рця ученику́ в преслуша́нії уме́ршу, і ведену во ад, он же припа́даше прося́, да умо́лиши Всеще́драго о учениці́ єго́, ти же я́ко ско́рий послу́шник і любві́ храни́тель, наде́жду возложи́ ко Всеще́дрому Бо́гу простре́ся на моли́тву, і Той многоми́лостив і во обі́тіх нело́жний, во́лю к боя́щимся Єго́ сотвори́, і моли́тву твою́ усли́ша, ізведе́ ду́шу от а́да. Того́ ра́ди і аз недосто́йний, припа́дая молю́ тя, о́тче Паї́сіє, моли́твами твої́ми ізба́ви м'я муки́ і огня́ негаси́маго.","Приспів: Преподо́бне о́тче Паї́сіє Вели́кий, моли́ Бо́га о нас.","Би́вша м'я бісо́м сміх, челові́ком уничиже́ніє, пра́ведним рида́ніє, А́нгелом плач, оскверне́ніє возду́ху і землі́ і вода́м. Ті́ло окаля́х і ум оскверни́х, па́че сло́ва дія́ньми. Аз враг Бо́гу бих. Уви́ мні, согріши́х, моли́твами преподо́бнаго Па́їсія прости́ м'я.","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху.","Я́ко впади́й в разбо́йники і уя́звен, та́ко і аз впадо́х от мно́гих гріхо́в і уя́звена мі єсть душа́. Ко кому́ прибі́гну пови́нний аз? То́кмо к Тебі́, милосе́рдному душа́м Врачу́, прийми́ моле́бника тепла́ преподо́бнаго Па́їсія, і моли́твами єго́ ізле́й на м'я вели́кую Твою́ ми́лость.","І ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Богородичен: Прегріше́нії мої́ умно́жиша, проше́нію і суду́ досто́їн, Чи́стая, припа́дая зову́ Ті: пре́жде конця́ пода́ждь мі очище́ніє і умиле́ніє, і нра́вом ісправле́ніє.","Катавасія: Ізба́ви от муки́ ві́чния усо́пшаго раба́ своєго́ (ім’я), преподо́бне о́тче Паї́сіє Вели́кий, я́ко всі по Бо́зі к тебі́ прибіга́єм, ти бо мо́лиши о нас Христа́ Бо́га на́шего (поклін). Го́споди, поми́луй (тричі з поклонами).","Або ця катавасія: Ізба́ви от бід раби́ своя́, преподо́бне о́тче Паї́сіє, я́ко всі по Бо́зі к тебі́ прибіга́єм, ти бо мо́лиши о нас Христа́ Бо́га на́шего (поклін). Го́споди, поми́луй (тричі з поклонами)."]},{"h":"Молитва","ps":["Страсте́й побіди́теля, душа́м помо́щника, о всіх моле́бника, всім спасе́нія хода́тая і наста́вника, із глубини́ се́рдця воздиха́я, усе́рдно і пла́менно мо́лим тя, Паї́сіє Преподо́бне! Внемли́ і помози́ нам, не отринь і не пре́зри нас, но а́біє усли́ши в смире́нії се́рдця притека́ющих к тебі́. Ти, преподо́бне, к спасе́нію бли́жніх прилі́жно стремился і мно́гих грі́шников к сві́ту спасе́нія приве́л єси́. По́двиги чрезмерниє успокоєнієм считал по себі́, пречу́дне, і, любовю ко Го́споду всегда́ го́ря, явле́нія Христа́ Спа́са сподо́бился єси́, і Єму́, за люде́й Уме́ршему, любо́вію подража́я, і об отре́кшихся от Христа́ моли́лся єси́. Усли́ши нас, Паї́сіє прехва́льне, і́бо недосто́йни єсьми́ моли́тися о дарова́нії нам вели́кой ми́лости Госпо́дней, поне́же грі́шни єсьми́, і уста́ оскверне́нния і се́рдця отягоще́нния імі́єм, і под бре́менем прегріше́ній стра́ждем, і не достига́єть моли́тва на́ша до Го́спода. Сего́ ра́ди помоли́ся за нас мольбо́ю твоє́ю крі́пкою і богоприя́тною, святи́й Паї́сіє, да ізба́влени бу́дуть скончавшієся без покая́нія сро́дники, ближніє і знаємиє на́ші от муки́ ві́чния, і моли́тву твою́ во благоволе́нії при́йметь Спас наш і милосе́рдіє Своє́ вмі́сто до́брих діл їх дасть їм, свободи́ть їх, ві́руєм, от страда́ній і всели́ть в селе́ніях пра́ведних, і нас в покая́нії сконча́тися удосто́їть, да просла́вим вку́пі Всесвято́є і великолі́поє і́м'я Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Відпуст","ps":["Го́споди Ісу́се Христе́, Си́не Бо́жий, моли́тв ра́ди Пречи́стия Твоєя́ Ма́тере, і преподо́бнаго отця́ на́шего Па́їсія Вели́каго, і всіх ра́ди святи́х, поми́луй і спаси́ нас, я́ко Благ і Человіколю́бець. Амі́нь.","Го́споди, поми́луй (тричі)."]}],"notes":[]},{"u":"Канон Архангелу Божому Михаїлу","e":"Canon to the Archangel Michael","secs":[{"h":"Пісня 1","ps":["Ірмос: Отве́рзу уста́ моя́, і напо́лняться Ду́ха, і сло́во отри́гну Цари́це Ма́тері, і явлю́ся сві́тло торжеству́я, і воспою́, ра́дуяся, Тоя́ чудеса́.","Приспів: Святи́й Архістрати́же Михаї́ле, моли́ Бо́га о нас.","Боже́ственними світлостьми́ облистава́єм всегда́, ум мой озари́, є́же воспі́ти тя, Архістрати́же го́рніх во́їнств, всіх утвержде́ніє притека́ющих к тебі́.","Приспів: Святи́й Архістрати́же Михаї́ле, моли́ Бо́га о нас.","Ум пребезнача́льний, преми́рнаго чинонача́льника показа́ чи́на тя, пресла́вне Архістрати́же, і світ су́щих во тьмі, і Боже́ственноє украше́ніє Це́ркве Своєя́.","Умо́в предворяя небе́сних в Ду́сі, до́льним же всеїзря́днійше Михаї́ле, да́лся єси́ огражде́ніє, і утвержде́ніє, і ору́жіє, враги́ закала́ющеє і потребля́ющеє.","Богородичен: Ді́во Всенепоро́чная, я́же а́нгелов благолі́піє, челові́ков по́моще, Ти мні помози́ морепла́вающему, і в бу́рі гріха́ при́сно впа́дающу і бі́дствующу."]},{"h":"Пісня 3","ps":["Ірмос: Не му́дростію і си́лою, і бога́тством хва́лимся, но Тобо́ю О́тчею Іпоста́сною му́дростію, Христе́, ність бо Свят, па́че Тебе́ Человіколю́бче.","Приспів: Святи́й Архістрати́же Михаї́ле, моли́ Бо́га о нас.","Крі́постію Боже́ственною, Воєво́до а́нгелов всехва́льне, обхо́диши всю зе́млю, от лю́тих ни ізима́я, призивающия твоє́ Боже́ственноє і́м'я.","Приспів: Святи́й Архістрати́же Михаї́ле, моли́ Бо́га о нас.","Я́ко боже́ствен пропові́дник, я́ко предста́тель ві́рних непости́ден, заблу́ждших путево́ждь, і наказа́тель бил єси́, Бо́жий Архістрати́же Богови́днійший.","Боже́ственнаго сія́нія чи́стшеє зерца́ло яви́лся єси́, явле́нія честна́го сві́тло приє́м Ду́ха, Михаї́ле Первоа́нгеле досточу́дне.","Богородичен: Невеще́ственния уми́ соста́вивий во́лею, во веще́ственноє Твоє́ чре́во всели́ся хоті́нієм, Всенепоро́чная, пло́тію зрим Незрі́нний."]},{"h":"Сідален, глас 8","ps":["Небе́сних чино́в наста́вник, служи́тель же сла́ви Боже́ственния, досто́йно бив повелі́нієм Зижди́теля твоєго́, христия́ном єси́ хода́тай спаси́тельний, невеще́ственною твоє́ю сла́вою земни́я назира́я. Ті́мже по до́лгу благохва́лим тя всі, Боже́ственноє твоє́ днесь воспіва́юще торжество́, Михаї́ле Архістрати́же, моли́ Христа́ Бо́га, гріхо́в оставле́ніє дарова́ти, празднующим любо́вію Боже́ственная твоя́ чудеса́."]},{"h":"Інший сідален, глас 1","ps":["Лик а́нгельський Архистрати́га імі́я, Боже́ственнаго Михаї́ла, с ним Святі́й Тро́йці немо́лчноє приноша́єть піснопі́ніє, із не су́щих бо Соді́тель вся́чеських, во́їнства огнезра́чних чино́в, Сло́вом приведе́."]},{"h":"Пісня 4","ps":["Ірмос: Сідя́й в сла́ві на Престо́лі Божества́, во о́блаці ле́гці, при́йде Ісу́с Пребоже́ственний, нетлі́нною дла́нію, і спа́се зову́щия: сла́ва, Христе́, си́лі Твоє́й.","Приспів: Святи́й Архістрати́же Михаї́ле, моли́ Бо́га о нас.","Ум сий пе́рвий, соста́вил єси́ Боже́ственния уми́ хоті́нієм, нача́льника посреді́ сих Михаї́ла соді́ла, всеблаже́нним прича́стієм просвіща́єма, і у́мними Богонача́лії облиста́єма.","Приспів: Святи́й Архістрати́же Михаї́ле, моли́ Бо́га о нас.","Пі́ніє свято́є со Престо́ли, і Нача́ли, і Си́лами, і Властьми́, і Свяще́нними Госпо́дьстви возглаша́єши Тро́йце, пресла́вне Михаї́ле, спаса́я ни пою́щия тя.","Велича́єм всіх Творця́ же і Го́спода, за благоутро́біє да́вшаго обхране́ніє велича́йшеє, і необори́му сті́ну, і забра́ло, Михаї́ла нам світоза́рнаго Архистрати́га.","Богородичен: Ми́сленно, Ді́во, Твоєго́ Рождества́ пресла́вноє ска́зоваше дре́вле, священноявле́нний Ду́хом, го́ру присененную ви́дя Тя ясні́йше, із Нея́же Святи́й при́йде Бог воплоща́єм."]},{"h":"Пісня 5","ps":["Ірмос: Нечести́вії не у́зрять сла́ви Твоєя́, Христе́, но ми Тя Єдиноро́дне, Оте́чеськия сла́ви сія́ніє Божества́, от но́чі у́тренююще, воспіва́єм Тя Человіколю́бче.","Приспів: Святи́й Архістрати́же Михаї́ле, моли́ Бо́га о нас.","Яви́лся єси́ предводящ дре́вняго Ізра́їля, повелі́нієм Су́щаго, із Іа́кова челові́ком я́вльшагося дебельство́м ті́ла, Михаї́ле безтіле́сний, а́нгелов Архістрати́же.","Приспів: Святи́й Архістрати́же Михаї́ле, моли́ Бо́га о нас.","Невеще́ственними сія́нії обожа́єм при́сно, прича́стієм Богонача́льним, і нам осія́ніє світода́тельноє подава́єши, Первоа́нгеле, пресла́вно удивля́єм.","Украси́ся благода́тію Боже́ственний твой храм, в той бо прише́д, враче́вств пучи́ну єго́ показа́л єси́, Михаї́ле Первоа́нгеле, і страсте́й потреби́теля.","Богородичен: У́мних а́нгелов Тя показа́ Бог ви́шшую, всели́вся в Твоя́ ложесна́, Чи́стая Всенепоро́чная, Єго́же моли́ всегда́, уще́дрити пою́щия Тя."]},{"h":"Пісня 6","ps":["Ірмос: Возопи́, прообразу́я погребе́ніє тридне́вноє, проро́к Іо́на, в ки́ті моля́ся: от тлі ізба́ви м'я, Ісу́се Царю́ сил.","Приспів: Святи́й Архістрати́же Михаї́ле, моли́ Бо́га о нас.","Ра́дується ві́рних мно́жество, благохва́ляще тя, і сла́вить Всесвята́го Сло́ва, совоку́пльшаго земни́я со а́нгели, Михаї́ле, Своє́ю бла́гостію.","Приспів: Святи́й Архістрати́же Михаї́ле, моли́ Бо́га о нас.","Во́їнства Ізра́їлева спасл єси́, явля́яся, і Боже́ственная подая́ повелі́нія, Архістрати́же, враги́ низложи́л єси́, і в коне́ць сія́ істреби́л єси́.","Я́ко ви́ді тя Ісу́с Нави́н, поклони́ся, вопроси́в честна́го твоєго́ і свята́го і́мене, Нача́льниче А́нгелов, благогові́нієм і стра́хом держи́м.","Богородичен: Блаже́нні лю́діє, при́сно блажа́щії Тя, Блаже́нная, я́ко Бо́га Блаже́ннаго ро́ждшая, земна́я за милосе́рдіє неізрече́нним єдине́нієм обожи́вшаго."]},{"h":"Кондак, глас 2","ps":["Архістрати́же Бо́жий, служи́телю Боже́ственния сла́ви, А́нгелов нача́льниче і челові́ков наста́вниче, поле́зноє нам проси́ і ве́лію ми́лость, я́ко безпло́тних Архістрати́г."]},{"h":"Ікос","ps":["Рекл єси́ Человіколю́бче, в Писа́ніїх Твої́х, мно́жеству ра́доватися А́нгелов на небесі́, о челові́ці єди́ном кающимся, Безсме́ртне. Ті́мже ми, і́же в беззако́ніїх, Безгрі́шне Єди́не Сердцеві́дче, тя моли́ти всегда́ дерза́єм, я́ко Благоутро́бнаго, уще́дрити і низпосла́ти недосто́йним умиле́ніє, Влади́ко, подая́ нам проще́ніє, о всіх бо нас мо́литься Тебі́ Безпло́тних Архістрати́г."]},{"h":"Пісня 7","ps":["Ірмос: Спаси́й в огні́ авраа́мськия Твоя́ о́троки, і халде́ї уби́в, я́же пра́вда пра́ведно уловля́ше. Препі́тий Го́споди, Бо́же оте́ць на́ших, благослове́н єси́.","Приспів: Святи́й Архістрати́же Михаї́ле, моли́ Бо́га о нас.","Усмотри́в Данії́л, ви́ді купностоя́ща тя блаже́нне, і умудря́юща Того́ в Хова́рі, виді́ніє, є́же ви́ді Гавриї́ле молнієзра́чне, Михаї́ла Чинонача́льника Тому́ явля́юща.","Приспів: Святи́й Архістрати́же Михаї́ле, моли́ Бо́га о нас.","А́нгелов наста́вники, Богови́дния і світоно́сния, Михаї́ла і Гавриї́ла на́ші благи́я уті́шители, і предста́телі, і храни́тели, восхва́лим ві́рою велегла́сно.","Красе́н і всеблаголі́пен, і Богови́ден сий, вождь па́че ума́ невеще́ственних духо́в бил єси́, Михаї́ле світоза́рнійший, с ни́ми у́бо о всіх нас моли́ся.","Богородичен: Ума́ вели́каго і́стинно Сло́во Присносу́щноє, Ді́во, в Тя неізглаго́ланно і стра́шно всели́вшася, ви́дя, возопи́ Гавриї́л Арха́нгел: ра́дуйся, Престо́ле Височа́йшаго, Благослове́нная."]},{"h":"Пісня 8","ps":["Ірмос: Ізба́вителю всіх Всеси́льне, посреді́ пла́мене благочествовашія, снизше́д ороси́л єси́, і научи́л єси́ пі́ти: вся діла́ благослові́те, по́йте Го́спода.","Приспів: Святи́й Архістрати́же Михаї́ле, моли́ Бо́га о нас.","Ми́сленних безтіле́сних Чинонача́льник, моли́твенник спаси́телен, Боже́ствен Бо́жий служи́тель, Михаї́ле, показа́лся єси́, поя́ непреста́нно: вся діла́ благослові́те, по́йте Го́спода.","Приспів: Святи́й Архістрати́же Михаї́ле, моли́ Бо́га о нас.","Світи́льника два всесві́тлая, Михаї́ле і Гавриї́ле Арха́нгели, Трисві́тлаго Божества́ сія́ньми твар просвіща́ющії, лю́тих мглу отгоня́єте.","Я́ко до́брії ко́рмчії Арха́нгели, ко приста́нищу Боже́ственния во́лі душе́вний кора́бль мой спаса́йте, от бу́рі гріхо́в па́дший і бі́дствующий.","Богородичен: Невістокраси́тель, Боже́ственний Арха́нгел, предста́в, приглаша́ше Тебі́, є́же ра́дуйся, Неві́сто Бо́жия Безневі́стная, А́нгелов Сла́во і челові́ков Спасе́ніє і Огражде́ніє."]},{"h":"Пісня 9","ps":["Ірмос: Є́ва у́бо неду́гом преслуша́нія кля́тву всели́ла єсть, Ти же, Ді́во Богоро́дице, прозябе́нієм чревоноше́нія ми́рові благослове́ніє процвіла́ єси́: тім Тя всі велича́єм.","Приспів: Святи́й Архістрати́же Михаї́ле, моли́ Бо́га о нас.","Се благолі́піє твоєго́ Арха́нгеле, Боже́ственнаго хра́ма осія́ющеє, світоза́рним твої́м прису́тствієм, чуде́с мо́лнії іспуща́єть, і тьми неду́гов всегда́ отгоня́єть Боже́ственною благода́тію.","Приспів: Святи́й Архістрати́же Михаї́ле, моли́ Бо́га о нас.","Я́ко сопру́г красе́н, і лі́потен су́ще, Влади́чнім повелі́нієм, су́щим на землі́ служі́те Арха́нгели, от лю́тих ізимающе, і всім просвіще́ніє посила́юще спаси́тельноє, Боже́ственним Ду́хом.","Днесь ра́дуються с на́ми безтіле́снії Боже́ственнії у́ми, воспіва́єма, ви́дяще сего́ от всіх, вели́каго і сві́тлаго Архистрати́га, і любо́вію с на́ми пра́зднують, Жизнода́вця велича́юще.","Боже́ственная дво́їце, і світоза́рна, Арха́нгели, Михаї́ле всече́стне і Гавриї́ле препросла́вленне, Тро́йце Честні́й предстоя́ще, прегріше́ній вини́ і муки́ хвалящия вас ізба́віте.","Богородичен: Глас Тебі́ Боже́ственнаго Гавриї́ла прино́сим ра́достно і взива́єм: ра́дуйся раю́, дре́во посреді́ жи́зні імі́яй, Пречи́стая, Пресла́вная Сло́ва Пала́то. Ра́дуйся, Ді́во Всенепоро́чная."]}],"notes":[]},{"u":"Канон святому Архангелу Гавриїлу","e":"Canon to the Holy Archangel Gabriel","secs":[{"h":"Пісня 1","ps":["Ірмос: Отве́рзу уста́ моя́ і напо́лняться Ду́ха, і сло́во отри́гну Цари́це Ма́тері, і явлю́ся, сві́тло торжеству́я, і воспою́, ра́дуяся, Тоя́ чудеса́.","Приспів: Святи́й Арха́нгеле Бо́жий Гавриї́ле, моли́ Бо́га о нас.","Я́ко сві́та су́ща к Сві́ту кра́йнійшему невеще́ственними причаще́нії, боже́ственнаго і невеще́ственнаго, молю́ тя, арха́нгеле Госпо́день: ум мой просвіти́ моли́твами твої́ми, я́ко да воспіва́ю тя.","Приспів: Святи́й Арха́нгеле Бо́жий Гавриї́ле, моли́ Бо́га о нас.","Соста́вим днесь лик боже́ственний, веселя́щеся, пе́рваго почита́юще безпло́тних умо́в, неізрече́нную ра́дость возвісти́вшаго, в мир прише́дшую за бла́гость.","Предста́теля тя велича́йша, і к Бо́гу засту́пника, і сті́ну, і утвержде́ніє, Гавриї́ле, іму́ще, лю́б'ящії тя, ізбавля́ємся от бід і вре́да змії́на, восхваля́ющії тя.","Богородичен: Чи́сту Тя, Всенепоро́чную, Гавриї́л я́ко узрі́, — ра́дуйся! — Тебе́, Влади́чице, сві́тло возопи́, браконеїску́сная, челові́ков спасе́ніє, а́нгелов похвала́ і честносло́віє."]},{"h":"Пісня 3","ps":["Ірмос: Твоя́ пісносло́вці, Богоро́дице, живи́й і незави́стний істо́чниче, лик себі́ совоку́пльшія, духо́вно утверди́, в боже́ственній Твоє́й сла́ві, вінце́в сла́ви сподо́би.","Приспів: Святи́й Арха́нгеле Бо́жий Гавриї́ле, моли́ Бо́га о нас.","Прича́стієм Сві́та невеще́ственнійшаго, я́ко невеще́ствен воі́стину, Гавриї́ле, невеще́ственно просвіща́єм, світ ви́дін бил єси́ втори́й, веще́ственния всегда́ челові́ки просвіща́я, пою́щия тя.","Приспів: Святи́й Арха́нгеле Бо́жий Гавриї́ле, моли́ Бо́га о нас.","Велича́йшаго благосла́вія сподо́бился, єси́, вели́коє та́їнство нам откри́в, велича́йше а́нгелов, і́мже взя́ти би́хом от землі́ к велича́йшей висоті́ вельми́ чту́щії тя.","Яви́ся всім с небесе́, любо́вію і́щущим тя при́сно, і уста́ви бу́рю на ни дви́жимую напа́стей же і скорбе́й, о Гавриї́ле архістрати́же!","Богородичен: Сказу́я є́же дре́вле сокрове́нноє та́їнство, Отрокови́це, Тебі́ іногда́ Гавриї́л взива́ше: ра́дуйся, Бо́жия пала́то, в ню́же всели́вся, вся челові́ки обожи́, я́ко Благоутро́бен."]},{"h":"Сідален, глас 4","ps":["Безпло́тних служи́телей ти пе́рвствуяй, пре́жде вік опреділе́нноє стра́шноє та́їнство, тебі́ єди́ному, Гавриї́ле сла́вне, вві́рися, рождество́ неізрече́нноє Святи́я Ді́ви, ра́дуйся, провозглаша́я Єй, Обра́дованная. Ті́мже тя до́лжно, ві́рнії, с весе́лієм при́сно ублажа́єм."]},{"h":"Пісня 4","ps":["Ірмос: Неізслі́дний Бо́жий сові́т, є́же от Ді́ви воплоще́нія Тебі́, Ви́шняго, проро́к Авваку́м усмотря́я, зов'я́ше: сла́ва си́лі Твоє́й, Го́споди.","Приспів: Святи́й Арха́нгеле Бо́жий Гавриї́ле, моли́ Бо́га о нас.","Стоя́л єси́, прича́стіями богонача́льними дре́вле, Гавриї́ле досточу́дне, просвіща́я проро́ка Даниї́ла і ізложи́в явле́ніє недові́домих ду́хом.","Приспів: Святи́й Арха́нгеле Бо́жий Гавриї́ле, моли́ Бо́га о нас.","Усти́ бре́нними тя ра́достно, о́гненна єстество́м су́ща, восхваля́єм: ізми́ ни огня́ всегда́ паля́щаго, Боже́ственними, Гавриї́ле, хода́тайстви твої́ми.","Па́че со́лнця в боже́ственную оде́жду, сла́вою непристу́пною блиста́ющуся, одіва́єм, архістрати́же служи́телей, Царю́ предстої́ши Небе́сному, веселя́ся.","Богородичен: Всю Тя, ду́хом Гавриї́л преочище́ну, Всенепоро́чная, разумі́в, вопіє́ть Тебі́ я́вственно: ра́дуйся, кля́тви ізбавле́ніє і пра́отцев воззва́ніє."]},{"h":"Пісня 5","ps":["Ірмос: Ужасо́шася вся́чеськая о Боже́ственній сла́ві Твоє́й, Ти бо, Неіскусобра́чная Ді́во, імі́ла єси́ во утро́бі над всі́ми Бо́га і родила́ єси́ Безлі́тнаго Си́на, всім воспіва́ющим Тя мир подава́ющая.","Приспів: Святи́й Арха́нгеле Бо́жий Гавриї́ле, моли́ Бо́га о нас.","Ума́ прича́стієм Пе́рваго просвіща́єм, втори́й ви́дін бил єси́ світ, зови́й со безчи́сленними а́нгел чи́ньми: Свят Оте́ць Вседі́тель, Син Собезнача́лен і Дух Сопресто́лен.","Приспів: Святи́й Арха́нгеле Бо́жий Гавриї́ле, моли́ Бо́га о нас.","Вид твой о́гнен, добро́та пречу́дна, вся́ку мисль ужаса́я, ве́лія сла́ва, Гавриї́ле велича́йше, Боже́ственних безпло́тних нача́льниче, всіх удобре́ніє, ві́рно воспіва́ющих тя.","Боже́ственний я́ко ви́ді тя, во вре́м'я кажде́нія дре́вле стоя́ща, Заха́рія, бива́єть нем: не ві́рова бо твоєму́ возвіще́нію стра́шному, єго́же ізгласи́л єси́, Гавриї́ле архістрати́же.","Богородичен: Храм свяще́нія су́щи, Всенепоро́чная, гла́сом Гавриї́ла арха́нгела, во святи́х почива́ющаго родила́ єси́ Всесвята́го Бо́га, вся освяща́ющаго і лю́тих ізима́ющаго."]},{"h":"Пісня 6","ps":["Ірмос: Боже́ственноє сіє́ і всечестно́є соверша́юще пра́зднество, богому́дрії, Богома́тере, прийді́те рука́ми воспле́щим, от Нея́ ро́ждшагося Бо́га сла́вим.","Приспів: Святи́й Арха́нгеле Бо́жий Гавриї́ле, моли́ Бо́га о нас.","Земні́ї язи́ци почести́ тя, ума́ світоза́рнаго і небе́снаго, не возмо́гуть, пресві́тло просвіща́єма па́че ума́ неізрече́нно Боже́ственними світлостьми́.","Приспів: Святи́й Арха́нгеле Бо́жий Гавриї́ле, моли́ Бо́га о нас.","Заря́ со́лнця многосві́тлая, о́гненних слуг архістрати́же, світоно́сними твої́ми ко Влади́ці мольба́ми пою́щия тя тьми страсте́й ісхи́ти.","Сові́ти язи́ков разори́, ві́ру правосла́вную утверди́, уста́ви раздо́ри церко́вния, арха́нгеле, ко всіх Творцю́ твої́ми моли́твами.","Богородичен: Глаго́лов Боже́ственних послушли́ва, Чи́стая, Гавриї́лових била́ єси́, і Пребезнача́льнаго Сло́ва пло́тію родила́ єси́, безслове́сія мир ізба́вльшаго."]},{"h":"Кондак, глас 8","ps":["Пресві́тлия, і Честни́я, і Вседі́тельния, пренеісче́тния і стра́шния Тро́йці ти єси́, архістрати́же, сла́вний служи́телю і моли́твенниче, ни́ні непреста́нно моли́ ізба́витися нам от вся́ких бід і мук, да зове́м ті: ра́дуйся, покро́ве рабо́м твої́м."]},{"h":"Пісня 7","ps":["Ірмос: Не послужи́ша тва́рі богому́дрії, па́че Созда́вшаго, но, о́гненноє преще́ніє му́жеськи попра́вше, ра́довахуся, пою́ще: препі́тий отце́в Госпо́дь і Бог, благослове́н єси́.","Приспів: Святи́й Арха́нгеле Бо́жий Гавриї́ле, моли́ Бо́га о нас.","Іоа́нново рождество́, сла́вне, возвісти́л єси́ Заха́рії іногда́, внутр Боже́ственнаго хра́ма предстоя́щу і пою́щу Ізба́вителю і Бо́гу: препі́тий отце́в Госпо́дь і Бог, благослове́н єси́.","Приспів: Святи́й Арха́нгеле Бо́жий Гавриї́ле, моли́ Бо́га о нас.","Пресла́вноє хра́ма твоєго́ благолі́піє пресві́тло, Гавриї́ле, освяща́єть ду́ші ві́рних і повеліва́єть велегла́сно вопи́ти: препі́тий отце́в Госпо́дь і Бог, благослове́н єси́.","Просвіща́єм прича́стієм, архістрати́же, пе́рваго Сві́та та́йно, втори́й світ воі́стину ви́дін бил єси́, пою́щия просвіща́я всегда́: препі́тий отце́в Госпо́дь і Бог, благослове́н єси́.","Богородичен: По́слан бисть Гавриї́л архистрати́г, ра́дость возвіща́я Тебі́, Ді́во Ма́ти Чи́стая, Єя́же ра́ди печа́ль преста́, і кля́тва воі́стину онепло́дствися, і благослове́ніє процвіте́ ві́рним во ві́ки."]},{"h":"Пісня 8","ps":["Ірмос: О́троки благочести́вия в пещі́ Рождество́ Богоро́дичо спасло́ єсть, тогда́ у́бо образу́ємоє, ни́ні же ді́йствуємоє, вселе́нную всю воздвиза́єть пі́ти Тебі́: Го́спода по́йте діла́ і превозносі́те Єго́ во вся ві́ки.","Приспів: Святи́й Арха́нгеле Бо́жий Гавриї́ле, моли́ Бо́га о нас.","Священносло́вії свяще́нними тя лю́діє свяще́ннії пою́ть, веселя́щеся, ти бо всевино́вноє Сло́во воплоща́ємо, є́же по нам, арха́нгеле, су́щей от нас приглаша́єши Ді́ві па́че ума́ же і сло́ва. Ті́мже тя почита́єм во вся ві́ки.","Приспів: Святи́й Арха́нгеле Бо́жий Гавриї́ле, моли́ Бо́га о нас.","Уму́ вели́кому же і пе́рвому невеще́ственно, арха́нгеле, соєдиня́яся усти́ о́гненними твої́ми поє́ши піснопі́ніє стра́шноє, є́же пою́ть всі а́нгельстії ли́ци: Го́спода по́йте, діла́, і превозносі́те Єго́ во вся ві́ки.","Благосла́віями я́ві іспещре́н Боже́ственними, прехо́диши небе́сная, та́же і земна́я, соверша́я свяще́нная хоті́нія Христа́, всіх Бо́га, а́нгелов нача́льниче Гавриї́ле, красота́ ві́рою при́сно тя хва́лящих.","Пло́тію по іпоста́си Сло́во челові́ком приміси́тися хотя́, ім'я́ше тя, предтеку́ща і предугото́вающа свяще́нную пала́ту, о свяще́нний Гавриї́ле, Го́спода по́йте, вопію́ща, і превозносі́те Єго́ во вся ві́ки.","Богородичен: Я́ко престо́л красе́н Царе́в, я́ко всіх тва́рей прейму́щую, я́ко Пресу́щнаго єди́ну осуществова́вшую, челові́ки обожи́вшаго соєдине́нієм лу́чшим рождества́ неізрече́ннаго і стра́ннаго, благослове́нную воспої́м Ді́ву."]},{"h":"Пісня 9","ps":["Ірмос: Всяк земноро́дний да взигра́ється, Ду́хом просвіща́єм, да торжеству́єть же безпло́тних умо́в єстество́, почита́ющеє свяще́нноє торжество́ Богома́тере, і да вопіє́ть: ра́дуйся, Всеблаже́нная Богоро́дице, Чи́стая Присноді́во.","Приспів: Святи́й Арха́нгеле Бо́жий Гавриї́ле, моли́ Бо́га о нас.","Предстої́ши, стра́шно престо́лу благода́ті служа́, і облиста́єм світоли́тії су́щими па́че ума́, і свяще́нно обожа́єм, і Світ зрим, і просвіща́я ві́рою честву́ющия тя, свяще́нне Гавриї́ле архістрати́же.","Приспів: Святи́й Арха́нгеле Бо́жий Гавриї́ле, моли́ Бо́га о нас.","Я́коже не́бо, зри́шися, звізда́ми укра́шено, Боже́ственними світлостьми́, і, я́коже воєво́да, рука́ми держи́ши скиптр пресві́тлий і претека́єши всю зе́млю, во́лю Влади́чню всегда́ творя́ і лю́тих ві́рния ізима́я.","Утиши́ лю́тую ва́рварськую бу́рю, воздви́жемую всегда́ на раби́ твоя́, церко́вния уста́ви раздо́ри, пою́щим тя пода́ждь прегріше́ній ізбавле́ніє, ві́рним же да́руй побіди́тельная, Гавриї́ле, те́плим предста́тельством твої́м.","Предо́брая дво́їце і пресла́вная, Михаї́ле і Гавриї́ле, престо́лу предстоя́ще Боже́ственния сла́ви, всім просі́те гріхо́в проще́нія і злих преміне́нія, я́ко предста́теліє і я́ко бла́гости Влади́чни во всем подо́б'ящеся.","Богородичен: Світ блиста́нія рождество́м Твої́м возсія́, і просвіти́ всю подсо́лнечную, і предста́теля тьми погуби́, Богороди́тельнице Всечи́стая, а́нгелов хвало́ і челові́ков всіх спасе́ніє, непреста́нними гла́си восхваля́ющих Тя."]}],"notes":[]},{"u":"Канон на успіння святої праведної Анни, матері Пресвятої Богородиці","e":"Canon for the Dormition of the Holy Righteous Anna, Mother of the Theotokos","secs":[{"h":"Глас 4. Пісня 1","ps":["Ірмос: Отве́рзу уста́ моя́, і напо́лняться Ду́ха, і сло́во отри́гну Цари́це Ма́тері, і явлю́ся, сві́тло торжеству́я, і воспою́, ра́дуяся, Тоя́ чудеса́.","Приспів: Свята́я пра́ведная ма́ти А́нно, моли́ Бо́га о нас.","Согріше́ній проще́ніє, і злих ізбавле́ніє, і житія́ ісправле́ніє ни́ні мі іспроси́, твою́ світоно́сную па́м'ять почита́ющему днесь, А́нно всехва́льная.","Приспів: Свята́я пра́ведная ма́ти А́нно, моли́ Бо́га о нас.","Живо́т ро́ждшую боголі́пно родила́ єси́, ті́мже к присножи́зненній жи́зні преста́вилася єси́, наслажда́ющися ра́дости неізглаго́ланния і Сві́та невече́рняго, А́нно богозва́нная.","Приспів: Свята́я пра́ведная ма́ти А́нно, моли́ Бо́га о нас.","Благода́ть Боже́ственная к ра́дости преста́ви, без сі́мене ю́же роди́ Дщи сея́ Чи́стая, і предстої́ть со мно́гим дерзнове́нієм, Го́сподеві моля́щися спасти́ся всім.","Пра́ведно і преподо́бно пожи́вши, всехва́льная, к Пра́ведному Го́споду ни́ні преста́вилася єси́ ра́доватися с пра́ведними, і́же от ві́ка, ті́мже, соше́дшеся, тя ві́рою почита́єм.","Богородичен: Із Тебе́ нам возсія́ Со́лнце пра́ведноє, і всю озари́ богоразу́мієм зе́млю, і разори́ мглу неразу́мія, Чи́стая, Всенепоро́чная, і Всеблаже́нная."]},{"h":"Пісня 3","ps":["Ірмос: Не му́дростію, і си́лою, і бога́тством хва́лимся, но Тобо́ю, О́тчею іпоста́сною Му́дростію, Христе́: ність бо свят, па́че Тебе́, Человіколю́бче.","Приспів: Свята́я пра́ведная ма́ти А́нно, моли́ Бо́га о нас.","Заче́ншую Содержа́щаго вся зачала́ єси́ і родила́ єси́ па́че сло́ва Христа́ ро́ждшую, ті́мже твоє́ успе́ніє, А́нно, почита́єм.","Приспів: Свята́я пра́ведная ма́ти А́нно, моли́ Бо́га о нас.","С похвала́ми соверша́ється сла́вная па́м'ять твоя́, я́ко родила́ єси́ нам хвале́ній преви́шшую, чи́стую Богома́тер, А́нно богоприя́тная.","Приспів: Свята́я пра́ведная ма́ти А́нно, моли́ Бо́га о нас.","Я́коже со́лнце с луно́ю, А́нні совокупля́яся, сла́вний Іоаки́м, ді́вства зарю́ ражда́єть, Єя́же ра́ди Божества́ луча́ просія́.","Го́ру Боже́ственную із чресл твої́х родила́ єси́ і ко гора́м ми́сленним і рая́ селе́нієм, А́нно, премину́ла єси́, богоблаже́нная.","Богородичен: Тя Предста́тельницю тве́рдую, Богороди́тельнице, стяжа́хом, упова́ніє на Тя возложи́вше, спаса́ємся і, к Тебі́ бо прибіга́юще, огражда́ємся."]},{"h":"Сідален, глас 8","ps":["Ма́тере Влади́ки і Творця́ ма́ти била́ єси́, А́нно всехва́льная, Того́ повелі́нія при́сно храня́щи, сего́ ра́ди, уме́рши, к жи́зні безсме́ртній преста́вилася єси́ воі́стину і к Сві́ту невече́рнему. Ті́мже світоно́сную і святу́ю твою́ па́м'ять соверша́єм, ду́хом просвіща́ємі всегда́, і согла́сно вопіє́м ті: моли́ Христа́ Бо́га гріхо́в оставле́ніє дарова́ти чту́щим любо́вію святу́ю па́м'ять твою́."]},{"h":"Пісня 4","ps":["Ірмос: Сідя́й в сла́ві на Престо́лі Божества́ во о́блаці ле́гці, при́йде Ісу́с Пребоже́ственний, Нетлі́нною Дла́нію і спасе́ зову́щия: сла́ва, Христе́, си́лі Твоє́й.","Приспів: Свята́я пра́ведная ма́ти А́нно, моли́ Бо́га о нас.","Я́же в зако́ні пи́саная, поуча́ющися, соверши́ла єси́ і Законода́вця Ма́тере ма́ти била́ єси́, ті́мже тебе́ вся твар по до́лгу ни́ні сотворя́єть твою́ ра́достно па́м'ять.","Приспів: Свята́я пра́ведная ма́ти А́нно, моли́ Бо́га о нас.","Блаже́нноє чре́во твоє́ воі́стину, носи́вшеє Світ ми́ра внутр во чре́ві носи́вшую, і сосця́ твоя́ кра́сная, я́ко доі́вшая доі́вшую, А́нно, Христа́, Пита́теля на́шего.","Я́ко пожи́вши непоро́чно, Ю́же непоро́чно родила́ єси́, Богоро́дицю Отрокови́цю, Сло́во О́тчеє породи́вшую, і к Нему́ со сла́вою всели́лася єси́, обожена́ честни́ми воі́стину прича́стії.","Богородичен: Ді́ви чре́во — стог, я́коже на гумні́, воі́стину яви́ся, клас неді́ланен іму́щи, і́мже пита́ється вся́коє єстество́, зову́щеє: Всеси́льне, сла́ва, Христе́, си́лі Твоє́й."]},{"h":"Пісня 5","ps":["Ірмос: Нечести́вії не у́зрять сла́ви Твоєя́, Христе́, но ми Тя, Єдиноро́дне, Оте́чеськия сла́ви Сія́ніє Божества́, от но́щі у́тренююще, воспіва́єм Тя, Человіколю́бче.","Приспів: Свята́я пра́ведная ма́ти А́нно, моли́ Бо́га о нас.","Не́бо родила́ єси́ на землі́ воі́стину, ро́ждшую небесе́ Творця́, днесь тя преставля́юща к небе́сним со сла́вою, А́нно пресла́вная.","Приспів: Свята́я пра́ведная ма́ти А́нно, моли́ Бо́га о нас.","С невеще́ственними чи́ньми невеще́ственним умо́м лику́єши ра́достно, ісполня́єма сія́нія Богатода́вця, но нас помина́й, ві́рою хва́лящих тя.","От ко́рене Ієссе́єва прозя́бшая я́ві, благоцвіту́щий жезл, Чи́стую, ізрасти́ла єси́, сла́вная, ізрасти́вшую цвіт неув'яда́ющий, Ісу́са, Ізба́вителя на́шего.","Богородичен: К Тебі́ прибіга́ю єди́ній держа́вній, ві́рних покро́ву, на Тя наде́жду возлага́ю спасе́нія моєго́, Пресвята́я Влади́чице Богоро́дице, не пре́зри мене́."]},{"h":"Пісня 6","ps":["Ірмос: Пожру́ Ті со гла́сом хвале́нія, Го́споди, Це́рков вопіє́ть Ті, от бісо́вськия кро́ве очи́щшися, ра́ди ми́лости от ребр Твої́х істе́кшею кро́вію.","Приспів: Свята́я пра́ведная ма́ти А́нно, моли́ Бо́га о нас.","Го́спода Ісу́са Бо́га пра́отці, Іоаки́м же і А́нна, пра́вдою укра́шени, по достоя́нію в пі́сніх да восхва́ляться днесь.","Приспів: Свята́я пра́ведная ма́ти А́нно, моли́ Бо́га о нас.","Вся́чеських похва́л А́нна превзи́де, я́ко вся́кия похвали́ превозше́дшую родила́ єсть, сего́ ра́ди в ли́ці пра́ведних водворя́ється.","Приспів: Свята́я пра́ведная ма́ти А́нно, моли́ Бо́га о нас.","Світоно́сія і сві́тлости іспо́лнена па́м'ять твоя́, сія́нія же в ми́рі спаси́тельная іспуща́ющи, цілому́дренная А́нно, дарова́ній вся́чеських іспо́лни.","Ру́чку, ма́нну боже́ственную вмісти́вшую, во чре́ві носи́ла єси́, А́нно, і, с Не́ю ни́ні на небесі́х живу́щи, о всіх мо́лишися, прехва́льная.","Богородичен: От А́нни ми́рові родила́ся єси́, Цари́це, всіх Царя́ ро́ждшая, і, ді́вствующи по рождестві́, херуви́м преви́шши, Пренепоро́чная."]},{"h":"Кондак, глас 2","ps":["Прароди́телей Христо́вих па́м'ять пра́зднуєм, тіх ві́рно прося́ще по́мощі ізба́витися всім от вся́кия ско́рби, зову́щим: Бог наш с на́ми, сих прославле́й, я́коже благоволи́."]},{"h":"Ікос","ps":["Проро́чеськи сни́демся всі досто́йно пі́ти прама́тере Христо́ви блаже́нноє преставле́ніє: днесь бо от вре́менния преста́вися жи́зні, на небесі́х с ра́достію ше́ствіє творя́щи, ра́дується, я́ко су́щи ма́ти і́стинния су́щия Богоро́диці, і взива́єть ві́рно: вели́чить душа́ моя́ Го́спода, я́ко роди́х Сего́ Ма́тер на землі́, і́же Сію́ прославле́й, я́коже благоволи́."]},{"h":"Пісня 7","ps":["Ірмос: Спаси́й во огні́ авраа́мськия Твоя́ о́троки і халде́ї уби́в, я́же Пра́вда пра́ведно уловля́ше, препі́тий Го́споди, Бо́же оте́ць на́ших, благослове́н єси́.","Приспів: Свята́я пра́ведная ма́ти А́нно, моли́ Бо́га о нас.","Я́ко жи́зні і́стинния, А́нно, Ма́тер ро́ждши, к жи́зні і́стинній преста́вилася єси́ ко сві́ту, взива́ющи: препі́тий Го́споди, Бо́же оте́ць на́ших, благослове́н єси́.","Приспів: Свята́я пра́ведная ма́ти А́нно, моли́ Бо́га о нас.","Я́же Ма́тері Ізба́вителя ма́ти су́щи, А́нно, от землі́ к небесі́, доброді́тельми укра́шена, востече́, во хвале́нії зову́щи: Бо́же оте́ць на́ших, благослове́н єси́.","Приспів: Свята́я пра́ведная ма́ти А́нно, моли́ Бо́га о нас.","К несконча́ємій жи́зні, к простра́нній широті́ ра́йськия пи́щі, к невече́рнему сві́ту отшла́ єси́, богоно́сице, зову́щи: Бо́же оте́ць на́ших, благослове́н єси́.","Іспещре́на доброді́тельми, добро́тою Боже́ственних дарова́ній укра́шена, к Бо́гу преложи́ся, непреста́нно зову́щи: препі́тий Го́споди, Бо́же оте́ць на́ших, благослове́н єси́.","Богородичен: Укра́шена добро́тами доброді́телей, кра́снаго па́че сино́в челові́чеських родила́ єси́ Сло́во, Пренепоро́чная, кра́сними лі́потами украша́ющаго Тебі́ пісносло́в'ящих."]},{"h":"Пісня 8","ps":["Ірмос: О́троки благочести́вия в пещі́ Рождество́ Богоро́дичо спасло́ єсть, тогда́ у́бо образу́ємоє, ни́ні же ді́йствуємоє, вселе́нную всю воздвиза́єть пі́ти Тебі́: Го́спода по́йте, діла́, і превозносі́те Єго́ во вся ві́ки.","Приспів: Свята́я пра́ведная ма́ти А́нно, моли́ Бо́га о нас.","Ма́ти єди́ния Богоро́диці, я́же непло́ди пре́жде, ни́ні же прама́ти Христо́ва, я́коже непло́дства, си́це і ме́ртвости, совле́кши оде́жду, во страні́ живу́щих вопіє́ть: Го́спода по́йте, діла́, і превозносі́те Єго́ во вся ві́ки.","Приспів: Свята́я пра́ведная ма́ти А́нно, моли́ Бо́га о нас.","Христо́с тебі́ две́рі ви́шнія отве́рзе, ра́достно тя прия́т, я́ко двер родила́ єси́, є́юже Сам про́йде і затворе́ну яви́ по ісхожде́нії, богому́драя достойнопі́тая А́нно, ті́мже тя почита́єм, ві́рнії, во ві́ки.","Свя́то житіє́ сконча́вши, Святи́я Присноді́ви ма́ти била́ єси́, Я́же Пресвято́є Сло́во породи́, освяще́ніє і ізбавле́ніє нам подаю́ща, богому́драя і досточу́дная А́нно, ті́мже тя поє́м при́сно, ві́рнії, во ві́ки.","Богородичен: Мно́гими м'я содержи́ма біда́ми і бу́рею гріхо́вною бі́дствующаго, ко приста́нищу невла́ємому диха́нії Ду́ха, Богороди́тельнице Влади́чице, ни́ні наста́ви: приста́нище бо єси́ христия́н. Ті́мже Тя поє́м во вся ві́ки."]},{"h":"Пісня 9","ps":["Ірмос: Є́ва у́бо неду́гом преслуша́нія кля́тву всели́ла єсть, Ти же, Ді́во Богоро́дице, прозябе́нієм чревоноше́нія ми́рові благослове́ніє процвіла́ єси́. Тім Тя всі велича́єм.","Приспів: Свята́я пра́ведная ма́ти А́нно, моли́ Бо́га о нас.","От землі́ чре́ва твоєго́ воі́стину роди́ся земля́ свята́я, неді́ланен клас прозя́бши безсі́менно, ми́рові Пита́теля і Го́спода, тебе́ к пи́щі неіждива́ємой, А́нно, прему́дро преста́вльшаго.","Приспів: Свята́я пра́ведная ма́ти А́нно, моли́ Бо́га о нас.","Па́м'ять твоя́ днесь нам возсія́, со́лнця світлі́йши, сія́нієм бога́тих даро́в нас просвіща́ющи, всечестна́я, і мрак страсте́й ізима́ющи, ю́же соверша́ющих сохрани́.","Боже́ственний нас Іоаки́м і А́нна богому́драя і всесла́вная, супру́г честни́й і світоно́сний, созива́ють боже́ственне весели́тися сих пра́здником, єго́же уясни́ Світода́вець всіх Госпо́дь.","Богородичен: Марі́є Госпоже́ всіх, вся́кими м'я порабоще́на согріше́нії ни́ні свободи́: Сама́ бо Свободи́теля родила́ єси́ всіх, рабо́ти нас ізба́вльшаго гріхо́вния, Боже́ственним манове́нієм."]},{"h":"Світилен","ps":["Достодо́лжно воспоє́м богозва́нную А́нну: Богоро́дицю бо та Ді́ву Марі́ю ро́ждши па́че наде́жди, сро́дниця по пло́ті Христа́, Ізба́вителя на́шего, яви́ся, сію́ боголі́пно приє́мшаго днесь во ви́шніх, о нас моля́щуюся і о умире́нії ми́ра.","Богородичен: Не́бо ро́ждши, А́нно, но́воє, Марі́ю, Є́юже возсія́ сла́ви Со́лнце, днесь от землі́ к небе́сним прехо́диши, Христу́ сра́дующися, пресла́вная."]}],"notes":[]},{"u":"Канон покаянний до Господа Ісуса Христа (твір ієромонаха Василя (Рослякова))","e":"Canon of repentance to the Lord Jesus Christ (by Hieromonk Basil (Roslyakov))","secs":[{"h":"Глас 6. Пісня 1","ps":["Ірмос: Разступи́ся пучи́на чермна́я / і ублажи́ стопи́ Ізра́їля уничиже́ннаго, / сомкну́вшися же мгло́ю і бу́рею / над главо́ю го́рдості єги́петськия, / Го́спода просла́вивши во ві́ки, / я́ко і́стиннаго Судію́ і Ізба́вителя.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я!","Іді́же обря́щу нача́ло зла моєго́? О́крест воззрю́ і содрага́юся, внутр обращу́ся і возболе́зную, я́ко тьма го́ркая обстої́ть м'я. О Звіздо́ єди́ная, Христе́ Спа́се мой, достигни м'я луча́ми благода́ті Твоєя́.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я!","Со Ада́мом ни́ні сокруша́юся: ка́ко воспою́ Сві́та уте́ряннаго? Ка́ко возвіщу́ І́стину оста́вленную? А́ще реку́, я́ко не ви́діх Го́спода, ка́мені возопію́ть, облича́юще м'я. Ка́мо пойду́, презрі́в Тя, Спа́се, Путь і І́стина Сий, Христе́?","Слава: Не і́мам, Го́споди, вити́йства висо́каго, не вім глаго́лов прему́дрих, но, я́ко і отці́ на́ші от ві́ка, взива́ю Ті: поми́луй м'я, Бо́же, і спаси́ м'я.","І нині: Не покри́ю лука́вством лю́тих мої́х, но вся возвіщу́ Тебі́, Ді́во Чи́стая, оба́че не смире́нія іспо́лнен творю́ сія́, но безсти́дства потає́ннаго. Ти же, кро́тости Істо́чниче Пречи́стий, оми́й окая́нство душі́ моєя́ і целому́дріє во мні оживи́."]},{"h":"Пісня 3","ps":["Ірмос: Єди́ному дню времена́ уподобля́я, / ві́чності начерта́ніє показа́л єси́, Го́споди, / ті́мже во хра́мі сла́ви Твоєя́ ли́ки составля́ються, / ність свят, ра́зві Тебі́, Го́споди, взива́юще.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я!","Коли́ко оде́жд раздеру́ окая́нний, і поко́я дости́гну? Коли́ко пе́пла возложу́ на главу́ сра́мную мою́ і не іму́ помишле́ній лю́тих? Ко́їм вре́тищем покри́юся і не узрю́ беззако́ній мої́х? Всу́є м'яту́ся, іща́ покая́нія. Но Ти, Христе́, реки́й: без Мене́ не мо́жете твори́ти нічесо́же, пройди́ во у́ди моя́, разсеци сло́вом Твої́м ка́менную утро́бу мою́, порази́ ка́мень се́рдця моєго́ і ізведи́ істо́чники слез.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я!","Єгда́ в ску́дости пребива́ю, печа́ль і за́висть терза́ють м'я. Єгда́ же преспева́ю ма́ло, го́рдостію обурева́юся неудержи́мо; гріх а́лчний го́нить м'я, Го́споди. Прийми́ сокруше́ніє моє́, Влади́ко, іни́х бо даро́в і жертв не і́мам.","Слава: Отку́ду прийму́ сле́зи, а́ще не от Тебе́, Бо́же? Ка́мо гряду́ в день печа́лі, а́ще не во храм Твой, Влади́ко? Гді обря́щу утіше́ніє, а́ще не в словесі́х Твої́х, Свя́те? Не отри́ни мене́, Го́споди, і ни́ні пом'яни́ м'я.","І нині: При́зри на м'я, Влади́чице, і вся скве́рни моя́ попали́, да не обе́шу на ви́ю мою́ жерно́в осе́льський, но прах прегріше́ній мої́х принесу́ Христу́ Бо́гу моєму́, і возмете́ть от лиця́ преклоне́ннаго моєго́."]},{"h":"Сідален","ps":["Оста́вих Тя, Сві́те і́стинний, тьма обдержи́ть м'я і хлад, огнь мудрова́нія моєго́ не грі́єть м'я, но́щі сме́ртния ужаса́юся. Воста́ни ра́но, Го́споди, Со́лнце моє́, і оживи́ м'я теплото́ю Ду́ха Твоєго́.","Слава: У Тебе́, Влади́ко, прошу́ благода́ті, но та́йную наде́жду полага́ю в крі́пості моє́й; велича́ю і благодарю́ Тя, но сла́ви не лиша́ю самолюби́вия душі́ моєя́. Не пре́зри, Го́споди, покая́нія моєго́ і поми́луй м'я.","І нині: Со вся́кою ско́рбію, вели́кою і ма́лою, с оби́дами та́йними і печа́лію го́ркою прибіга́ю к Тебі́, Ма́ти Бо́жия, я́ко ча́до, от злих оби́димоє, вся приношу́ Тебі́, Ді́во Чи́стая, ча́я утіше́нія і Ма́тернія ми́лости."]},{"h":"Пісня 4","ps":["Ірмос: Мир із небитія́ воззва́вий / і персть земну́ю си́на Сві́та соді́лавий, / возведи́, Го́споди, / в ра́дость ду́шу мою́ / і утверди́ во і́стині Твоє́й / непоколеби́мо.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я!","К Тебі́ іду́, Го́споди, і утаї́ти замишля́ю, я́ко Ана́нія і Сапфи́ра, часть ні́кую душі́ моєя́ на діла́ пости́дная. При́зри на не́мощ мою́, і умертви́ та́йная моя́, і Сам яви́ м'я неосужде́нна пред Тобо́ю.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я!","Не приє́млеть душа́ моя́ утіше́нія: днем лицемі́ріє моє́ наставля́єть м'я, но́щію нече́стіє се́рдця моєго́ предстої́ть мні, отобою́ду печа́ль і поноше́ніє, ність мні прибі́жища; єди́н то́кмо плач утвержде́ніє і утіше́ніє моє́.","Слава: О́тче, возста́ви м'я, аз бо пред гріхо́м пресмика́юся ра́бськи; Си́не, ізведи́ м'я от мі́ста сту́днаго житія́ моєго́; Ду́ше Святи́й, освяти́ нощ стра́нствованія моєго́. Тро́йце непостижи́мая, да гряду́ к Тебі́ покая́нієм непоколеби́мим.","І нині: Богоро́дице ми́лостивая, го́ркая жи́зні сея́ услади́ слеза́ми покая́нія, окамене́нная ми́ра сего́ сокруше́нієм серде́чним ум'ягчи́. Вся бо мо́жеши моле́нієм неусипа́ющим, одесну́ю Христа́ Бо́га предстоя́щи."]},{"h":"Пісня 5","ps":["Ірмос: Плаче́вною но́щію / бе́здні небе́сній аз удиви́хся, / день істлі́вший пред собо́ю ви́дя, / достиго́х зарі́ і нача́ла со́лнечнаго, / і па́ки удиви́хся неудержи́мо / блиста́нію проро́чествующему.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я!","Я́ко Савл, неі́стовствую на Тя, Бо́же, ре́вностно гоню́ благода́ть Твою́ от себе́, но Ти Сам, Влади́ко, яви́ся се́рдцю моєму́ і осліпи́ о́ноє сві́том любве́ Твоєя́, і возглашу́ аз, окая́нний: что сотворю́, Го́споди?","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я!","Обличи́л м'я єси́, Го́споди, і преклони́хся пред Тобо́ю, стидо́м покри́стася о́чі мої́, да не у́зрить і нощ гріха́ моєго́; то́кмо Тебі́, Бо́же, печа́ль моя́. Не оста́ви мене́, см'яте́ннаго, посіти́ і спаси́ м'я.","Слава: Не гла́дом гла́дна душа́ моя́, не жа́ждою жа́ждеть се́рдце моє́, но о глаго́ліх Твої́х, Христе́, стражду́, о і́стині Твоє́й а́лчу. При́зри на не́мощ мою́, Го́споди, і пода́ждь ма́нну слове́с Твої́х.","І нині: Я́ко Свіща́ неугаси́мая, сле́зи те́плия на зе́млю іска́пающи, предстої́ши, Богоро́дице Пресвята́я, пред Царе́м Небе́сним, ті́мже і мні сві́та і тепла́ Твоєго́ да́руй на де́рзостноє се́рдце моє́."]},{"h":"Пісня 6","ps":["Ірмос: Пове́ржен на ло́же сле́зноє, / я́ко на дно морсько́є, / ка́ко воста́ти мні сме́ртному, / от мі́ста клевети́ і презрі́нія? / Го́споди, Бо́же мой, / воскреси́ м'я погиба́ющаго.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я!","Внегда́ і́скренній мой поноша́ше м'я, к Тебі́, Го́споди, душа́ моя́; а́ще у́бо і душа́ моя́ обетша́єть, уста́ призову́ть Влади́ку моєго́. Но ка́мо, Го́споди, пойду́, а́ще рече́ши: не вім тя? Земля́ не при́йметь м'я, не́бо не покри́єть м'я. Не отри́ни мене́, Бо́же, от лиця́ Твоєго́.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я!","Твоя́ от Твої́х приношу́ Ті, Спа́се, і велича́юся; тщу́ся, я́ко Си́мон волхв, Ду́ха Свята́го получи́ти за мзду моли́тв і діл мої́х. Прости́ м'я, Го́споди, і не пом'яни́ нече́стія моєго́.","Слава: Уста́ іспові́дують Тя, Бо́же, ті́ло уготовля́ється на по́двиги і страда́нія; душа́ же безмо́лвствуєть і гото́вить час отрече́нія моєго́; Го́споди, сокруши́ жесто́коє се́рдце моє́ і от сна нечу́вствія возста́ви м'я.","І нині: Сокруши́шася колі́на моя́ от но́щі печа́лі і забве́нія, но Ти не забу́ди мене́, Ма́ти Бо́жия, і возста́ви м'я унива́ющаго."]},{"h":"Кондак, глас 6","ps":["При бре́зі ста́ну, Го́споди, і воспла́чу, / я́ко зрю Тя по іну́ю страну́ вод непроходи́мих. / Обрати́ ко мні о́чі Твої́, Спа́се мой, / і поми́луй м'я."]},{"h":"Інший кондак, глас той самий","ps":["Глас Твой сли́шу, Го́споди, хла́да то́нка, / і не вім, отку́ду прихо́дить і ка́мо і́деть. / Отве́рзи, Христе́ Спа́се, слух се́рдця моєго́ / і наста́ви і спаси́ м'я."]},{"h":"Ікос","ps":["Поме́рче во мні Со́лнце Пра́вди, і при́йде на м'я хлад земни́й, гре́юся огне́м страсте́й мої́х, во дво́ріх чужди́х обріта́юся окая́нний. Взи́ди, Го́споди, на не́бо се́рдця моєго́ і день спасе́нія мні возвісти́."]},{"h":"Пісня 7","ps":["Ірмос: Вавило́нськую пещ о́гненную, / я́ко часть ма́лую / пла́мене беззако́нія людська́го, / о́троци невреди́мо пройдо́ша, / спасе́нія піснь воспіва́юще: / Бо́же оте́ць на́ших, благослове́н єси́.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я!","А́ще оста́влю Тя, Го́споди, Ти не оста́ви мене́ до конця́, потерпи́ безу́мства і беззако́нія моя́, покри́й срамоту́ і нече́стіє моє́. Єгда́ же в день печа́лі призову́ Тя, прості́ мене́ і не пом'яни́ непостоя́нства і двоєду́шія моєго́.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я!","Стижду́ся проси́ти Тебі́, Го́споди, ті́мже не і́мам слове́с к Тебі́, окая́нний, то́кмо ру́ці простира́ю і се́рдце, ми́лости прошу́ і хлі́ба насу́щнаго, я́ко ни́щий, отве́рженний і презре́нний.","Тебі́, Го́споди, іщу́ і не обріта́ю; я́ко сліпе́ць, іщу́ Тебі́ і путевожда́ не і́мам; при путі́ сіжу́ і ожида́ю, внегда́ мимоі́деши і усли́шиши моле́нія моя́.","Слава: Глаго́леши, Го́споди: толці́те, і отве́рзеться вам; но скорб, Влади́ко, связа́ ру́ці мої́, істо́рже му́жество із душі́ моєя́; при две́ріх сижу́ безмо́лвний. Отве́рзи мі, Го́споди, і при́зри на м'я, я́ко на разсла́бленнаго іногда́.","І нині: Почто́ сиро́тствую, Ма́тер імі́я ми́ра Влади́чицю? Почто́ смуща́юся во стра́нствіїх, дом наслі́довав Небе́сний? Пресвята́я Богоро́дице, Ма́ти Го́спода на́шего, доведи́ м'я го́рняго Оте́чества моєго́."]},{"h":"Пісня 8","ps":["Ірмос: Не ужасни́ся, душе́ моя́, / не устраши́ся, се́рдце моє́, / іскуше́нія о́гненнаго, / во очище́ніє посила́ємаго Го́сподем Милосе́рдим, / Єго́же стра́сті пом'яні́те, / Воскресе́ніє воспо́йте / і превозносі́те во вся ві́ки.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я!","Ві́рности сло́во вруча́ю Тебі́, Го́споди, но при пе́рвім стра́сі отриця́юся; ви́дя же Тя на поруга́ніє ведо́ма і обра́щшася, зря́ща мене́, помина́ю, сту́дний, кля́тви моя́, гряду́ вон і пла́чуся го́рко.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я!","І злочести́вий Іу́да любля́ше Ісу́са, оба́че кори́сти ра́ди; аз же немощни́й, та́яжде творю́, си́ли Боже́ственния любве́ не приє́млю, ізнемога́ю от но́щі тщесла́вія моєго́. Спаси́ м'я, Го́споди, да не впаду́ в бе́здну преда́тельства і поги́белі ві́чния.","Слава: Да́ри ісціле́ній от Бо́га приї́м і лю́дем расточа́я, сла́вою обогати́ся Іу́да; приноше́нія содержа́ і ми́лостиню подава́я, благодаре́ньми услажда́шеся; аз же, треокая́нний, тщесла́вія бога́тство скрив, страшу́ся єди́ножди Бо́га преда́ти. Спаси́ м'я, Го́споди, да возда́м Тебі́ Єди́ному сла́ву і благодаре́ніє.","І нині: Ску́дно хвале́ніє моє́ Твоєго́, Влади́чице, милосе́рдія, не́мощно покая́ніє моє́ о бе́здні гріхо́в мої́х; не ревну́ю о благодаре́нії, немотству́ю і в покая́нії. Не оста́ви мене́, см'яте́ннаго, Ма́ти Бо́жия, і спаси́ м'я."]},{"h":"Пісня 9","ps":["Ірмос: Усиновле́ніє моє́ чу́дноє / Ма́терію Госпо́днею / дерза́ю воспіва́ти, / но страшу́ся і трепе́щу сего́, / я́ко при Кресті́ би́вшаго. / Предста́ни мні, Ма́ти, в позо́рищі і сме́рті су́щему, / і спаси́ м'я сія́нієм ли́ка Твоєго́ Пречи́стаго.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я!","Не отвіща́єши мні нічесо́же, Го́споди, єгда́ вослі́д вопію́ Тебі́: помози́ мі, душа́ моя́ жесто́ко печа́лується. Обрати́ся же, Спа́се мой, я́ко не понесу́ оставле́нія сего́, і поми́луй м'я.","Приспів: Поми́луй м'я, Бо́же, поми́луй м'я!","Вім, Го́споди, вім, я́ко біє́ши вся́каго си́на, єго́же приє́млеши, но ропщу́, єгда́ зрю наказу́ємая ча́да Твоя́. Прости́ м'я, Го́споди, і терпі́ніє с благодаре́нієм да́руй.","Слава: Ра́зумом постига́ю, я́ко вінці́ і сла́ву гото́виши пла́чущим і уничиже́нним, но душа́ моя́ не утіша́ється ни́ні воздая́нієм гряду́щим; скорб об'є́млеть м'я, єгда́ зрю поноше́нія на і́скренняя моя́. Поми́луй м'я, Го́споди, і моли́тися научи́ за враги́ неоскудева́ющия.","І нині: Гні́ва огнь неугаси́мий сожига́єть м'я, горди́ні черв неусипа́яй сніда́єть се́рдце моє́. Спаси́ м'я, Пресвята́я Богоро́дице, от мук а́дових, дости́гших до душі́ моєя́."]},{"h":"Світилен","ps":["Сві́те мой Христе́ Спа́се, нощ житія́ моєго́, іді́же і со́лнце не просвіща́єть м'я, озари́ блиста́нієм Божества́ Твоєго́ і спаси́ м'я."]},{"h":"Молитва","ps":["Го́споди Ісу́се Христе́, Ти єси́ Хліб Живи́й, сше́дий с Небесе́, і яди́й Хліб сей не у́мреть і бу́деть жи́ти во ві́ки! Го́споди, Хліб сей єсть Плоть Твоя́, ю́же Ти отда́л єси́ за жизнь ми́ра, ті́мже і рекл єси́: яди́й Мою́ Плоть і пія́й Мою́ Кров і́мать живо́т ві́чний, і Аз воскрешу́ єго́ в послі́дній день. Та́ко і днесь гряде́м к Тебі́ по сло́ву Твоєму́. І ни́ні, іспиту́я нас, глаго́леши: не хо́щете ли і ви отити́? Ми же, я́ко Петр іногда́, зове́м Ті: Го́споди! Ко кому́ нам іти́? Ти і́маши глаго́ли жи́зні ві́чния, Ти – Христо́с, Син Бо́га Жива́го, Ти – А́льфа і Оме́га, нача́ло і коне́ць, Ти – Бог, Цар і Госпо́дь, і Твою́ держа́ву і милосе́рдіє сла́вим ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Канон розчулення до Пресвятої Богородиці, який читає жінка, що занапастила дитя в утробі своїй","e":"Canon of compunction to the Most Holy Theotokos, read by a woman who destroyed her child in the womb","secs":[{"h":"Глас 8. Пісня 1","ps":["Ірмос: Во́ду проше́д, я́ко су́шу, / і єги́петськаго зла ізбіжа́в, / ізра́їльтянин вопія́ше: / Ізба́вителю і Бо́гу на́шему пої́м.","Приспів: Пресвята́я Богоро́дице, спаси́ м'я.","Я́ко по су́ху прешла́ єси́ житія́ мирська́го пучи́ну, Чи́стая і Пресвята́я Ді́во, Ма́ти Го́спода Моєго́ і жи́зні Пода́теля. Аз же, волна́ми страсте́й мої́х потопля́єма і я́ко ка́мень на ви́ї іму́щи детоуби́йства гріх, молю́ Твою́ Боже́ственную бла́гость: при́зри на ду́шу мою́, во мрак отча́янія погруже́нную, і умоли́ о проще́нії мі согріше́ній тя́жких.","Приспів: Пресвята́я Богоро́дице, спаси́ м'я.","Упова́нія о́браз би́ша христия́ном роди́телі Твоя́, Ді́во, я́ко о своє́м безча́дії го́рко сле́зи пролива́юще, неотсту́пно моля́ху Бо́га, да пода́сть їм дитя́ благослове́нноє. Аз же, дні своя́ іждива́ющи і сласте́м потво́рствующи, о да́рі матери́нства ніколи́же радеіх.","Слава: Получи́вше от Бо́га увіре́ніє о дарова́нії Дще́ре Богоізбра́нния, святі́ї Іоаки́м і А́нна в храм ідя́ху і благодаре́ніє возда́ша. Аз же, в омраче́нії ума́ о ча́ді, во чре́ві моє́м зача́том, помишля́ющи, малоду́шію, осужде́нію і зло́бі предава́хся.","І нині: Іскупи́в Христо́с лю́ди Своя́, спасе́ їх от вла́сті дия́воли. Аз же, ча́до нерожде́нноє погуби́вши, самово́льне дия́волу преда́хся. Но заступи́ і умоли́ Си́на Твоєго́, Пречи́стая, і м'я взиска́ти, я́ко овча́ заблу́ждшеє."]},{"h":"Пісня 3","ps":["Ірмос: Небе́снаго кру́га, Верхотво́рче Го́споди, / і Це́ркве Зижди́телю, / Ти мене́ утверди́ в любві́ Твоє́й, / жела́ній кра́ю, ві́рних утвержде́ніє, / Єди́не Человіколю́бче.","Приспів: Пресвята́я Богоро́дице, спаси́ м'я.","А́ще не ми́лості Твоя́, о Богома́ти, безчи́сленния, ро́ду челові́чеському явле́нния, уни́ла би душа́ моя́ і во отча́янія пучи́ну пове́рглася би. Но, на предста́тельство Твоє́ упова́ющи, і́мам наде́жду спасе́ніє улучи́ти.","Приспів: Пресвята́я Богоро́дице, спаси́ м'я.","І́ноці оби́телі ні́кия нече́стієм досади́ша Си́ну Твоєму́, і ізрече́ Он суд Свой пра́ведний, во є́же погуби́ти я; ті́мже уста́ Ма́тере Своєя́ загради́, да не ізи́деть глас проше́нія. Но а́біє Пречи́стая ру́ку Христо́ву от уст Свої́х отведе́ дерзнове́нно, і преложи́ Госпо́дь суд Свой на ми́лость. Сіє́ воспомина́ющи, упова́ю і аз на Тя, Преблагослове́нная Ма́ти.","Слава: Я́ко Неупиваємая Ча́ша милосе́рдія на іко́ні предстає́ши і Си́на Твоєго́ во спасе́ніє дає́ши нам, Ма́ти Милосе́рдая. Сего́ ра́ди і аз, зло́ю тоско́ю і уни́нієм му́чима, припа́даю ко кра́ю ри́зи Твоєя́, моля́щи наде́жду спасе́нія мі пода́ти.","І нині: Рождество́м Си́на Твоєго́, Пресвята́я, род челові́чеський обнови́ся, я́ко но́ваго Ада́ма восприя́т. І мене́ покая́нієм па́ки обнови́ти умоли́, на сві́тлость Єго́ взира́ти не дерза́ющую."]},{"h":"Пісня 4","ps":["Ірмос: Усли́шах, Го́споди, / смотре́нія Твоєго́ та́їнство, / разумі́х діла́ Твоя́, / і просла́вих Твоє́ Божество́.","Приспів: Пресвята́я Богоро́дице, спаси́ м'я.","Я́ко упова́ніє крі́пкоє на Бо́га іму́щая, вість чу́дную о безсі́меннім зача́тії, ра́зум челові́ч превосходя́щую, смире́нно прия́ла єси́, Благослове́нная. Наста́ви і м'я, ка́ко по ві́рі жи́ти і на ми́лость Си́на Твоєго́ упова́ти, І́же воплоти́ся во є́же грі́шники спасти́ от сме́рти ві́чния.","Приспів: Пресвята́я Богоро́дице, спаси́ м'я.","Не усумни́лася єси́, Богома́ти, о промишле́нії Боже́ственнім, єгда́ Іо́сиф уві́де, я́ко і́маши во чре́ві ча́до і отпусти́ти Тя поми́сли, но па́че моли́твою ду́шу укрепля́ла єси́. Научи́ і м'я со упова́нієм моли́тися, Блага́я, на сме́ртний гріх детоуби́йства по скудоу́мію і жестокосе́рдію дерзну́вшую.","Слава: Христа́, Спа́са і Го́спода во верте́пі бе́днем родила́ єси́, Пречи́стая, смире́нно пелена́ми повила́ єси́ і в я́сліх положи́ла єси́. Ка́ко воззрю́ на Него́, окая́нная, я́ко ми́ра сего́ суєму́дрію послі́довавши, в малоду́шії і гні́ві погуби́х ча́до своє́?","І нині: Взира́ющи на Си́на Возлю́бленнаго, ко Кресту́ пригвожда́ємаго і му́ці предає́маго, рида́ла єси́, Богома́ти, го́рці. Ни́ні же, во сла́ві Небе́сній одесну́ю Єго́ сідя́щи, не оста́ви о заступле́нії Твоє́м грі́шники неотсту́пно взива́ющия."]},{"h":"Пісня 5","ps":["Ірмос: Просвіти́ нас повелі́нії Твої́ми, Го́споди, / і ми́шцею Твоє́ю висо́кою / Твой мир пода́ждь нам, / Человіколю́бче.","Приспів: Пресвята́я Богоро́дице, спаси́ м'я.","Си́на Твоєго́ от сме́рти ізба́ви А́нгела повелі́ніє, є́же во сні Іо́сиф получи́: воста́в поїми́ Отроча́ і Ма́тер Єго́, і біжи́ во Єги́пет. Аз же, сном гріхо́вним отягче́на, ча́до нерожде́нноє погуби́х, ра́зумом помраче́нна пребива́ющи.","Приспів: Пресвята́я Богоро́дице, спаси́ м'я.","Єгда́ разбо́йник лю́тий на путі́ пліни́ Тебі́ со Іо́сифом, сві́том сія́ше лице́ Си́на Твоєго́, Богома́ти. Ті́мже злоді́ї умили́шася і без вре́да отпусти́ша ви. Аз же ча́до своє́ ніколи́же поми́ловах і душегу́бцем сопричи́слихся.","Слава: Воскресе́нія світ да́же до а́да дости́же, отону́дуже Син Твой пра́ведники ізведе́. І ду́шу мою́, во тьмі отча́янія і страсте́й одержи́мую, умоли́ Єго́ озари́ти, да покая́нієм очи́щуся.","І нині: Звіздо́ю Рождества́ ведо́ми, волсви́ із Перси́ди ко Христу́ прийдо́ша; та́ко і аз, сія́нію ми́лости Твоєя́ неотсту́пно сле́дующи, покая́нієм тщу́ся дости́гнути спаси́тельнаго проще́нія."]},{"h":"Пісня 6","ps":["Ірмос: Моли́тву пролію́ ко Го́споду / і Тому́ возвіщу́ печа́лі моя́, / я́ко зол душа́ моя́ іспо́лнися / і живо́т мой а́ду прибли́жися, / і молю́ся, я́ко Іо́на: / от тлі, Бо́же, возведи́ м'я.","Приспів: Пресвята́я Богоро́дице, спаси́ м'я.","Стеня́ху ма́тері іуде́йськия о младе́нціх свої́х, неви́нно І́родом убіє́нних. Ті́мже і аз прошу́ Тя, Пречи́стая: даждь мі сле́зи опла́кати ча́да, я́же по неві́рію і зло́бі загу́блена би́ша, і Си́на Твоєго́ умоли́ всели́ти я на мі́сті поко́йні.","Приспів: Пресвята́я Богоро́дице, спаси́ м'я.","Во чре́ві ки́товем Іо́на пребива́ше, до́ндеже Бог єго́ поми́лова; аз же жестокосе́рдієм свої́м во чре́ві погуби́х ча́до, Бо́гом мі дарова́нноє. Ті́мже ни́ні молю́ Тя, Пресвята́я: із пучи́ни отча́янія м'я ізведи́.","Слава: Ча́до обрі́тши во чре́ві, ко пра́ведній Єлисаве́ті во срі́теніє, Богома́ти, востекла́ єси́, і взигра́ся Предте́ча во чре́ві тоя́, Си́на Бо́жия рожде́ніє предвозвіща́я. Аз же, во утро́бі іму́щи ча́до, сові́тники недо́брия вопроша́х, і́же нището́ю м'я устраша́юще, ко уби́йству го́ркому понужда́ху.","І нині: Чре́во Твоє́, Ді́во Богоізбра́нная, рая́ бисть вмісти́лище і Христа́ обита́лище. Аз же саму́ю себі́ мі́сто поги́белі соді́лах і страсте́й ігра́лище. О, моєго́ окая́нства го́ркаго, от него́же молю́ ізба́вити м'я!"]},{"h":"Кондак, глас 6","ps":["Не вві́ри м'я челові́чеському предста́тельству, / Пресвята́я Влади́чице, / но прийми́ моле́ніє раби́ Твоєя́: / скорб бо обдержи́ть м'я, / терпі́ти не могу́ де́монськаго стріля́нія, / покро́ва не і́мам, ніже́ гді прибі́гну, окая́нная, / всегда́ побіжда́єма, / і утіше́нія не і́мам, ра́зві Тебе́, Влади́чице ми́ра, / упова́ніє і предста́тельство ві́рних, / не пре́зри моле́ніє моє́, / поле́зно сотвори́."]},{"h":"Пісня 7","ps":["Ірмос: О́троци євре́йстії в пещі́ / попра́ша пла́мень дерзнове́нно / і на ро́су огнь преложи́ша, вопію́ще: / благослове́н єси́, Го́споди Бо́же, во ві́ки.","Приспів: Пресвята́я Богоро́дице, спаси́ м'я.","В пліне́нії вавило́нстім о́троци дерзнове́нно пла́мень пе́щі угаси́ша; та́кожде росо́ю ми́лости Твоєя́, Богома́ти, ороси́ ізсо́хшую юдо́ль душі́ моєя́, да потеку́ть по ней покая́нія рі́ки сле́зния.","Приспів: Пресвята́я Богоро́дице, спаси́ м'я.","Єгда́ растя́ше о́трок Ісу́с і мужа́ше, се́рдце Твоє́, Ма́ти Пресвята́я, разлу́ку ско́рую уві́де і ско́рбію отягчи́ся. Аз же ка́ко дерзну́ ма́тер нарещи́ся, ча́до бо своє́ не роди́х, ні взрасти́х, ніже́ поми́ловах, но із утро́би ізри́нух злі; а́ще же опла́кати єго́ восхощу́, не і́мам мі́ста, іді́же упоко́їся.","Слава: Пла́мене огня́ неугаса́ющаго досто́йна єсьм аз со блудники́ і уби́йці, я́же Ца́рства Бо́жия не наслі́дують. Но ми́лості Твоє́й, Ма́ти Бо́жия, вверя́ю ча́до, є́же погуби́х, моля́щи всели́ти єго́ в мі́сто упокоє́нія.","І нині: Ско́рбію се́рдце Твоє́ ору́жіє про́йде, Ді́во, позна́ла бо єси́, я́ко Син Твой Же́ртву за лю́ди Себі́ прино́сить. Аз же, ча́до моє́ погуби́вши, ніколи́же скорбі́х, і я́ко человікоуби́йця єсьм аз, не помишля́х."]},{"h":"Пісня 8","ps":["Ірмос: Царя́ Небе́снаго, / Єго́же пою́ть во́ї а́нгельстії, / хвалі́те і превозносі́те во вся ві́ки.","Приспів: Пресвята́я Богоро́дице, спаси́ м'я.","Єгда́ на бра́ці в Ка́ні Галиле́йстій вино́ істощи́ся, проше́ніє Твоє́, Ді́во Пречи́стая, чу́до сотвори́, Ісу́с бо по сло́ву Твоєму́ во́ду во вино́ претвори́. Ті́мже аз Тя смире́нно молю́ мо́лвити к Си́ну Твоєму́ сло́во о ча́ді моє́м убіє́ннем.","Приспів: Пресвята́я Богоро́дице, спаси́ м'я.","Ти єси́ Ма́ти Бо́жия, я́ко Сама́го Христа́ Го́спода носи́ла єси́, ди́вно родила́ єси́ і возрасти́ла єси́. Аз же не досто́йна ма́тер чад свої́х нарещи́ся, ті́мже честно́му покро́ву Твоєму́ вверя́ю їх.","Слава: Не рида́й Мене́, Ма́ти, зря́щи во гро́бі, Син Твой Тя утіша́ше, єгда́ со Креста́ сне́мши, слеза́ми Єго́ омива́ла єси́. Аз же Христо́ва ніколи́каго сло́ва до́браго ча́ю усли́шати, то́кмо по діло́м мої́м глас осужде́нія пра́веднаго. Ті́мже молю́ Тя: заступи́ і спаси́ м'я.","І нині: Всі ро́ди челові́честії чтуть Тя, Пресвята́я, і Си́на Твоєго́ прославля́ють, І́же на Кресті́ ви́ся, Ма́тернему попече́нію Твоєму́ вся наро́ди земни́я предаде́. Єго́же, Христа́ на́шего і Го́спода, о спасе́нії гре́шниць, ча́да своя́ во утро́бі погуби́вших, моли́ти не преста́й."]},{"h":"Пісня 9","ps":["Ірмос: Воі́стину Богоро́дицю / Тя іспові́дуєм, / спасе́ннії Тобо́ю, Ді́во Чи́стая, / с безпло́тними ли́ки Тя велича́юще.","Приспів: Пресвята́я Богоро́дице, спаси́ м'я.","Не то́кмо ма́терей всіх Досто́йнейшая і Сла́внійшая, но і Честні́йшая А́нгел і Херуви́м Преви́шшая єси́. Бу́ди і мні, заблу́ждшей, ми́лостивая Ма́ти, на́стави, вразуми́, поми́луй і спаси́ м'я.","Приспів: Пресвята́я Богоро́дице, спаси́ м'я.","Моля́ше Ти, Ді́во Чи́стая, Го́спода о проще́нії враго́в Єго́, ті́мже Савл гони́тель, пока́явся, апо́стол первоверхо́вний Па́вел соді́лася. О, си́ла ди́вная покая́нія! О, дерзнове́ніє ве́ліє пред Си́ном і Бо́гом Ма́тере Пречи́стия, і́мже гре́шницям окая́нним врата́ Небе́сная отверза́ються.","Слава: Со разбо́йником благоразу́мним і аз вопію́ к Си́ну Твоєму́: пом'яни́ м'я, Го́споди, во Ца́рствії Твоє́м. Ти же, Чи́стая Ді́во, красу́йся і лику́й, я́ко Син Твой із ме́ртвих воста́ і нам дарова́ Воскресе́ніє і жизнь ві́чную.","І нині: Єгда́ вре́м'я ісхо́да Твоєго́ наста́, Син Твой і Бог с Небесе́ соше́д, в ру́ці ду́шу Твою́ прия́т, ве́лію по́честь Ви́сшей А́нгелов творя́й. Аз же не преста́ну моли́ти Тя, Пречи́стая, да пом'яне́ши м'я во Ца́рствії Си́на Твоєго́, па́че же ча́да неви́нная, ма́терми убіє́нная."]},{"h":"Молитва","ps":["О, Преблагослове́нная Ма́ти і Сла́внійшая всіх дще́рей земни́х! К стопа́м Твої́м припа́даю і сле́зно молю́ от пото́ков благода́ті Твоєя́ ка́плю ми́лости мі пода́ти і ороси́ти се́рдце моє́, ізсо́хшеє страстьми́ і печа́льми. Просвіти́ луча́ми Твоєя́ бла́гости помраче́нний сме́ртними гріхми́ ум мой, да прийду́ в позна́ніє і́стинния ві́ри і уразумі́ю гріхопаде́ніє моє́, ча́до бо своє́ во утро́бі погуби́вши, не смі́ю взира́ти на Не́бо, но то́кмо о дарова́нії покая́нія дерза́ю проси́ти.","Неісче́тни ми́лості Твоя́, Богома́ти, ко грі́шному ро́ду челові́чеському, сего́ ра́ди молю́ Тя: я́коже дре́вле челові́ку ні́коєму, на ді́ло зло іду́щу, да́руй і мні неча́янную ра́дость обраще́нія і вразумле́нія Боже́ственнаго; я́коже одержи́мия разли́чними неду́ги, утоли́ і моя́ стра́сті неупива́ємою ча́шею Твоєго́ милосе́рдія; я́ко поги́бших Взиска́ніє, взищи́ і м'я, заблу́ждшую во грісі́х; я́коже от і́ноков неради́вих, отведи́ от мене́ суд пра́ведний і да́руй мі отра́ду і спаси́тельноє утіше́ніє, у Си́на Твоєго́ ми́лости іспроси́вши; утоли́ моя́ печа́лі, сле́зним покая́нієм болі́знующей душі́ моє́й утіше́ніє да́рующи; на смире́нієТвоєі Госпо́дь призрі́ і Ма́тер Си́на Своєго́ соді́ла Тя, ті́мже і м'я наста́ви, ка́ко со смире́нієм крест свой носи́ти і ми́лость Бо́жию тім обрісти́. Ра́зві Тебе́ не і́мам ні по́мощі, ніже́ наде́жди іни́я, Преблагослове́нная Ді́во Ма́ти, Неві́сто Неневі́стная, я́ко да сохрани́ши м'я і покри́єши покро́вом несконча́ємия Твоєя́ бла́гости во ві́ки віко́в. Амі́нь."]}],"notes":[]}];
export default D;
